def _find_installed_brave_executable():
    """Return an installed Brave browser executable without using automation bundles."""
    def _usable(path):
        if not path:
            return ''
        try:
            candidate = os.path.expandvars(os.path.expanduser(str(path).strip().strip('"')))
            if os.path.isdir(candidate):
                candidate = os.path.join(candidate, 'brave.exe' if os.name == 'nt' else 'brave')
            if 'brave-automation-tool' in os.path.normcase(candidate).lower():
                return ''
            if os.path.isfile(candidate):
                return os.path.abspath(candidate)
        except Exception:
            return ''
        return ''

    for env_key in ('VIDEO_PLAYER_BRAVE_PATH', 'BRAVE_PATH', 'BRAVE_EXE'):
        found = _usable(os.environ.get(env_key))
        if found:
            return found

    for name in ('brave.exe', 'brave'):
        found = _usable(shutil.which(name))
        if found:
            return found

    if os.name == 'nt':
        roots = [
            os.environ.get('LOCALAPPDATA'),
            os.environ.get('ProgramFiles'),
            os.environ.get('ProgramFiles(x86)'),
        ]
        relative_candidates = (
            ('BraveSoftware', 'Brave-Browser', 'Application', 'brave.exe'),
            ('BraveSoftware', 'Brave-Browser-Beta', 'Application', 'brave.exe'),
            ('BraveSoftware', 'Brave-Browser-Nightly', 'Application', 'brave.exe'),
            ('BraveSoftware', 'Brave-Browser-Dev', 'Application', 'brave.exe'),
        )
        for root in roots:
            if not root:
                continue
            for parts in relative_candidates:
                found = _usable(os.path.join(root, *parts))
                if found:
                    return found

        for root in roots:
            brave_root = os.path.join(root or '', 'BraveSoftware')
            if not os.path.isdir(brave_root):
                continue
            try:
                base_depth = os.path.abspath(brave_root).rstrip(os.sep).count(os.sep)
                for current, dirs, files in os.walk(brave_root):
                    depth = os.path.abspath(current).rstrip(os.sep).count(os.sep) - base_depth
                    if depth >= 5:
                        dirs[:] = []
                    for file_name in files:
                        if file_name.lower() == 'brave.exe':
                            found = _usable(os.path.join(current, file_name))
                            if found:
                                return found
            except Exception:
                continue
    return ''

def _find_installed_chromium_like_executable():
    """Return any installed Chromium-based browser usable for Playwright
    automation (Brave, then Chrome, then Edge), or '' if none is found.

    _find_installed_brave_executable() is kept Brave-only because it also
    backs the app's "open in Brave" action, where the specific browser
    matters. For headless/headed automation (clicking a play button and
    reading network/DOM state), any Chromium-based browser works exactly
    the same, so this widens the search — a person who has Chrome or Edge
    installed but not Brave specifically would otherwise silently get no
    browser at all and no visible indication why.
    """
    brave = _find_installed_brave_executable()
    if brave:
        return brave

    def _usable(path):
        if not path:
            return ''
        try:
            candidate = os.path.expandvars(os.path.expanduser(str(path).strip().strip('"')))
            if os.path.isfile(candidate):
                return os.path.abspath(candidate)
        except Exception:
            return ''
        return ''

    for env_key in ('VIDEO_PLAYER_CHROME_PATH', 'CHROME_PATH', 'VIDEO_PLAYER_EDGE_PATH', 'EDGE_PATH'):
        found = _usable(os.environ.get(env_key))
        if found:
            return found

    for name in (
        'chrome.exe', 'google-chrome', 'google-chrome-stable', 'chromium', 'chromium-browser',
        'msedge.exe', 'microsoft-edge', 'microsoft-edge-stable',
    ):
        found = _usable(shutil.which(name))
        if found:
            return found

    if os.name == 'nt':
        roots = [
            os.environ.get('LOCALAPPDATA'),
            os.environ.get('ProgramFiles'),
            os.environ.get('ProgramFiles(x86)'),
        ]
        relative_candidates = (
            ('Google', 'Chrome', 'Application', 'chrome.exe'),
            ('Google', 'Chrome Beta', 'Application', 'chrome.exe'),
            ('Microsoft', 'Edge', 'Application', 'msedge.exe'),
        )
        for root in roots:
            if not root:
                continue
            for parts in relative_candidates:
                found = _usable(os.path.join(root, *parts))
                if found:
                    return found
    elif sys.platform == 'darwin':
        for candidate in (
            '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
            '/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge',
        ):
            found = _usable(candidate)
            if found:
                return found

    return ''

if os.name == 'nt':
    # Prefer hardware-accelerated decode paths on Windows.
    # d3d11va is the modern Direct3D 11 VA-API path; dxva2 is the legacy fallback.
    # Setting these before QApplication is created ensures the FFmpeg backend picks
    # them up before it probes available decoders.
    os.environ.setdefault("QT_FFMPEG_DECODING_HW_DEVICE_TYPES", "d3d11va,dxva2")
    # Ask the multimedia backend to prefer the FFmpeg plugin which supports
    # hardware decode, rather than the Windows Media Foundation plugin which
    # does not expose hw surfaces to QVideoWidget on all driver versions.
    os.environ.setdefault("QT_MULTIMEDIA_PREFERRED_PLUGINS", "ffmpeg")
    # Disable OpenGL debug output that can stall the render thread on some drivers
    os.environ.setdefault("QSG_NO_DEPTH_BUFFER", "1")


