def _ftp_url_for_native_client(url_text):
    """Return an FTP URL in the form mpv/ffmpeg/ffprobe expect for RETR."""
    try:
        text = str(url_text or '')
        parsed = urlparse(text)
        if parsed.scheme.lower() != 'ftp':
            return text
        return urlunparse((
            parsed.scheme,
            parsed.netloc,
            unquote(parsed.path),
            parsed.params,
            parsed.query,
            parsed.fragment,
        ))
    except Exception:
        return str(url_text or '')

