# Best-effort, defensive DOM/state scraper for a loaded GoFile share page.
# Only reads what's already rendered in the user's own browsing session
# (no API calls) to surface a folder's file names/sizes/durations in our
# playlist. Tries several strategies since we don't have a guaranteed,
# stable selector for GoFile's page structure; any strategy that finds
# nothing is a no-op. Returns a JSON string of [{name, size, duration}, ...].
_GOFILE_FOLDER_SCRAPE_JS = r"""
(function() {
    function bytesToText(n) {
        if (typeof n !== 'number' || !isFinite(n)) return null;
        var units = ['B', 'KB', 'MB', 'GB', 'TB'];
        var i = 0;
        while (n >= 1024 && i < units.length - 1) { n /= 1024; i++; }
        return n.toFixed(1) + ' ' + units[i];
    }
    var results = [];
    var seen = {};
    function addItem(name, size, duration) {
        name = (name || '').toString().trim();
        if (!name || seen[name]) return;
        seen[name] = true;
        results.push({name: name, size: size || null, duration: duration || null});
    }
    var extPattern = '(mp4|mkv|mov|avi|webm|mp3|flac|wav|m4a)';

    // Strategy 1: common SPA hydration-state globals.
    try {
        var stateCandidates = [window.__NUXT__, window.__INITIAL_STATE__, window.__NEXT_DATA__];
        for (var i = 0; i < stateCandidates.length; i++) {
            var state = stateCandidates[i];
            if (!state) continue;
            var json = JSON.stringify(state);
            var re = new RegExp('"name"\\s*:\\s*"([^"]+\\.' + extPattern + ')"[^}]{0,300}?"size"\\s*:\\s*(\\d+)', 'gi');
            var m;
            while ((m = re.exec(json)) !== null) {
                addItem(m[1], bytesToText(parseInt(m[3], 10)), null);
            }
        }
    } catch (e) {}

    // Strategy 2: inline <script> JSON blobs containing name/size pairs.
    try {
        var scripts = document.querySelectorAll('script');
        for (var s = 0; s < scripts.length; s++) {
            var text = scripts[s].textContent || '';
            if (text.indexOf('"size"') === -1) continue;
            var re2 = new RegExp('"name"\\s*:\\s*"([^"]+\\.' + extPattern + ')"[^}]{0,300}?"size"\\s*:\\s*(\\d+)', 'gi');
            var m2;
            while ((m2 = re2.exec(text)) !== null) {
                addItem(m2[1], bytesToText(parseInt(m2[3], 10)), null);
            }
        }
    } catch (e) {}

    // Strategy 3: plain DOM text scan for a filename-looking string, then
    // look at its nearest row/container for a size- and duration-looking
    // string nearby.
    try {
        var extRe = new RegExp('[^\\s"\'<>]+\\.' + extPattern, 'i');
        var sizeRe = /\b(\d+(\.\d+)?\s?(B|KB|MB|GB|TB))\b/i;
        var durRe = /\b(\d{1,2}:)?\d{1,2}:\d{2}\b/;
        var all = document.querySelectorAll('body *');
        for (var j = 0; j < all.length; j++) {
            var el = all[j];
            if (el.children && el.children.length > 3) continue;
            var t = (el.textContent || '').trim();
            if (!t || t.length > 200) continue;
            var nameMatch = t.match(extRe);
            if (!nameMatch) continue;
            var container = el.closest('tr, li, div') || el;
            var ctext = container.textContent || '';
            var sizeMatch = ctext.match(sizeRe);
            var durMatch = ctext.match(durRe);
            addItem(nameMatch[0], sizeMatch ? sizeMatch[1] : null, durMatch ? durMatch[0] : null);
        }
    } catch (e) {}

    return JSON.stringify(results);
})();
"""

# Injected into the GoFile page BEFORE its own scripts run (DocumentCreation
# injection point), so it can wrap fetch()/XMLHttpRequest and capture the
# response of GoFile's own "/contents/<id>" API call — the exact same
# request their web client makes to list a folder. We don't call this API
# ourselves; we just read the response of the call the page already makes,
# which avoids the rate-limiting/blocking triggered by extra third-party
# metadata requests.
_GOFILE_CONTENTS_CAPTURE_JS = r"""
(function() {
    if (window.__gofileCaptureInstalled) return;
    window.__gofileCaptureInstalled = true;
    window.__gofileCapturedContents = [];

    function record(text) {
        try {
            var data = JSON.parse(text);
            window.__gofileCapturedContents.push(data);
        } catch (e) {}
    }

    var origFetch = window.fetch;
    if (origFetch) {
        window.fetch = function() {
            var input = arguments[0];
            var url = (typeof input === 'string') ? input : (input && input.url) || '';
            var result = origFetch.apply(this, arguments);
            if (url.indexOf('/contents/') !== -1) {
                result.then(function(resp) {
                    try {
                        resp.clone().text().then(record).catch(function() {});
                    } catch (e) {}
                }).catch(function() {});
            }
            return result;
        };
    }

    var OrigXHR = window.XMLHttpRequest;
    if (OrigXHR) {
        var origOpen = OrigXHR.prototype.open;
        OrigXHR.prototype.open = function(method, url) {
            this.__gofile_url = url;
            return origOpen.apply(this, arguments);
        };
        var origSend = OrigXHR.prototype.send;
        OrigXHR.prototype.send = function() {
            var xhr = this;
            if (xhr.__gofile_url && String(xhr.__gofile_url).indexOf('/contents/') !== -1) {
                xhr.addEventListener('load', function() {
                    record(xhr.responseText);
                });
            }
            return origSend.apply(this, arguments);
        };
    }
})();
"""

# Injected into the Eporner page BEFORE its own scripts run, for the same
# reason as the GoFile capture script above. Eporner's own player fetches
# its real source list from /xhr/video/<slug>?hash=... — we don't call this
# API ourselves, we just read the response the page's own JS already
# receives, then pick the best source out of it directly. This sidesteps
# whatever the <video> element itself ends up loading, which has been
# observed to sometimes be a short decoy/preview clip rather than the
# actual requested video (likely served when the page's ad break fails to
# render/complete in our embedded session).
_EPORNER_SOURCES_CAPTURE_JS = r"""
(function() {
    if (window.__epornerCaptureInstalled) return;
    window.__epornerCaptureInstalled = true;
    window.__epornerCapturedSources = [];

    function record(text) {
        try {
            var data = JSON.parse(text);
            window.__epornerCapturedSources.push(data);
        } catch (e) {}
    }

    function isSourcesUrl(url) {
        url = String(url || '');
        return url.indexOf('/xhr/video/') !== -1 && url.indexOf('heatmap') === -1;
    }

    var origFetch = window.fetch;
    if (origFetch) {
        window.fetch = function() {
            var input = arguments[0];
            var url = (typeof input === 'string') ? input : (input && input.url) || '';
            var result = origFetch.apply(this, arguments);
            if (isSourcesUrl(url)) {
                result.then(function(resp) {
                    try {
                        resp.clone().text().then(record).catch(function() {});
                    } catch (e) {}
                }).catch(function() {});
            }
            return result;
        };
    }

    var OrigXHR2 = window.XMLHttpRequest;
    if (OrigXHR2) {
        var origOpen2 = OrigXHR2.prototype.open;
        OrigXHR2.prototype.open = function(method, url) {
            this.__eporner_url = url;
            return origOpen2.apply(this, arguments);
        };
        var origSend2 = OrigXHR2.prototype.send;
        OrigXHR2.prototype.send = function() {
            var xhr = this;
            if (isSourcesUrl(xhr.__eporner_url)) {
                xhr.addEventListener('load', function() {
                    record(xhr.responseText);
                });
            }
            return origSend2.apply(this, arguments);
        };
    }
})();
"""

def natural_sort_key(s):
    """Sort strings with embedded numbers naturally: 1, 2, 10 instead of 1, 10, 2"""
    return [int(c) if c.isdigit() else c.lower() for c in re.split(r'(\d+)', str(s))]

TREE_SORT_ROLE = Qt.ItemDataRole(Qt.ItemDataRole.UserRole.value + 40)
PLAYLIST_SEARCH_ROLE = Qt.ItemDataRole(Qt.ItemDataRole.UserRole.value + 41)

_MPV_MODULE = None
_MPV_IMPORT_ERROR = None
_MPV_DLL_DIR_HANDLES = []


def _find_yt_dlp_executable():
    """Find the yt-dlp launcher so libmpv can use its native ytdl hook."""
    for name in ("yt-dlp", "yt-dlp.exe"):
        found = shutil.which(name)
        if found:
            return found
    scripts_dir = os.path.join(os.path.dirname(sys.executable), "Scripts")
    for name in ("yt-dlp.exe", "yt-dlp"):
        candidate = os.path.join(scripts_dir, name)
        if os.path.exists(candidate):
            return candidate
    return None


def _yt_dlp_command_prefix():
    exe = _find_yt_dlp_executable()
    if exe:
        return [exe]
    return [sys.executable, '-m', 'yt_dlp']


def _query_media_name_hint(url):
    """Extract a filename-like media hint from query params such as ?f=/path/video.mp4."""
    try:
        parsed = urlparse(str(url or '').strip())
    except Exception:
        return ''
    candidates = []
    for raw_params in (parsed.query, parsed.fragment):
        try:
            params = parse_qs(raw_params or '', keep_blank_values=True)
        except Exception:
            params = {}
        for key in ('f', 'file', 'filename', 'name', 'title', 'dn', 'download_name'):
            candidates.extend(params.get(key) or [])
    for candidate in candidates:
        value = html_unescape(str(candidate or '').replace('\\/', '/')).strip()
        if not value:
            continue
        for _ in range(2):
            decoded = unquote(value).strip()
            if decoded == value:
                break
            value = decoded
        if re.match(r'^https?://', value, re.IGNORECASE):
            try:
                value = urlparse(value).path
            except Exception:
                pass
        name = os.path.basename(value.replace('\\', '/')).strip().lower()
        if name:
            return name
    return ''


def _load_mpv_module():
    global _MPV_MODULE, _MPV_IMPORT_ERROR, _MPV_DLL_DIR_HANDLES
    if _MPV_MODULE is not None:
        return _MPV_MODULE
    if _MPV_IMPORT_ERROR is not None:
        return None

    base_dir = os.path.dirname(os.path.abspath(__file__))
    search_paths = [
        os.path.join(base_dir, "third_party", "mpv-dev"),
    ]

    program_files = os.environ.get("ProgramFiles")
    if program_files:
        search_paths.append(os.path.join(program_files, "MPV Player"))

    local_appdata = os.environ.get("LOCALAPPDATA")
    if local_appdata:
        search_paths.append(os.path.join(
            local_appdata,
            "Microsoft",
            "WinGet",
            "Packages",
            "mpv-player.mpv-CI.MSVC_Microsoft.Winget.Source_8wekyb3d8bbwe",
        ))

    seen = set()
    for path in search_paths:
        if not path or path in seen or not os.path.isdir(path):
            continue
        seen.add(path)

        dll_path = os.path.join(path, "libmpv-2.dll")
        exe_path = os.path.join(path, "mpv.exe")
        if not (os.path.exists(dll_path) or os.path.exists(exe_path)):
            continue

        try:
            if hasattr(os, "add_dll_directory") and os.path.exists(dll_path):
                _MPV_DLL_DIR_HANDLES.append(os.add_dll_directory(path))
        except Exception:
            pass

        current_path = os.environ.get("PATH", "")
        path_parts = current_path.split(os.pathsep) if current_path else []
        if path not in path_parts:
            os.environ["PATH"] = path + os.pathsep + current_path

    try:
        import mpv as mpv_module
    except Exception as exc:
        _MPV_IMPORT_ERROR = exc
        return None

    _MPV_MODULE = mpv_module
    return _MPV_MODULE

if _QT_WEBENGINE_AVAILABLE:
    class GofileWebEnginePage(QWebEnginePage):
        """QWebEnginePage that surfaces JS console output and render-process
        crashes, since Qt's loadFinished(False) alone gives no detail when
        the failure is code=0/NoErrorDomain (an aborted/cancelled load)."""

        def __init__(self, profile, parent=None, owner=None):
            super().__init__(profile, parent)
            self._owner = owner

        def javaScriptConsoleMessage(self, level, message, line_number, source_id):
            print(f'[GOFILE][WEB][JS] {source_id}:{line_number} {message}')

        def certificateError(self, error):
            print(f'[GOFILE][WEB][CERT] {error.description()} url={error.url().toString()}')
            return False  # keep default (reject) behavior, just log it

        def acceptNavigationRequest(self, url, nav_type, is_main_frame):
            # Chromium's bundled Qt WebEngine build usually lacks proprietary
            # video codecs (H.264/AAC), so its own <video> preview can fail
            # to play a file our libmpv backend handles fine. Rather than
            # let GoFile's page try (and fail) to preview the actual media
            # file in-browser, catch the navigation the moment it points at
            # a direct video/audio URL and hand it to the real player instead.
            if is_main_frame and self._owner is not None:
                path = url.path().lower()
                if path.endswith(VIDEO_EXTENSIONS + AUDIO_EXTENSIONS):
                    target = url.toString()
                    print(f'[GOFILE][WEB] Intercepted direct media link, handing off to player: {target}')
                    QTimer.singleShot(0, lambda u=target: self._owner._handle_gofile_media_url(u))
                    return False
            return super().acceptNavigationRequest(url, nav_type, is_main_frame)

    class GofileMediaRequestInterceptor(QWebEngineUrlRequestInterceptor):
        """Blocks the actual network request for a video/audio file on the
        GoFile page and hands the URL to the real mpv player instead.

        GoFile doesn't always do a full top-level navigation to the file —
        it often loads it straight into an inline <video> element, which
        acceptNavigationRequest never sees. interceptRequest() runs for
        every sub-resource request too (including media), so it catches
        that case as well. This callback fires on Qt WebEngine's own
        internal thread, so we only ever emit a signal here — the actual
        UI/player handoff happens on the GUI thread via the queued
        connection to _handle_gofile_media_url."""

        media_url_intercepted = pyqtSignal(str)
        contents_api_requested = pyqtSignal()
        eporner_sources_requested = pyqtSignal()

        def __init__(self, parent=None, owner=None):
            super().__init__(parent)
            self._owner = owner

        def interceptRequest(self, info):
            try:
                url = info.requestUrl()
                host = (url.host() or '').lower()
                # GoFile's page loads plenty of media that isn't the content
                # file itself — ad-network video banners, preview thumbnails,
                # tracking pixels, etc. Only intercept requests actually
                # going to a GoFile content-delivery host (their download
                # CDN subdomains look like store-na-phx-4.gofile.io); every
                # observed content link so far has come from a *.gofile.io
                # host, so anything else (a-ads.com, analytics domains, ...)
                # is left alone to load/fail on its own inside the page.
                if not ('gofile.io' in host or 'gofile.to' in host or 'eporner' in host):
                    return
                path = url.path().lower()
                if '/contents/' in path:
                    self.contents_api_requested.emit()
                if '/xhr/video/' in path and 'heatmap' not in path:
                    self.eporner_sources_requested.emit()
                resource_type = None
                try:
                    resource_type = info.resourceType()
                except Exception:
                    resource_type = None
                is_media_resource = (
                    resource_type == QWebEngineUrlRequestInfo.ResourceType.ResourceTypeMedia
                    if resource_type is not None else False
                )
                # Diagnostic: folder pages may preview video differently
                # (e.g. a JS player using fetch/XHR for the stream instead
                # of a plain <video src>). Log every non-trivial GoFile CDN
                # request so we can see the actual pattern when it happens.
                interesting_types = {'ResourceTypeMedia', 'ResourceTypeXhr', 'ResourceTypeFetch'}
                type_name = getattr(resource_type, 'name', str(resource_type))
                if type_name in interesting_types or path.endswith(VIDEO_EXTENSIONS + AUDIO_EXTENSIONS):
                    print(f'[GOFILE][WEB][REQ] type={type_name} url={url.toString()}')
                if is_media_resource or path.endswith(VIDEO_EXTENSIONS + AUDIO_EXTENSIONS):
                    info.block(True)
                    self.media_url_intercepted.emit(url.toString())
            except Exception as exc:
                print(f'[GOFILE][WEB][INTERCEPT] error: {exc}')

else:
    GofileWebEnginePage = None
    GofileMediaRequestInterceptor = None


class NaturalSortTreeWidgetItem(QTreeWidgetItem):
    def __lt__(self, other):
        self_sort = self.data(0, TREE_SORT_ROLE)
        other_sort = other.data(0, TREE_SORT_ROLE)
        left = self_sort if self_sort not in (None, "") else self.text(0)
        right = other_sort if other_sort not in (None, "") else other.text(0)
        return natural_sort_key(left) < natural_sort_key(right)


