# Background Image Loading Infrastructure
class BatchLoaderSignals(QObject):
    page_ready = pyqtSignal(int, QImage)   # index, image (one page decoded)
    all_done = pyqtSignal()                # all pages finished
    progress = pyqtSignal(int, int)        # loaded_count, total_count

class BatchImageLoader(QRunnable):
    """Loads images ONE AT A TIME on a background thread.
    Emits QImage (not QPixmap!) because QPixmap cannot be created
    on non-GUI threads. The main thread converts to QPixmap."""
    
    def __init__(self, image_sources, is_cbz=False, cbz_path=None, is_pdf=False, page_mode=False,
                 rpa_index=None, pdf_dark_level=0):
        super().__init__()
        self.setAutoDelete(False)   # prevent Qt GC while threads still running
        self.image_sources = image_sources
        self.is_cbz = is_cbz
        self.is_pdf = is_pdf
        try:
            self.pdf_dark_level = max(0, min(int(pdf_dark_level or 0), 3))
        except Exception:
            self.pdf_dark_level = 0
        self.cbz_path = cbz_path
        self.page_mode = page_mode  # True = serial decode (page mode), False = parallel (continuous)
        # rpa_index: {name: (offset, length)} — set when loading an RPA archive
        self.rpa_index = rpa_index or {}
        self.signals = BatchLoaderSignals()
        self._cancelled = False
        self._done = False          # guard: all_done emits exactly once

    def _apply_pdf_dark_level(self, qimg):
        level = int(getattr(self, 'pdf_dark_level', 0) or 0)
        if level <= 0 or qimg.isNull():
            return qimg

        qimg = qimg.convertToFormat(QImage.Format.Format_RGB32)
        qimg.invertPixels(QImage.InvertMode.InvertRgb)

        tone_levels = {
            1: (56.0, 0.66),
            2: (30.0, 0.80),
            3: (8.0, 0.94),
        }
        floor_value, scale = tone_levels.get(level, tone_levels[2])

        try:
            import numpy as np
            bits = qimg.bits()
            bits.setsize(qimg.sizeInBytes())
            arr = np.frombuffer(bits, dtype=np.uint8).reshape((qimg.height(), qimg.bytesPerLine()))
            rgb = arr[:, : qimg.width() * 4].reshape((qimg.height(), qimg.width(), 4))
            toned = np.clip(
                floor_value + rgb[:, :, :3].astype(np.float32) * scale,
                0,
                255,
            ).astype(np.uint8)
            rgb[:, :, :3] = toned
        except Exception:
            pass
        return qimg

    def cancel(self):
        self._cancelled = True

    def _emit_done(self):
        if not self._done:
            self._done = True
            try:
                self.signals.all_done.emit()
            except RuntimeError:
                pass

    def _decode_data(self, data):
        """Decode raw bytes to QImage using BGRX/BGRA for correct colors on Windows.
        Falls back to cv2 for WebP/formats Pillow can't handle."""
        try:
            from PIL import Image as PILImage
            import io
            pil_img = PILImage.open(io.BytesIO(data))
            pil_img.load()
            if pil_img.mode in ('RGBA', 'LA', 'PA'):
                pil_img = pil_img.convert('RGBA')
                raw = pil_img.tobytes('raw', 'BGRA')
                return QImage(raw, pil_img.width, pil_img.height,
                              pil_img.width * 4, QImage.Format.Format_ARGB32).copy()
            else:
                pil_img = pil_img.convert('RGB')
                raw = pil_img.tobytes('raw', 'BGRX')
                return QImage(raw, pil_img.width, pil_img.height,
                              pil_img.width * 4, QImage.Format.Format_RGB32).copy()
        except Exception as pil_err:
            try:
                import imageio, io as _io
                from PIL import Image as PILImage
                arr = imageio.imread(_io.BytesIO(data))
                pil_img = PILImage.fromarray(arr)
                if pil_img.mode in ('RGBA', 'LA', 'PA'):
                    pil_img = pil_img.convert('RGBA')
                    raw = pil_img.tobytes('raw', 'BGRA')
                    return QImage(raw, pil_img.width, pil_img.height,
                                  pil_img.width * 4, QImage.Format.Format_ARGB32).copy()
                else:
                    pil_img = pil_img.convert('RGB')
                    raw = pil_img.tobytes('raw', 'BGRX')
                    return QImage(raw, pil_img.width, pil_img.height,
                                  pil_img.width * 4, QImage.Format.Format_RGB32).copy()
            except Exception as iio_err:
                print(f"[_decode_data] pillow={pil_err} imageio={iio_err}")
                return QImage()

    @staticmethod
    def _decode_path(path):
        """Decode image to (w, h, stride, fmt, raw_bytes).
        Uses BGRX/BGRA byte order to match Qt's little-endian memory layout.
        Falls back to imageio for WebP/formats Pillow can't handle.
        """
        def _pil_to_result(pil_img):
            if pil_img.mode in ('RGBA', 'LA', 'PA'):
                pil_img = pil_img.convert('RGBA')
                raw = pil_img.tobytes('raw', 'BGRA')
                return (pil_img.width, pil_img.height, pil_img.width * 4, 'ARGB32', raw)
            else:
                pil_img = pil_img.convert('RGB')
                raw = pil_img.tobytes('raw', 'BGRX')
                return (pil_img.width, pil_img.height, pil_img.width * 4, 'RGB32', raw)

        # Try Pillow first
        try:
            from PIL import Image as PILImage
            import io
            with open(path, 'rb') as f:
                data = f.read()
            pil_img = PILImage.open(io.BytesIO(data))
            pil_img.load()
            return _pil_to_result(pil_img)
        except Exception as pil_err:
            # Pillow failed — try imageio (handles extended WebP)
            try:
                import imageio.v2 as imageio_v2
                from PIL import Image as PILImage
                arr = imageio_v2.imread(path)
                pil_img = PILImage.fromarray(arr)
                return _pil_to_result(pil_img)
            except Exception as iio_err:
                # Last resort: Qt's own QImageReader (supports all WebP variants)
                try:
                    from PyQt6.QtGui import QImageReader as _QIR
                    reader = _QIR(path)
                    qimg = reader.read()
                    if qimg.isNull():
                        raise ValueError(reader.errorString())
                    # Convert to RGB32/ARGB32 for BGRX byte layout
                    if qimg.hasAlphaChannel():
                        qimg = qimg.convertToFormat(QImage.Format.Format_ARGB32)
                        import ctypes
                        ptr = qimg.bits()
                        ptr.setsize(qimg.byteCount())
                        raw = bytes(ptr)
                        return (qimg.width(), qimg.height(), qimg.bytesPerLine(), 'ARGB32', raw)
                    else:
                        qimg = qimg.convertToFormat(QImage.Format.Format_RGB32)
                        import ctypes
                        ptr = qimg.bits()
                        ptr.setsize(qimg.byteCount())
                        raw = bytes(ptr)
                        return (qimg.width(), qimg.height(), qimg.bytesPerLine(), 'RGB32', raw)
                except Exception as qt_err:
                    print(f"[_decode_path] {path}: pillow={pil_err} imageio={iio_err} qt={qt_err}")
                    return None

    def run(self):
        z = None
        try:
            if self.is_cbz:
                import io
                from PIL import Image
                total = len(self.image_sources)
                for i, name in enumerate(self.image_sources):
                    if self._cancelled: break
                    try:
                        if self.rpa_index:
                            # RPA path: read bytes directly from the archive at the stored offset
                            offset, length = self.rpa_index[name]
                            with open(self.cbz_path, 'rb') as _f:
                                _f.seek(offset)
                                data = _f.read(length)
                        else:
                            # Normal CBZ/ZIP path
                            with zipfile.ZipFile(self.cbz_path, 'r') as z:
                                data = z.read(name)
                        qimg = self._decode_data(data)
                        if not qimg.isNull():
                            self.signals.page_ready.emit(i, qimg)
                    except Exception as _e:
                        print(f"[BatchImageLoader] page {i} ({name}): {_e}")
                    self.signals.progress.emit(i + 1, total)
            elif self.is_pdf:
                import fitz
                pdf_path = self.image_sources[0][0] # All sources share same path
                doc = fitz.open(pdf_path)
                total = len(self.image_sources)
                for i, (_, page_num) in enumerate(self.image_sources):
                    if self._cancelled: break
                    try:
                        page = doc.load_page(page_num)
                        # Render to image (using 2x scaling for better quality)
                        zoom = 2.0
                        mat = fitz.Matrix(zoom, zoom)
                        pix = page.get_pixmap(matrix=mat, alpha=False)
                        
                        # Convert fitz pixmap to QImage
                        # Format is RGB
                        img_format = QImage.Format.Format_RGB888
                        qimg = QImage(pix.samples, pix.width, pix.height, pix.stride, img_format)
                        # Make a copy because pix.samples might be freed
                        qimg = qimg.copy()
                        if not qimg.isNull():
                            qimg = self._apply_pdf_dark_level(qimg)
                        
                        if not qimg.isNull():
                            self.signals.page_ready.emit(i, qimg)
                    except Exception as e:
                        print(f"Error rendering PDF page {page_num}: {e}")
                    self.signals.progress.emit(i + 1, total)
                doc.close()
            else:
                total = len(self.image_sources)
                if self.page_mode:
                    # Serial: decode one at a time, emit immediately — keeps UI responsive
                    # and gives instant first-page display
                    for i, path in enumerate(self.image_sources):
                        if self._cancelled:
                            break
                        try:
                            with open(path, 'rb') as f:
                                data = f.read()
                            qimg = self._decode_data(data)
                            if not qimg.isNull():
                                self.signals.page_ready.emit(i, qimg)
                        except Exception:
                            pass
                        self.signals.progress.emit(i + 1, total)
                else:
                    # Parallel: Pillow decode in threads (releases GIL during I/O + decode)
                    import concurrent.futures, os
                    # Cap workers: fewer for large chapters to avoid RAM exhaustion.
                    # Each large manga page can be 5-20MB decoded — 12 threads * 200 pages
                    # can hit 2-4GB at once and cause thrashing.
                    cpu = os.cpu_count() or 4
                    # Cap workers by BOTH count AND estimated decoded size to avoid RAM
                    # exhaustion.  A 30-page chapter of 10 MB/page decoded = 300 MB+;
                    # blindly using 8 workers spikes to 2.4 GB and causes paging.
                    # Estimate ~8 MB decoded per page (safe lower-bound for HQ manga).
                    estimated_mb_per_page = 8
                    safe_ram_mb = 512  # max RAM to use for simultaneous decodes
                    ram_cap = max(1, safe_ram_mb // estimated_mb_per_page)

                    if total > 100:
                        workers = min(cpu, 4, ram_cap)   # large chapters: gentle
                    elif total > 50:
                        workers = min(cpu, 6, ram_cap)
                    else:
                        workers = min(cpu, 8, ram_cap)

                    def _load_one(args):
                        i, path = args
                        result = BatchImageLoader._decode_path(path)
                        return i, result  # result is (w,h,stride,fmt,raw) or None

                    done = 0
                    with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as ex:
                        futs = [ex.submit(_load_one, (i, p)) for i, p in enumerate(self.image_sources)]
                        for fut in concurrent.futures.as_completed(futs):
                            if self._cancelled:
                                break
                            i, result = fut.result()
                            if result is not None:
                                w, h, stride, fmt, raw = result
                                _fmt_map = {'RGB32': QImage.Format.Format_RGB32, 'ARGB32': QImage.Format.Format_ARGB32}
                                qimg = QImage(raw, w, h, stride, _fmt_map[fmt]).copy()
                                if not qimg.isNull():
                                    try:
                                        self.signals.page_ready.emit(i, qimg)
                                    except RuntimeError:
                                        break
                                else:
                                    print(f"[loader] page {i} → null QImage")
                            else:
                                print(f"[loader] page {i} → decode failed")
                            done += 1
                            try:
                                self.signals.progress.emit(done, total)
                            except RuntimeError:
                                break
            
            if not self._cancelled:
                self._emit_done()
        except Exception as e:
            print(f"[BatchImageLoader] run error: {e}")
            import traceback; traceback.print_exc()
            self._emit_done()
        finally:
            if z:
                try: z.close()
                except Exception: pass
class BatchPhoneImageLoader(QRunnable):
    """Sequential FTP loader for phone chapters."""

    def __init__(self, parent_player, remote_image_paths):
        super().__init__()
        self.setAutoDelete(False)   # keep alive until threads finish
        self.parent_player = parent_player
        self.remote_paths = remote_image_paths
        self.signals = BatchLoaderSignals()
        self._cancelled = False
        self._done = False

    def cancel(self):
        self._cancelled = True

    def _emit_done(self):
        if not self._done:
            self._done = True
            try:
                self.signals.all_done.emit()
            except RuntimeError:
                pass

    def _decode_data(self, data):
        image = QImage()
        if image.loadFromData(data):
            return image
        try:
            from PIL import Image as PILImage
            import io
            pil_img = PILImage.open(io.BytesIO(data))
            if pil_img.mode == 'RGB':
                raw = pil_img.tobytes('raw', 'RGB')
                return QImage(raw, pil_img.width, pil_img.height,
                              pil_img.width * 3, QImage.Format.Format_RGB888).copy()
            pil_img = pil_img.convert('RGBA')
            raw = pil_img.tobytes('raw', 'RGBA')
            return QImage(raw, pil_img.width, pil_img.height,
                         pil_img.width * 4, QImage.Format.Format_RGBA8888).copy()
        except Exception:
            return QImage()

    def _fetch_and_decode(self, i, path):
        """Fetch one file from phone, decode to QImage, then delete the temp file.
        Returns (i, QImage) or (i, None). No permanent disk storage used."""
        try:
            local_path = self.parent_player.request_phone_file_sync(path)
            if not local_path or not os.path.exists(local_path):
                return i, None
            with open(local_path, 'rb') as f:
                data = f.read()
            # Delete temp file immediately after reading into RAM
            try:
                if os.path.basename(local_path).startswith('.ftp_'):
                    os.remove(local_path)
            except Exception:
                pass
            return i, self._decode_data(data)
        except Exception as e:
            print(f"[phone loader] page {i} error: {e}")
            return i, None

    def run(self):
        total = len(self.remote_paths)
        try:
            # The FTP manager services queued downloads on a single worker thread
            # and single FTP connection. Submitting several page requests at once
            # only creates queue contention and makes later pages time out before
            # their transfer even starts, so fetch them in order here.
            for i, path in enumerate(self.remote_paths):
                if self._cancelled:
                    break
                _, qimg = self._fetch_and_decode(i, path)
                if qimg is not None and not qimg.isNull():
                    try:
                        self.signals.page_ready.emit(i, qimg)
                    except RuntimeError:
                        break
                try:
                    self.signals.progress.emit(i + 1, total)
                except RuntimeError:
                    break
        except Exception as e:
            print(f"[BatchPhoneImageLoader] run error: {e}")
        finally:
            self._emit_done()


# ── RPA extraction worker ─────────────────────────────────────────────────────
class RpaExtractorSignals(QObject):
    progress      = pyqtSignal(int, int, str)   # (done, total, current_filename)
    file_extracted = pyqtSignal(str)             # absolute path of each extracted file
    finished      = pyqtSignal(str, bool)        # (extract_dir, success)
    error         = pyqtSignal(str)              # human-readable error

class RpaExtractorWorker(QThread):
    """Background thread: extracts every entry in an .rpa archive to <rpa_stem>/."""

    def __init__(self, rpa_path, rpa_index, extract_dir, parent=None):
        super().__init__(parent)
        self.rpa_path    = rpa_path
        self.rpa_index   = rpa_index      # {name: (offset, length)}
        self.extract_dir = extract_dir    # target folder (may already exist)
        self.signals     = RpaExtractorSignals()
        self._cancelled  = False

    def cancel(self):
        self._cancelled = True

    def run(self):
        try:
            os.makedirs(self.extract_dir, exist_ok=True)
            names = sorted(self.rpa_index.keys(), key=natural_sort_key)
            total = len(names)
            with open(self.rpa_path, 'rb') as src:
                for done, name in enumerate(names):
                    if self._cancelled:
                        self.signals.finished.emit(self.extract_dir, False)
                        return
                    offset, length = self.rpa_index[name]
                    # Sanitise path separators (RPA may use forward or back slashes)
                    rel  = name.replace('\\', '/').lstrip('/')
                    dest = os.path.join(self.extract_dir, os.path.normpath(rel))
                    os.makedirs(os.path.dirname(dest), exist_ok=True)
                    try:
                        src.seek(offset)
                        data = src.read(length)
                        with open(dest, 'wb') as out:
                            out.write(data)
                        self.signals.file_extracted.emit(dest)
                    except Exception as _e:
                        print(f"[RPA extractor] {name}: {_e}")
                    self.signals.progress.emit(done + 1, total, os.path.basename(name))
            self.signals.finished.emit(self.extract_dir, True)
        except Exception as e:
            self.signals.error.emit(str(e))
            self.signals.finished.emit(self.extract_dir, False)
# ─────────────────────────────────────────────────────────────────────────────

class SubtitleOverlay(QWidget):
    """
    Full-window transparent overlay that renders the current subtitle via
    paintEvent.  Because the entire canvas is cleared on every repaint there
    are NO ghost pixels regardless of the video backend (Qt, MPV/D3D11, …).

    Drag support (edit-mode) is preserved: the user can drag the subtitle
    text block when subtitle_edit_mode is active, and the new y_offset is
    saved exactly as before.
    """

    def __init__(self, main_window, parent=None):
        super().__init__(parent)
        self.parent_player = main_window

        # Widget state
        self._text      = ""
        self._font_size = 24
        self._color     = QColor("#FFFF00")
        self._font_fam  = "Arial"
        self._show_bg   = True
        self._sub_x     = 0
        self._sub_y     = 0

        # Drag state
        self.is_dragging    = False
        self.drag_start_pos = None
        self.drag_start_widget_pos = None

        # WA_NoSystemBackground: Qt will not fill the widget background before
        # paintEvent, so our CompositionMode_Clear pass in paintEvent is the only
        # thing that clears the canvas — no ghost pixels, no opaque fill.
        # We deliberately do NOT use WA_TranslucentBackground: when the overlay is
        # parented to the top-level QMainWindow (required to paint over native HWND
        # video children on Windows/D3D11), WA_TranslucentBackground forces the
        # entire top-level window to an ARGB surface which suppresses painting of
        # sibling widgets such as the playlist panel.
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        self.setAttribute(Qt.WidgetAttribute.WA_NoSystemBackground, True)
        self.setAutoFillBackground(False)
        self.setMouseTracking(True)

    # ------------------------------------------------------------------
    # Public API (called by update_subtitle)
    # ------------------------------------------------------------------

    def set_subtitle(self, text, font_size, color_hex, font_fam, show_bg,
                     sub_x, sub_y):
        """Update subtitle content/position and repaint the whole overlay."""
        self._text      = text
        self._font_size = font_size
        self._color     = QColor(color_hex)
        self._font_fam  = font_fam
        self._show_bg   = show_bg
        self._sub_x     = int(sub_x)
        self._sub_y     = int(sub_y)
        total_w, total_h = self._measure_text_block()
        target = QRect(self._sub_x, self._sub_y, max(1, int(total_w)), max(1, int(total_h)))
        if self.geometry() != target:
            self.setGeometry(target)
        self.update()   # redraws entire transparent canvas — no ghost pixels

    def clear_subtitle(self):
        """Erase the subtitle (blank repaint)."""
        if self._text:
            self._text = ""
            self.update()

    def subtitle_rect(self):
        """Return the bounding QRect of the rendered subtitle block."""
        if not self._text:
            return QRect()
        return QRect(0, 0, self.width(), self.height())

    # ------------------------------------------------------------------
    # Painting — the whole overlay is redrawn every call
    # ------------------------------------------------------------------

    def _make_font(self):
        f = QFont(self._font_fam)
        f.setPointSize(self._font_size)
        f.setBold(True)
        return f

    def _measure_text_block(self):
        if not self._text:
            return 1, 1
        fm = QFontMetrics(self._make_font())
        lines = self._text.split('\n')
        max_w = max(fm.horizontalAdvance(line) for line in lines)
        line_h = fm.height()
        pad_h, pad_v = 10, 5
        return max_w + pad_h * 2, line_h * len(lines) + pad_v * 2

    def paintEvent(self, event):
        painter = QPainter(self)
        # Always clear to transparent first — prevents old subtitle frames
        # from ghosting/stacking in the backing store.
        painter.setCompositionMode(
            QPainter.CompositionMode.CompositionMode_Clear)
        painter.fillRect(self.rect(), Qt.GlobalColor.transparent)
        painter.setCompositionMode(
            QPainter.CompositionMode.CompositionMode_SourceOver)
        if not self._text:
            painter.end()
            return
        painter.setRenderHint(QPainter.RenderHint.TextAntialiasing)

        font = self._make_font()
        painter.setFont(font)
        fm   = painter.fontMetrics()

        lines     = self._text.split('\n')
        line_h    = fm.height()
        pad_h, pad_v = 10, 5
        total_h   = self.height()
        total_w   = self.width()
        rect      = QRect(0, 0, total_w, total_h)

        if self._show_bg:
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(QBrush(QColor(0, 0, 0, 180)))
            painter.drawRoundedRect(rect, 3, 3)

        painter.setPen(self._color)
        for i, line in enumerate(lines):
            lw     = fm.horizontalAdvance(line)
            text_x = (total_w - lw) // 2
            text_y = pad_v + fm.ascent() + i * line_h
            painter.drawText(text_x, text_y, line)

        painter.end()

    # ------------------------------------------------------------------
    # Drag support (subtitle edit mode)
    # ------------------------------------------------------------------

    def enable_drag(self, enabled):
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, not enabled)
        self.setCursor(Qt.CursorShape.SizeAllCursor if enabled else Qt.CursorShape.ArrowCursor)

    def mousePressEvent(self, event):
        p = self.parent_player
        if event.button() == Qt.MouseButton.LeftButton and p and p.subtitle_edit_mode:
            sr = self.subtitle_rect()
            if sr.contains(event.pos()):
                self.is_dragging    = True
                try:
                    self.drag_start_pos = event.globalPosition().toPoint()
                except Exception:
                    self.drag_start_pos = self.mapToGlobal(event.pos())
                self.drag_start_widget_pos = self.pos()
                event.accept()
                return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if self.is_dragging and self.drag_start_pos is not None and self.drag_start_widget_pos is not None:
            try:
                current_global = event.globalPosition().toPoint()
            except Exception:
                current_global = self.mapToGlobal(event.pos())
            new_tl = self.drag_start_widget_pos + (current_global - self.drag_start_pos)
            parent = self.parentWidget()
            parent_w = parent.width() if parent is not None else self.parent_player.width()
            parent_h = parent.height() if parent is not None else self.parent_player.height()
            nx = max(0, min(new_tl.x(), parent_w - self.width()))
            ny = max(0, min(new_tl.y(), parent_h - self.height()))
            self.move(nx, ny)
            self._sub_x = nx
            self._sub_y = ny
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton and self.is_dragging:
            self.is_dragging = False
            self.drag_start_pos = None
            self.drag_start_widget_pos = None
            p = self.parent_player
            if p:
                # subtitle_label is now parented to self (QMainWindow), so _sub_y is
                # in main-window coordinates.  Map the video bottom edge to the same
                # space to compute the correct y_offset.
                if hasattr(p, 'video_view') and p.video_view.isVisible():
                    vv        = p.video_view
                    vv_origin = vv.mapTo(p, vv.rect().topLeft())
                    vv_bottom = vv_origin.y() + vv.height()
                elif hasattr(p, 'media_stack') and p.media_stack.isVisible():
                    ms        = p.media_stack
                    ms_origin = ms.mapTo(p, ms.rect().topLeft())
                    vv_bottom = ms_origin.y() + ms.height()
                else:
                    vv_bottom = p.height()
                y_offset = vv_bottom - self._sub_y
                # Mark that the user has manually dragged, so resize (+/-) won't
                # snap the position back to the centred default.
                self._user_dragged = True
                p.settings['subtitle_y_offset'] = y_offset
                p.save_settings()
                p.show_osd(f"Subtitle Position Saved: {y_offset}px from bottom",
                           duration=1000)
                p._subtitle_render_signature = None
                p.update_subtitle()
            event.accept()
            return
        super().mouseReleaseEvent(event)


# Alias so existing references throughout the file continue to work
DraggableSubtitleLabel = SubtitleOverlay


class _FaviconPair:
    """R50: two favicons side by side — the jav SITE's icon next to the
    HOSter's icon (e.g. roshy + doodstream). Built by _get_favicon_icon
    when a playlist row is a jav-site page whose stream/mirrors live on
    a different hoster; the delegate paints first|second in two slots."""
    __slots__ = ('first', 'second')

    def __init__(self, first, second):
        self.first = first
        self.second = second


class NameColumnDelegate(QStyledItemDelegate):
    """Draws filename left-aligned plus compact markers in the Name column."""
    DOWNLOAD_BUTTON_WIDTH = 24
    DOWNLOAD_BUTTON_MARGIN = 5
    FOLDER_BADGE_WIDTH = 22
    TRAILING_ICON_GAP = 4
    FAVICON_WIDTH = 16
    FAVICON_PAIR_GAP = 3

    def __init__(self, player_ref, parent=None):
        super().__init__(parent)
        self._player = player_ref

    @classmethod
    def download_button_rect_for_option(cls, option):
        height = max(16, min(22, option.rect.height() - 4))
        width = cls.DOWNLOAD_BUTTON_WIDTH
        x = option.rect.right() - width - cls.DOWNLOAD_BUTTON_MARGIN
        y = option.rect.top() + max(2, (option.rect.height() - height) // 2)
        return QRect(x, y, width, height)

    @classmethod
    def folder_badge_rect_for_option(cls, option, has_download=False):
        height = max(16, min(22, option.rect.height() - 4))
        width = cls.FOLDER_BADGE_WIDTH
        x = option.rect.right() - width - cls.DOWNLOAD_BUTTON_MARGIN
        if has_download:
            x -= cls.DOWNLOAD_BUTTON_WIDTH + cls.TRAILING_ICON_GAP
        y = option.rect.top() + max(2, (option.rect.height() - height) // 2)
        return QRect(x, y, width, height)

    @classmethod
    def favicon_rect_for_option(cls, option, favicon_width, has_download=False, has_folder=False):
        """Sits immediately to the left of the folder/url badge (or the download
        button, if there's no folder badge) — i.e. far right, next to those markers."""
        height = min(cls.FAVICON_WIDTH, max(12, option.rect.height() - 6))
        width = favicon_width
        x = option.rect.right() - cls.DOWNLOAD_BUTTON_MARGIN
        if has_download:
            x -= cls.DOWNLOAD_BUTTON_WIDTH + cls.TRAILING_ICON_GAP
        if has_folder:
            x -= cls.FOLDER_BADGE_WIDTH + cls.TRAILING_ICON_GAP
        x -= width + cls.TRAILING_ICON_GAP
        y = option.rect.top() + max(2, (option.rect.height() - height) // 2)
        return QRect(x, y, width, height)

    @classmethod
    def _favicon_label_font(cls, option):
        font = QFont(option.font)
        font.setPointSize(max(6, font.pointSize() - 2))
        font.setBold(True)
        return font

    @classmethod
    def favicon_content_width(cls, option, favicon_value):
        """Width needed for the favicon slot: fixed for a real icon, measured
        (and capped) for a text fallback like 'filester'."""
        if isinstance(favicon_value, _FaviconPair):
            # R50: site + hoster icon side by side
            return cls.FAVICON_WIDTH * 2 + cls.FAVICON_PAIR_GAP
        if isinstance(favicon_value, str):
            fm = QFontMetrics(cls._favicon_label_font(option))
            return min(90, max(20, fm.horizontalAdvance(favicon_value) + 10))
        return cls.FAVICON_WIDTH

    @classmethod
    def _paint_favicon_slot(cls, painter, option, rect, value):
        if isinstance(value, QIcon):
            value.paint(painter, rect, Qt.AlignmentFlag.AlignCenter)
            return
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        painter.setFont(cls._favicon_label_font(option))
        painter.setPen(QColor("#9aa0a8"))
        painter.drawText(rect, Qt.AlignmentFlag.AlignCenter, str(value or '')[:8])

    def paint(self, painter, option, index):
        player = self._player
        if not player:
            super().paint(painter, option, index)
            return
        playlist = getattr(player, 'playlist', [])
        row = index.row()
        if row >= len(playlist):
            super().paint(painter, option, index)
            return
        file_path = playlist[row]
        is_remote = bool(getattr(player, '_is_remote_url', lambda _p: False)(file_path))
        folder_info = getattr(player, '_playlist_folder_badge_info', lambda *_a, **_k: None)(row, file_path)
        mappings = getattr(player, 'subtitle_mappings', {})

        has_sub = False
        if mappings:
            sub_key_func = getattr(player, '_sub_key', None)
            if sub_key_func:
                key = sub_key_func(file_path)
                has_sub = any(mappings.get(k) for k in (key, file_path, file_path.replace('\\', '/'), file_path.replace('/', '\\')))
            else:
                def norm(p):
                    return os.path.normpath(p).lower()
                fp_norm = norm(file_path)
                has_sub = any(v for k, v in mappings.items() if norm(k) == fp_norm)

        favicon_value = None
        if is_remote:
            get_favicon = getattr(player, '_get_favicon_icon', None)
            if get_favicon:
                favicon_value = get_favicon(file_path)
        favicon_width = self.favicon_content_width(option, favicon_value) if is_remote else 0

        opt = QStyleOptionViewItem(option)
        reserve = 0
        if is_remote:
            reserve += self.DOWNLOAD_BUTTON_WIDTH + (self.DOWNLOAD_BUTTON_MARGIN * 2)
            reserve += favicon_width + self.TRAILING_ICON_GAP
        if folder_info:
            reserve += self.FOLDER_BADGE_WIDTH + self.TRAILING_ICON_GAP
        if has_sub:
            reserve += 18
        if reserve:
            opt.rect = option.rect.adjusted(0, 0, -reserve, 0)
        super().paint(painter, opt, index)

        painter.save()
        if favicon_value:
            rect = self.favicon_rect_for_option(option, favicon_width, has_download=is_remote, has_folder=bool(folder_info))
            if isinstance(favicon_value, _FaviconPair):
                # Always two slots (site | hoster). A slot may still be a
                # short label while the real favicon loads.
                half = max(8, (rect.width() - self.FAVICON_PAIR_GAP) // 2)
                h = rect.height()
                self._paint_favicon_slot(
                    painter, option,
                    QRect(rect.left(), rect.top(), half, h),
                    favicon_value.first)
                self._paint_favicon_slot(
                    painter, option,
                    QRect(rect.left() + half + self.FAVICON_PAIR_GAP,
                          rect.top(), half, h),
                    favicon_value.second)
            elif isinstance(favicon_value, QIcon):
                favicon_value.paint(painter, rect, Qt.AlignmentFlag.AlignCenter)
            else:
                self._paint_favicon_slot(painter, option, rect, favicon_value)
        if is_remote:
            rect = self.download_button_rect_for_option(option)
            selected = bool(option.state & QStyle.StateFlag.State_Selected)
            painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            painter.setPen(QPen(QColor("#6aa9ff" if selected else "#4b87c8"), 1))
            painter.setBrush(QBrush(QColor(35, 70, 105, 190) if selected else QColor(42, 45, 48, 210)))
            painter.drawRoundedRect(rect, 4, 4)
            font = painter.font()
            font.setBold(True)
            painter.setFont(font)
            painter.setPen(QColor("#ffffff" if selected else "#8fc7ff"))
            painter.drawText(rect, Qt.AlignmentFlag.AlignCenter, "↓")
        if folder_info:
            rect = self.folder_badge_rect_for_option(option, has_download=is_remote)
            selected = bool(option.state & QStyle.StateFlag.State_Selected)
            painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            badge_kind = str((folder_info or {}).get('kind') or 'folder')
            if badge_kind == 'folder':
                painter.setPen(QPen(QColor("#b99854" if selected else "#7d6540"), 1))
                painter.setBrush(QBrush(QColor(98, 74, 30, 210) if selected else QColor(58, 50, 36, 210)))
                painter.drawRoundedRect(rect, 4, 4)
                icon = QApplication.style().standardIcon(QStyle.StandardPixmap.SP_DirIcon)
                pixmap = icon.pixmap(max(12, rect.width() - 6), max(12, rect.height() - 6))
                if not pixmap.isNull():
                    px = rect.x() + max(0, (rect.width() - pixmap.width()) // 2)
                    py = rect.y() + max(0, (rect.height() - pixmap.height()) // 2)
                    painter.drawPixmap(px, py, pixmap)
            else:
                palette = {
                    'phone': ("#5fbda8", "#1f5e55", "#dffcf6"),
                    'usb': ("#d0a44f", "#684f1d", "#fff0c6"),
                    'pc': ("#7da7d9", "#254e7a", "#e2f0ff"),
                    'url': ("#a38bd8", "#46316f", "#eee7ff"),
                }.get(badge_kind, ("#8a8f98", "#3f444b", "#f1f3f5"))
                border, fill, text_color = palette
                painter.setPen(QPen(QColor(border), 1))
                painter.setBrush(QBrush(QColor(fill)))
                painter.drawRoundedRect(rect, 4, 4)
                font = painter.font()
                font.setBold(True)
                font.setPointSize(max(7, font.pointSize() - 1))
                painter.setFont(font)
                painter.setPen(QColor(text_color))
                painter.drawText(rect, Qt.AlignmentFlag.AlignCenter, str(folder_info.get('label') or '').upper())
        if has_sub:
            font = painter.font()
            font.setBold(True)
            painter.setFont(font)
            painter.setPen(QColor("#4fc3f7"))
            right_pad = 6
            if is_remote:
                right_pad += self.DOWNLOAD_BUTTON_WIDTH + (self.DOWNLOAD_BUTTON_MARGIN * 2)
                right_pad += favicon_width + self.TRAILING_ICON_GAP
            if folder_info:
                right_pad += self.FOLDER_BADGE_WIDTH + self.TRAILING_ICON_GAP
            rect = option.rect.adjusted(0, 0, -right_pad, 0)
            painter.drawText(rect, Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter, "S")
        painter.restore()

class SourceFilterComboBox(QComboBox):
    sourceSelectionChanged = pyqtSignal()
    SOURCE_ITEMS = (('phone', 'Phone'), ('usb', 'USB'), ('pc', 'PC'), ('url', 'URL'))

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setEditable(True)
        self.setInsertPolicy(QComboBox.InsertPolicy.NoInsert)
        self.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        line_edit = self.lineEdit()
        if line_edit is not None:
            line_edit.setReadOnly(True)
            line_edit.setFocusPolicy(Qt.FocusPolicy.NoFocus)
            line_edit.setAlignment(Qt.AlignmentFlag.AlignCenter)
        for key, label in self.SOURCE_ITEMS:
            self.addItem(label, key)
            row = self.count() - 1
            self.setItemData(row, Qt.CheckState.Checked, Qt.ItemDataRole.CheckStateRole)
            item = self.model().item(row, 0) if hasattr(self.model(), 'item') else None
            if item is not None:
                item.setFlags(item.flags() | Qt.ItemFlag.ItemIsUserCheckable | Qt.ItemFlag.ItemIsEnabled)
        self.view().pressed.connect(self._toggle_source_index)
        self.update_display_text()

    def _state_is_checked(self, state):
        checked_value = getattr(Qt.CheckState.Checked, 'value', None)
        return state == Qt.CheckState.Checked or (checked_value is not None and state == checked_value)

    def checked_keys(self):
        checked = set()
        for row in range(self.count()):
            state = self.itemData(row, Qt.ItemDataRole.CheckStateRole)
            if self._state_is_checked(state):
                checked.add(str(self.itemData(row, Qt.ItemDataRole.UserRole) or ''))
        checked.discard('')
        return checked

    def set_checked_keys(self, keys):
        keys = set(keys or [])
        self.blockSignals(True)
        try:
            for row in range(self.count()):
                key = str(self.itemData(row, Qt.ItemDataRole.UserRole) or '')
                state = Qt.CheckState.Checked if key in keys else Qt.CheckState.Unchecked
                self.setItemData(row, state, Qt.ItemDataRole.CheckStateRole)
        finally:
            self.blockSignals(False)
        self.update_display_text()

    def update_display_text(self):
        selected_labels = []
        for row in range(self.count()):
            if self._state_is_checked(self.itemData(row, Qt.ItemDataRole.CheckStateRole)):
                selected_labels.append(self.itemText(row))
        if len(selected_labels) == self.count():
            text = "Source"
        elif selected_labels:
            text = "Source: " + ", ".join(selected_labels)
        else:
            text = "Source: None"
        line_edit = self.lineEdit()
        if line_edit is not None:
            line_edit.setText(text)
        self.setToolTip(text)

    def _toggle_source_index(self, index):
        if not index.isValid():
            return
        row = index.row()
        current = self.itemData(row, Qt.ItemDataRole.CheckStateRole)
        next_state = Qt.CheckState.Unchecked if self._state_is_checked(current) else Qt.CheckState.Checked
        self.setItemData(row, next_state, Qt.ItemDataRole.CheckStateRole)
        self.update_display_text()
        self.sourceSelectionChanged.emit()


class SourceFilterHeaderView(QHeaderView):
    def __init__(self, orientation, parent=None):
        super().__init__(orientation, parent)
        self.source_filter_provider = None
        self.setMouseTracking(True)
        self.viewport().setMouseTracking(True)

    def paintSection(self, painter, rect, logical_index):
        super().paintSection(painter, rect, logical_index)
        provider = getattr(self, 'source_filter_provider', None)
        if logical_index != 0 or provider is None:
            return
        try:
            combo_rect = provider._source_filter_header_rect()
        except Exception:
            return
        if combo_rect.isNull() or not rect.intersects(combo_rect):
            return

        painter.save()
        try:
            hovered = bool(getattr(provider, '_source_filter_header_hover', False))
            pressed = bool(getattr(provider, '_source_filter_header_pressed', False))
            bg = QColor("#2f78c2") if pressed else (QColor("#3a8ee6") if hovered else QColor("#333333"))
            border = QColor("#9ec9ff") if hovered else QColor("#666666")
            text_color = QColor("#ffffff") if hovered else QColor("#dddddd")

            painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            box = QRectF(combo_rect.adjusted(0, 3, -1, -3))
            painter.setPen(QPen(border, 1))
            painter.setBrush(QBrush(bg))
            painter.drawRoundedRect(box, 3, 3)

            font = painter.font()
            font.setBold(False)
            if font.pointSize() > 0:
                font.setPointSize(max(8, font.pointSize() - 1))
            painter.setFont(font)
            painter.setPen(text_color)
            text_rect = combo_rect.adjusted(8, 1, -22, -1)
            painter.drawText(text_rect, Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft, provider._source_filter_display_text())
            arrow_rect = QRect(combo_rect.right() - 20, combo_rect.top(), 16, combo_rect.height())
            painter.drawText(arrow_rect, Qt.AlignmentFlag.AlignCenter, "▼")
        finally:
            painter.restore()


class DraggableTableWidget(QTableWidget):
    """Custom table widget with mouse-based drag-drop"""
    def __init__(self, parent=None):
        super().__init__(parent)
        self.parent_player = parent
        self.drag_start_row = None
        self.drag_selected_rows = []
        self.drop_indicator_row = -1
        
        # Auto-scroll timer for drag operations
        self.auto_scroll_timer = QTimer(self)
        self.auto_scroll_timer.timeout.connect(self.auto_scroll)
        self.auto_scroll_direction = 0  # -1 for up, 1 for down, 0 for none  # Row to show drop indicator
        self.auto_scroll_interval_ms = 420
        self.auto_scroll_step_rows = 1
        self.setDragEnabled(False)
        self.setAcceptDrops(True)
        self.setSelectionBehavior(QTableWidget.SelectionBehavior.SelectRows)
        # Enable multi-selection with Ctrl and Shift
        self.setSelectionMode(QTableWidget.SelectionMode.ExtendedSelection)
        # Enable context menu
        self.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.customContextMenuRequested.connect(self.show_context_menu)
    
    def show_context_menu(self, position):
        """Show right-click context menu"""
        if not self.parent_player:
            return
        pp = self.parent_player
        viewport = self.viewport()
        global_pos = viewport.mapToGlobal(position) if viewport is not None else self.mapToGlobal(position)

        selected_rows = sorted(set(idx.row() for idx in self.selectedIndexes()))
        clicked_row = self.rowAt(position.y())
        # If click is on an unselected row, treat just that row as selection
        if clicked_row >= 0 and clicked_row not in selected_rows:
            self.selectRow(clicked_row)
            selected_rows = [clicked_row]

        menu = QMenu(self)
        if hasattr(pp, '_context_menu_stylesheet'):
            menu.setStyleSheet(pp._context_menu_stylesheet())
        else:
            menu.setStyleSheet(
                "QMenu { background:#2b2b2b; color:#ddd; border:1px solid #555; padding:2px 0px; }"
                "QMenu::item { padding:6px 22px 6px 24px; background:transparent; }"
                "QMenu::item:selected { background:#444; }"
                "QMenu::separator { background:#444; height:1px; margin:4px 10px; }"
            )

        if hasattr(pp, '_populate_playlist_context_menu'):
            pp._populate_playlist_context_menu(menu, selected_rows)
            fallback = None
            if pp._is_app_fullscreen() and hasattr(pp, '_show_fullscreen_playlist_overlay_menu'):
                target_pos = QPoint(global_pos)
                fallback = lambda gp=target_pos, rows=list(selected_rows): pp._show_fullscreen_playlist_overlay_menu(gp, rows)
            if hasattr(pp, '_exec_popup_menu'):
                pp._exec_popup_menu(menu, global_pos, fullscreen_fallback=fallback)
            else:
                menu.exec(global_pos)
            return

        add_files_action = menu.addAction("Add Files...")
        add_files_action.triggered.connect(self.parent_player.add_files_to_playlist)

        if selected_rows:
            menu.addSeparator()
            n = len(selected_rows)
            label = f"{n} file{'s' if n > 1 else ''}"

            # Determine mixed/all-marked state for smart label
            selected_paths = [
                pp.playlist[r] for r in selected_rows
                if 0 <= r < len(pp.playlist)
            ]
            all_marked   = all(pp.is_seen(pp.playlist[r]) for r in selected_rows if r < len(pp.playlist))
            all_unmarked = all(not pp.is_seen(pp.playlist[r]) for r in selected_rows if r < len(pp.playlist))

            if all_unmarked:
                mark_action = menu.addAction(f"✓ Mark {label} as SEEN")
                mark_action.triggered.connect(lambda: pp.bulk_mark_videos(selected_rows, mark=True))
            elif all_marked:
                unmark_action = menu.addAction(f"✗ Unmark {label}")
                unmark_action.triggered.connect(lambda: pp.bulk_mark_videos(selected_rows, mark=False))
            else:
                # Mixed: offer smart toggle + force mark/unmark all
                smart_action = menu.addAction(f"⇄ Toggle (mark unseen, unmark seen)")
                smart_action.triggered.connect(lambda: pp.bulk_mark_videos(selected_rows, mark=None))
                menu.addSeparator()
                mark_action = menu.addAction(f"✓ Mark ALL {label} as SEEN")
                mark_action.triggered.connect(lambda: pp.bulk_mark_videos(selected_rows, mark=True))
                unmark_action = menu.addAction(f"✗ Unmark ALL {label}")
                unmark_action.triggered.connect(lambda: pp.bulk_mark_videos(selected_rows, mark=False))

            menu.addSeparator()
            if len(selected_paths) == 1:
                reveal_action = menu.addAction("Show in Explorer")
                reveal_action.triggered.connect(
                    lambda checked=False, path=selected_paths[0]: pp.reveal_in_file_manager(path)
                )
            delete_action = menu.addAction(f"🗑 Delete {label} (to Trash)")
            delete_action.triggered.connect(lambda: pp.bulk_delete_videos(selected_rows))

        pp.populate_restore_from_trash_menu(menu)
        menu.addSeparator()

        save_action = menu.addAction("Save Playlist")
        save_action.triggered.connect(self.parent_player.save_playlist)

        load_action = menu.addAction("Load Playlist")
        load_action.triggered.connect(self.parent_player.load_playlist)

        relink_action = menu.addAction("Relink Missing Files")
        relink_action.triggered.connect(self.parent_player.relink_missing_playlist_files)

        menu.addSeparator()

        # Recent Files submenu
        recent_files_menu = menu.addMenu("Recent Files")
        if hasattr(self.parent_player, 'recent_files') and self.parent_player.recent_files:
            for file_path in self.parent_player.recent_files[:10]:
                action = recent_files_menu.addAction(self.parent_player._get_playlist_name_for_path(file_path))
                action.setData(file_path)
                action.triggered.connect(lambda checked, path=file_path: self.parent_player.load_recent_file(path))
        else:
            no_files_action = recent_files_menu.addAction("No recent files")
            no_files_action.setEnabled(False)

        # Recent Playlists submenu
        recent_playlists_menu = menu.addMenu("Recent Playlists")
        if hasattr(self.parent_player, 'recent_playlists') and self.parent_player.recent_playlists:
            for file_path in self.parent_player.recent_playlists[:10]:
                action = recent_playlists_menu.addAction(os.path.basename(file_path))
                action.setData(file_path)
                action.triggered.connect(lambda checked, path=file_path: self.parent_player.load_recent_playlist(path))
        else:
            no_playlists_action = recent_playlists_menu.addAction("No recent playlists")
            no_playlists_action.setEnabled(False)

        menu.addSeparator()

        analyze_action = menu.addAction("Analyze Folder")
        analyze_action.triggered.connect(self.parent_player.analyze_folder_quality)

        global_pos = self.mapToGlobal(position)
        if hasattr(pp, '_exec_popup_menu'):
            fallback = None
            if pp._is_app_fullscreen():
                target_pos = QPoint(global_pos)
                fallback = lambda gp=target_pos, rows=list(selected_rows): pp._show_fullscreen_playlist_overlay_menu(gp, rows)
            pp._exec_popup_menu(menu, global_pos, fullscreen_fallback=fallback)
        else:
            menu.exec(global_pos)

    # ── External file/playlist drag-drop onto the playlist panel ─────────────
    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            event.accept()
        else:
            event.ignore()

    def dragMoveEvent(self, event):
        if event.mimeData().hasUrls():
            event.accept()
        else:
            event.ignore()

    def dropEvent(self, event):
        """Route OS-level file drops (including .agpl playlists) to the player."""
        if event.mimeData().hasUrls():
            files = [u.toLocalFile() or u.toString() for u in event.mimeData().urls()]
            if self.parent_player and files:
                self.parent_player.handle_dropped_files(files)
                event.accept()
                return
        event.ignore()

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            clicked_row = self.rowAt(event.position().toPoint().y())
            
            # Capture currently selected rows BEFORE super() changes selection
            selected_rows = sorted(set(index.row() for index in self.selectedIndexes()))
            
            # Only start drag if clicking on an already selected row (without modifiers)
            if (clicked_row >= 0 and 
                clicked_row in selected_rows and 
                not (event.modifiers() & (Qt.KeyboardModifier.ControlModifier | Qt.KeyboardModifier.ShiftModifier))):
                
                # Starting a potential drag operation — record press position
                self.drag_start_row = clicked_row
                self.drag_selected_rows = selected_rows if len(selected_rows) > 0 else [clicked_row]
                self._drag_press_pos = event.position().toPoint()
                self._drag_actually_dragged = False
                
                # Don't call super() here so the multi-selection is preserved
                return
        
        # Normal click behavior (selection changes)
        super().mousePressEvent(event)
        self.drag_start_row = None
        self.drag_selected_rows = []
        self._drag_press_pos = None
        self._drag_actually_dragged = False
    
    def mouseMoveEvent(self, event):
        if event.buttons() & Qt.MouseButton.LeftButton and self.drag_start_row is not None:
            # Only consider it a real drag after moving a minimum distance
            if not getattr(self, '_drag_actually_dragged', False):
                press_pos = getattr(self, '_drag_press_pos', None)
                if press_pos is not None:
                    delta = event.position().toPoint() - press_pos
                    if (abs(delta.x()) + abs(delta.y())) < 6:
                        return  # Not yet moved enough — wait
                self._drag_actually_dragged = True
            # Visual feedback - change cursor only
            self.setCursor(Qt.CursorShape.ClosedHandCursor)
            
            # Update drop indicator
            current_row = self.rowAt(event.position().toPoint().y())
            if current_row >= 0:
                self.drop_indicator_row = current_row
            else:
                # If below all rows, indicate drop at end
                self.drop_indicator_row = self.rowCount()
            
            # Auto-scroll when near edges
            edge_threshold = 38  # pixels from edge to trigger scroll
            mouse_y = event.position().toPoint().y()
            viewport_height = self.viewport().height()
            
            if mouse_y < edge_threshold:
                # Near top edge - scroll up
                self.auto_scroll_direction = -1
                if not self.auto_scroll_timer.isActive():
                    self.auto_scroll_timer.start(self.auto_scroll_interval_ms)
            elif mouse_y > viewport_height - edge_threshold:
                # Near bottom edge - scroll down
                self.auto_scroll_direction = 1
                if not self.auto_scroll_timer.isActive():
                    self.auto_scroll_timer.start(self.auto_scroll_interval_ms)
            else:
                # Not near edges - stop auto-scroll
                self.auto_scroll_timer.stop()
                self.auto_scroll_direction = 0
            
            self.viewport().update()  # Trigger repaint to show indicator
            
            # Don't call super to avoid unwanted selection highlighting
            return
        super().mouseMoveEvent(event)
    
    def mouseReleaseEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton and self.drag_start_row is not None:
            actually_dragged = getattr(self, '_drag_actually_dragged', False)
            
            if not actually_dragged:
                # Plain click on an already-selected row — collapse selection to just that row
                start_row = self.drag_start_row
                self.drag_start_row = None
                self.drag_selected_rows = []
                self._drag_press_pos = None
                self._drag_actually_dragged = False
                self.drop_indicator_row = -1
                self.auto_scroll_timer.stop()
                self.setCursor(Qt.CursorShape.ArrowCursor)
                self.viewport().update()
                # Collapse to the clicked row (normal single-click behaviour)
                self.setCurrentCell(start_row, self.currentColumn())
                self.selectRow(start_row)
                super().mouseReleaseEvent(event)
                return
            
            drop_row = self.rowAt(event.position().toPoint().y())
            
            # If dropped below table, use last row + 1
            if drop_row < 0:
                drop_row = self.rowCount() - 1
            
            if drop_row >= 0 and self.parent_player:
                # Check if dragging multiple rows
                if len(self.drag_selected_rows) > 1:
                    # Multi-row drag
                    self.parent_player.reorder_multiple_playlist_items(self.drag_selected_rows, drop_row)
                elif drop_row != self.drag_start_row:
                    # Single row drag
                    self.parent_player.reorder_playlist(self.drag_start_row, drop_row)
            
            self.drag_start_row = None
            self.drag_selected_rows = []
            self._drag_press_pos = None
            self._drag_actually_dragged = False
            self.drop_indicator_row = -1
            self.auto_scroll_timer.stop()  # Stop auto-scroll
            self.setCursor(Qt.CursorShape.ArrowCursor)
            self.viewport().update()  # Clear indicator
        super().mouseReleaseEvent(event)
    
    def auto_scroll(self):
        """Auto-scroll the playlist when dragging near edges"""
        if self.auto_scroll_direction == -1:
            # Scroll up
            current_value = self.verticalScrollBar().value()
            self.verticalScrollBar().setValue(current_value - self.auto_scroll_step_rows)
        elif self.auto_scroll_direction == 1:
            # Scroll down
            current_value = self.verticalScrollBar().value()
            self.verticalScrollBar().setValue(current_value + self.auto_scroll_step_rows)
    
    def paintEvent(self, event):
        """Override paint to draw drop indicator line"""
        super().paintEvent(event)
        
        if self.drop_indicator_row >= 0:
            from PyQt6.QtGui import QPainter, QPen, QColor
            from PyQt6.QtCore import Qt
            
            painter = QPainter(self.viewport())
            pen = QPen(QColor(0, 120, 215), 2)  # Blue line, 2px thick
            painter.setPen(pen)
            
            # Draw line above the target row
            if self.drop_indicator_row < self.rowCount():
                y = self.rowViewportPosition(self.drop_indicator_row)
            else:
                # Draw at bottom if dropping at end
                y = self.rowViewportPosition(self.rowCount() - 1) + self.rowHeight(self.rowCount() - 1)
            
            painter.drawLine(0, y, self.viewport().width(), y)
            painter.end()
    
    
    def keyPressEvent(self, event):
        """Handle Delete key and arrow keys for movement"""
        current_row = self.currentRow()
        
        if event.key() == Qt.Key.Key_Delete:
            # Handle multi-delete
            selected_rows = sorted(set(index.row() for index in self.selectedIndexes()), reverse=True)
            if selected_rows and self.parent_player:
                self.parent_player.delete_multiple_from_playlist(selected_rows)
                event.accept()
                return
        elif event.key() == Qt.Key.Key_A and event.modifiers() & Qt.KeyboardModifier.ControlModifier:
            # Ctrl+A: Select all
            self.selectAll()
            event.accept()
            return
        elif event.key() == Qt.Key.Key_V and event.modifiers() & Qt.KeyboardModifier.ControlModifier:
            if self.parent_player and self.parent_player.paste_urls_to_playlist_from_clipboard():
                event.accept()
                return
        elif event.key() == Qt.Key.Key_F2:
            if self.parent_player:
                self.parent_player.rename_selected_playlist_entry()
                event.accept()
                return
        elif event.key() == Qt.Key.Key_Up and event.modifiers() & Qt.KeyboardModifier.ControlModifier:
            if current_row > 0 and self.parent_player:
                self.parent_player.reorder_playlist(current_row, current_row - 1)
                event.accept()
                return
        elif event.key() == Qt.Key.Key_Down and event.modifiers() & Qt.KeyboardModifier.ControlModifier:
            if current_row < self.rowCount() - 1 and self.parent_player:
                self.parent_player.reorder_playlist(current_row, current_row + 1)
                event.accept()
                return
        
        super().keyPressEvent(event)


class ClickableGraphicsView(QGraphicsView):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.parent_player = parent
        self.viewport().installEventFilter(self)
        self.setMouseTracking(True)
        
        # Gesture tracking
        self.gesture_start_pos = None
        self.gesture_start_time = None
        self.is_gesture = False
        
        self.viewport().setAcceptDrops(True)

    def eventFilter(self, source, event):
        if event.type() == QEvent.Type.MouseButtonDblClick and source is self.viewport():
             if self.parent_player:
                self.parent_player.toggle_fullscreen()
             return True
        elif event.type() == QEvent.Type.MouseMove:
             if self.parent_player:
                 self.parent_player.show_controls()
                 self.parent_player._update_fullscreen_taskbar_reveal(QCursor.pos())
        return super().eventFilter(source, event)
    
    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            event.accept()
        else:
            event.ignore()

    def dragMoveEvent(self, event):
        if event.mimeData().hasUrls():
            event.accept()
        else:
            event.ignore()

    def dropEvent(self, event):
        files = [u.toLocalFile() or u.toString() for u in event.mimeData().urls()]
        if self.parent_player and files:
            self.parent_player.handle_dropped_files(files)
            event.accept()
        else:
            event.ignore()

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.RightButton and self.parent_player:
            global_pos = event.globalPosition().toPoint() if hasattr(event, 'globalPosition') else self.mapToGlobal(event.pos())
            pp = self.parent_player
            if pp._is_app_fullscreen():
                # In fullscreen, the app-level eventFilter is the single handler
                # for right-clicks (both menu and side-panel toggle). Don't call
                # show_video_surface_context_menu here — just let the event propagate
                # so the eventFilter sees it.
                super().mousePressEvent(event)
                return
            pp.show_video_surface_context_menu(global_pos)
            event.accept()
            return
        if event.button() == Qt.MouseButton.LeftButton:
            self.gesture_start_pos = event.pos()
            self.gesture_start_time = datetime.now()
            self.is_gesture = False
        super().mousePressEvent(event)
    
    def mouseMoveEvent(self, event):


        if self.gesture_start_pos and event.buttons() & Qt.MouseButton.LeftButton:
            delta = event.pos() - self.gesture_start_pos
            if abs(delta.x()) > 50 or abs(delta.y()) > 50:
                self.is_gesture = True
                
                # Horizontal gesture - seek
                if abs(delta.x()) > abs(delta.y()):
                    seek_amount = int(delta.x() / 10) * 1000  # 1 sec per 10 pixels
                    if self.parent_player:
                        pos = self.parent_player.media_player.position()
                        new_pos = max(0, pos + seek_amount)
                        self.parent_player.media_player.setPosition(new_pos)
                        self.parent_player.show_time_osd()
                # Vertical gesture - volume
                else:
                    vol_change = int(-delta.y() / 10)  # Negative because up is negative Y
                    if self.parent_player:
                        vol = self.parent_player.volume_slider.value()
                        new_vol = max(0, min(100, vol + vol_change))
                        self.parent_player.volume_slider.setValue(new_vol)
                        self.parent_player.show_osd(f"Volume: {new_vol}%")
                
                self.gesture_start_pos = event.pos()
        super().mouseMoveEvent(event)
    
    def mouseReleaseEvent(self, event):


        if not self.is_gesture and self.parent_player:
            # Side-click navigation: ONLY for single images (not videos, CBZ, or Read Mode)
            p = self.parent_player
            current = getattr(p, 'current_file', '') or ''
            is_single_image = (current.lower().endswith(IMAGE_EXTENSIONS)
                              and not getattr(p, 'is_cbz_active', False)
                              and not getattr(p, 'read_mode', False))
            
            if is_single_image:
                width = self.viewport().width()
                pos_x = event.pos().x()
                
                if pos_x < width / 3:
                    p.previous_video()
                    event.accept()
                elif pos_x > 2 * width / 3:
                    p.next_video()
                    event.accept()
                
        self.gesture_start_pos = None
        self.gesture_start_time = None
        self.is_gesture = False
        super().mouseReleaseEvent(event)
    
    def wheelEvent(self, event):
        # Zoom with Ctrl + Wheel
        if event.modifiers() & Qt.KeyboardModifier.ControlModifier:
            if self.parent_player:
                delta = event.angleDelta().y()
                if getattr(self.parent_player, 'rotation_mode_enabled', False) and self.parent_player._is_video_rotation_available():
                    steps = delta / 120.0 if delta else 0.0
                    if abs(steps) >= 0.01:
                        self.parent_player.adjust_video_rotation(steps * 6.0)
                else:
                    if delta > 0:
                        self.parent_player.zoom_in()
                    else:
                        self.parent_player.zoom_out()
            event.accept()
        else:
            if self.parent_player and self.parent_player._handle_graphics_view_scroll_wheel(event):
                event.accept()
                return
            super().wheelEvent(event)


class VideoSurfaceInputMixin:
    def _init_video_surface_input(self, parent=None):
        self.parent_player = parent
        self.setMouseTracking(True)
        self.setAcceptDrops(True)
        self.gesture_start_pos = None
        self.gesture_start_time = None
        self.is_gesture = False

    def mouseDoubleClickEvent(self, event):
        if self.parent_player:
            self.parent_player.toggle_fullscreen()
        event.accept()

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            event.accept()
        else:
            event.ignore()

    def dragMoveEvent(self, event):
        if event.mimeData().hasUrls():
            event.accept()
        else:
            event.ignore()

    def dropEvent(self, event):
        files = [u.toLocalFile() or u.toString() for u in event.mimeData().urls()]
        if self.parent_player and files:
            self.parent_player.handle_dropped_files(files)
            event.accept()
        else:
            event.ignore()

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.RightButton and self.parent_player:
            global_pos = event.globalPosition().toPoint() if hasattr(event, 'globalPosition') else self.mapToGlobal(event.pos())
            pp = self.parent_player
            if pp._is_app_fullscreen():
                # In fullscreen, the app-level eventFilter is the single handler
                # for right-clicks (both menu and side-panel toggle). Don't call
                # show_video_surface_context_menu here — just let the event propagate
                # so the eventFilter sees it.
                super().mousePressEvent(event)
                return
            pp.show_video_surface_context_menu(global_pos)
            event.accept()
            return
        if event.button() == Qt.MouseButton.LeftButton:
            self.gesture_start_pos = event.pos()
            self.gesture_start_time = datetime.now()
            self.is_gesture = False
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if self.parent_player:
            self.parent_player.show_controls()
            self.parent_player._update_fullscreen_taskbar_reveal(QCursor.pos())

        if self.gesture_start_pos and event.buttons() & Qt.MouseButton.LeftButton:
            delta = event.pos() - self.gesture_start_pos
            if abs(delta.x()) > 50 or abs(delta.y()) > 50:
                self.is_gesture = True

                if abs(delta.x()) > abs(delta.y()):
                    seek_amount = int(delta.x() / 10) * 1000
                    if self.parent_player:
                        pos = self.parent_player.media_player.position()
                        new_pos = max(0, pos + seek_amount)
                        self.parent_player.media_player.setPosition(new_pos)
                        self.parent_player.show_time_osd()
                else:
                    vol_change = int(-delta.y() / 10)
                    if self.parent_player:
                        vol = self.parent_player.volume_slider.value()
                        new_vol = max(0, min(100, vol + vol_change))
                        self.parent_player.volume_slider.setValue(new_vol)
                        self.parent_player.show_osd(f"Volume: {new_vol}%")

                self.gesture_start_pos = event.pos()
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        self.gesture_start_pos = None
        self.gesture_start_time = None
        self.is_gesture = False
        super().mouseReleaseEvent(event)

    def wheelEvent(self, event):
        if event.modifiers() & Qt.KeyboardModifier.ControlModifier:
            if self.parent_player:
                delta = event.angleDelta().y()
                if getattr(self.parent_player, 'rotation_mode_enabled', False) and self.parent_player._is_video_rotation_available():
                    steps = delta / 120.0 if delta else 0.0
                    if abs(steps) >= 0.01:
                        self.parent_player.adjust_video_rotation(steps * 6.0)
                else:
                    if delta > 0:
                        self.parent_player.zoom_in()
                    else:
                        self.parent_player.zoom_out()
            event.accept()
        else:
            if self.parent_player and self.parent_player._handle_zoomed_video_surface_wheel(event):
                event.accept()
                return
            super().wheelEvent(event)


class ClickableVideoWidget(VideoSurfaceInputMixin, QVideoWidget):
    def __init__(self, parent=None):
        super().__init__(parent)
        self._init_video_surface_input(parent)


class MpvAudioOutputProxy(QObject):
    def __init__(self, player):
        super().__init__(player)
        self._player = player
        self._mpv = None
        self._volume = 0.7
        self._muted = False
        self._device = QMediaDevices.defaultAudioOutput()

    def attach_mpv(self, mpv_handle):
        self._mpv = mpv_handle
        self._apply_volume()
        self._apply_mute()
        self._apply_device()

    def _apply_volume(self):
        if self._mpv is None:
            return
        try:
            self._mpv.volume = max(0.0, min(100.0, float(self._volume) * 100.0))
        except Exception as exc:
            print(f"[mpv] volume sync failed: {exc}")

    def _apply_mute(self):
        if self._mpv is None:
            return
        try:
            self._mpv.mute = bool(self._muted)
        except Exception as exc:
            print(f"[mpv] mute sync failed: {exc}")

    def _apply_device(self):
        if self._mpv is None or self._device.isNull():
            return
        self._player.apply_audio_device(self._device)

    def volume(self):
        return float(self._volume)

    def setVolume(self, value):
        self._volume = max(0.0, min(1.0, float(value)))
        self._apply_volume()

    def isMuted(self):
        return bool(self._muted)

    def setMuted(self, muted):
        self._muted = bool(muted)
        self._apply_mute()

    def device(self):
        return self._device

    def setDevice(self, device):
        self._device = device
        self._apply_device()

    def update_from_mpv(self, *, volume=None, muted=None):
        if volume is not None:
            try:
                self._volume = max(0.0, min(1.0, float(volume) / 100.0))
            except Exception:
                pass
        if muted is not None:
            self._muted = bool(muted)


class ClickableMpvWidget(VideoSurfaceInputMixin, QOpenGLWidget):
    def __init__(self, parent=None):
        super().__init__(parent)
        self._init_video_surface_input(parent)
        self._player_backend = None
        self.setStyleSheet("background-color: black; border: none;")
        self.setAutoFillBackground(False)
        self.setAttribute(Qt.WidgetAttribute.WA_OpaquePaintEvent, True)
        try:
            self.setUpdateBehavior(QOpenGLWidget.UpdateBehavior.NoPartialUpdate)
        except Exception:
            pass

    def bind_backend(self, backend):
        self._player_backend = backend

    @pyqtSlot()
    def request_mpv_frame(self):
        self.update()

    def _clear_black(self):
        ctx = QOpenGLContext.currentContext()
        if ctx is None:
            return
        try:
            gl = ctypes.windll.opengl32
            gl.glClearColor.argtypes = [ctypes.c_float, ctypes.c_float, ctypes.c_float, ctypes.c_float]
            gl.glClearColor.restype = None
            gl.glClear.argtypes = [ctypes.c_uint]
            gl.glClear.restype = None
            gl.glClearColor(0.0, 0.0, 0.0, 1.0)
            gl.glClear(0x00004000)
        except Exception:
            pass

    def initializeGL(self):
        if self._player_backend is not None:
            self._player_backend.ensure_render_context(self)

    def paintGL(self):
        if self._player_backend is not None and self._player_backend.render_frame(
            self.defaultFramebufferObject(),
            self.width(),
            self.height(),
        ):
            return
        self._clear_black()

    def resizeGL(self, width, height):
        super().resizeGL(width, height)
        if self._player_backend is not None:
            self._player_backend.ensure_render_context(self)


class ClickableNativeMpvWidget(VideoSurfaceInputMixin, QWidget):
    def __init__(self, parent=None):
        super().__init__(parent)
        self._init_video_surface_input(parent)
        self._player_backend = None
        self.setStyleSheet("background-color: black; border: none;")
        self.setAutoFillBackground(False)
        self.setAttribute(Qt.WidgetAttribute.WA_NativeWindow, True)
        self.setAttribute(Qt.WidgetAttribute.WA_DontCreateNativeAncestors, False)
        self.setAttribute(Qt.WidgetAttribute.WA_OpaquePaintEvent, True)
        self.setAttribute(Qt.WidgetAttribute.WA_NoSystemBackground, True)

    def bind_backend(self, backend):
        self._player_backend = backend

    def resizeEvent(self, event):
        super().resizeEvent(event)
        if self._player_backend is not None:
            self._player_backend.refreshVideoSurface()


class MpvMediaPlayerAdapter(QObject):
    positionChanged = pyqtSignal(int)
    durationChanged = pyqtSignal(int)
    mediaStatusChanged = pyqtSignal(object)
    sourceChanged = pyqtSignal(QUrl)
    playbackFinished = pyqtSignal()
    loadFailed = pyqtSignal(str, str)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._mpv_module = _load_mpv_module()
        self._mpv = None
        self._render_widget = None
        self._native_render_widget = None
        self._render_driver = ''
        self._render_context = None
        self._gl_get_proc_wrapper = None
        self._source = QUrl()
        self._status = QMediaPlayer.MediaStatus.NoMedia
        self._playback_state = QMediaPlayer.PlaybackState.StoppedState
        self._position_ms = 0
        self._duration_ms = 0
        self._network_headers = {}
        self._tls_verify = True
        self._pending_seek_ms = None
        self._pending_video_state = None
        self._last_filter_chain = None
        self._last_video_rotate = None
        self._last_video_zoom = None
        self._last_video_pan_x = None
        self._last_video_pan_y = None
        self._last_video_crop = None
        self._last_transform_shader_key = ''
        self._shader_dim_factor = 1.0
        self._transform_shader_paths = {}
        self._presentation_mirror = False
        self._presentation_vertical_mirror = False
        self._presentation_fbo = None
        self._presentation_fbo_size = (0, 0)
        self._presentation_program = None
        self._presentation_vao = None
        self._gl_bind_framebuffer = None
        self._gl_blit_framebuffer = None
        self._gl_viewport = None
        self._gl_active_texture = None
        self._gl_bind_texture = None
        self._gl_draw_arrays = None
        self._gl_disable = None
        self._qt_gl_function_cache = {}
        self._presentation_blit_failed_logged = False
        self._prefer_shader_mirror = False
        self._mirror_perf_signature = None
        self._playback_rate = 1.0
        self._stopped_explicitly = True
        self._file_loaded = False
        self._end_of_media_reported = False
        self._audio_output = MpvAudioOutputProxy(self)
        self._audio_device_list = []
        self._backend_error = None
        self._event_handlers = []
        self._property_handlers = []
        self._render_failure_logged = False
        self._last_perf_profile = None

        if self._mpv_module is None:
            self._backend_error = _MPV_IMPORT_ERROR
            return

        # The mpv handle is created after the video widgets exist.  On Windows
        # that lets us prefer mpv's native D3D11 child-window output, which keeps
        # 4K/60 decode/presentation on the GPU.  The old libmpv/OpenGL renderer
        # remains as a fallback if native creation fails.

    def is_available(self):
        return self._mpv_module is not None and self._backend_error is None

    def is_native_rendering(self):
        return getattr(self, '_render_driver', '') == 'native-d3d11'

    def backend_error(self):
        return self._backend_error

    def _native_window_id(self):
        widget = getattr(self, '_native_render_widget', None)
        if widget is None:
            return None
        try:
            widget.setAttribute(Qt.WidgetAttribute.WA_NativeWindow, True)
            wid = int(widget.winId())
            return wid if wid > 0 else None
        except Exception:
            return None

    def _cookies_txt_path(self):
        """Return absolute path to cookies.txt if it exists next to main.py."""
        import os
        try:
            path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'cookies.txt')
            return path if os.path.isfile(path) else None
        except Exception:
            return None

    def _mpv_common_options(self):
        opts = {
            'ao': 'wasapi',
            'hwdec_extra_frames': 128,
            'audio_exclusive': False,
            'osc': False,
            'input_default_bindings': False,
            'config': False,
            'pause': True,
            'idle': 'yes',
            'keep_open': 'always',
            'cursor_autohide': 'no',
            'terminal': False,
        }
        # Pass browser cookies to mpv so CDN servers see an authenticated session
        cookies_path = self._cookies_txt_path()
        if cookies_path:
            opts['cookies'] = True
            opts['cookies_file'] = cookies_path
            print(f'[COOKIES] mpv will use cookies from: {cookies_path}')
        return opts

    def _mpv_log_handler(self, loglevel, component, message):
        # Surfaces libmpv/ffmpeg's own internal error/warning messages (demuxer
        # failures, HTTP errors, codec issues) to the console. Without this,
        # playback failures below the Python layer are completely silent —
        # we only ever see our own high-level [PLAYBACK] prints, never the
        # actual reason ffmpeg/mpv gave up on a stream.
        try:
            print(f"[MPV][{loglevel}][{component}] {message}")
        except Exception:
            pass
        # Stash the most recent error/fatal line so _handle_playback_load_failed
        # can inspect the *real* reason (e.g. a TLS certificate rejection) —
        # the end-file event mpv fires only carries a generic reason like
        # "loading failed" with none of this detail.
        try:
            if str(loglevel or '').lower() in ('error', 'fatal'):
                self._last_mpv_error_message = str(message or '')
                # Keep the last handful of error lines too: mpv follows the
                # meaningful ffmpeg error (e.g. "tls: ... certificate verify
                # failed") with a generic "[stream] Failed to open <url>"
                # line that overwrites it before the load-failed handler can
                # inspect the real reason.
                _recent = getattr(self, '_recent_mpv_errors', None)
                if not isinstance(_recent, list):
                    _recent = []
                _recent.append(self._last_mpv_error_message)
                self._recent_mpv_errors = _recent[-12:]
        except Exception:
            pass

    def _create_mpv_handle(self, mode):
        if self._mpv_module is None:
            raise RuntimeError(_MPV_IMPORT_ERROR or "mpv module is unavailable")

        options = self._mpv_common_options()
        if mode == 'native-d3d11':
            wid = self._native_window_id()
            if wid is None:
                raise RuntimeError("native video widget does not have a window id")
            options.update({
                'vo': 'gpu-next,gpu',
                'wid': wid,
                'gpu_api': 'd3d11',
                'hwdec': 'd3d11va',
                'd3d11va_zero_copy': True,
                'd3d11_flip': True,
            })
        else:
            options.update({
                'vo': 'libmpv',
                'hwdec': 'auto-copy-safe',
            })
        return self._mpv_module.MPV(log_handler=self._mpv_log_handler, loglevel='error', **options)

    def _finish_mpv_setup(self):
        if self._mpv is None:
            return
        try:
            self._apply_base_performance_options()
            self._mpv['ytdl'] = True
            # No height cap — the old 1080p cap was blocking 4K VR streams routed
            # through mpv's native ytdl hook. Quality selection for streams resolved
            # by the PyQt side is handled separately via _ytdlp_format_selector.
            self._mpv['ytdl-format'] = 'bestvideo+bestaudio/best'
        except Exception as exc:
            print(f"[mpv] yt-dlp hook setup skipped: {exc}")
        self._audio_output.attach_mpv(self._mpv)
        self._event_handlers = []
        self._property_handlers = []
        self._register_observers()

    def _initialize_mpv(self):
        if self._mpv is not None:
            return True
        if self._mpv_module is None:
            return False

        candidates = []
        if os.name == 'nt' and self._native_window_id() is not None:
            candidates.append('native-d3d11')
        candidates.append('embedded-opengl')

        last_error = None
        for mode in candidates:
            try:
                self._render_driver = mode
                self._mpv = self._create_mpv_handle(mode)
                self._finish_mpv_setup()
                if mode == 'native-d3d11':
                    print("[video_backend] mpv renderer: native D3D11 window")
                else:
                    print("[video_backend] mpv renderer: embedded OpenGL fallback")
                return True
            except Exception as exc:
                last_error = exc
                print(f"[mpv] {mode} init failed: {exc}")
                try:
                    if self._mpv is not None:
                        self._mpv.terminate()
                except Exception:
                    pass
                self._mpv = None
                self._render_driver = ''

        self._backend_error = last_error
        return False

    def _set_mpv_option(self, name, value):
        if self._mpv is None:
            return False
        try:
            self._mpv[name] = value
            return True
        except Exception:
            return False

    def _get_mpv_property(self, name, default=None):
        if self._mpv is None:
            return default
        try:
            return self._mpv._get_property(name)
        except Exception:
            return default

    def _is_local_ftp_proxy_source(self):
        """Whether the current source is our range-capable FTP streaming proxy."""
        try:
            source = self._source.toString()
            parsed = urlparse(source)
            return (
                parsed.scheme.lower() == 'http'
                and (parsed.hostname or '').lower() in {'127.0.0.1', 'localhost', '::1'}
                and (parsed.path or '').startswith('/ftp/')
            )
        except Exception:
            return False

    def _is_local_hls_proxy_source(self):
        """Whether the current source is our rewritten HLS proxy (/hls/…)."""
        try:
            source = self._source.toString()
            parsed = urlparse(source)
            return (
                parsed.scheme.lower() == 'http'
                and (parsed.hostname or '').lower() in {'127.0.0.1', 'localhost', '::1'}
                and (parsed.path or '').startswith('/hls/')
            )
        except Exception:
            return False

    def _source_buffering_options(self):
        """Return the small, seek-friendly buffer used for live FTP playback.

        The proxy deliberately has no disk cache and supports HTTP byte ranges.
        Keeping mpv's normal 60/90-second network cache for this source can make
        it read a large portion of an MP4 before showing the first frame.
        """
        if self._is_local_ftp_proxy_source():
            return {
                'cache': 'yes',
                'cache-secs': 3,
                'cache-pause-initial': False,
                'demuxer-max-bytes': '16MiB',
                'demuxer-max-back-bytes': '4MiB',
                'demuxer-readahead-secs': 0.25,
                # Lets libmpv use the proxy's Accept-Ranges support to fetch an
                # MP4 index near the end instead of sequentially reading there.
                'force-seekable': True,
            }
        if self._is_local_hls_proxy_source():
            # R59: turtleviplay VOD-as-live — without force-seekable, mpv
            # only walks the live window (~1 min) on the time bar.
            return {
                'cache': 'yes',
                'cache-secs': 20,
                'cache-pause-initial': False,
                'demuxer-max-bytes': '128MiB',
                'demuxer-max-back-bytes': '64MiB',
                'demuxer-readahead-secs': 1,
                'force-seekable': True,
            }
        return {
            'cache': 'yes',
            'cache-secs': 60,
            'cache-pause-initial': False,
            'demuxer-max-bytes': '512MiB',
            'demuxer-max-back-bytes': '128MiB',
            'demuxer-readahead-secs': 1,
            'force-seekable': False,
        }

    def _apply_source_buffering_options(self):
        for name, value in self._source_buffering_options().items():
            self._set_mpv_option(name, value)

    def _apply_base_performance_options(self):
        if self._mpv is None:
            return
        options = {
            # d3d11va-copy is used as the base hwdec instead of d3d11va zero-copy.
            # Zero-copy is faster for H.264/HEVC but silently falls back to hwdec=no
            # for codecs the GPU's fixed-function decoder doesn't support (e.g. AV1 on
            # most GPUs pre-RTX 30xx / RX 6000+). d3d11va-copy never falls back to
            # hwdec=no — it copies the decoded frame to system RAM and handles the rest
            # there, which is far better than pure CPU decode for large frames.
            # The 4k-fast profile upgrades to zero-copy for H.264/HEVC explicitly.
            'hwdec': 'd3d11va-copy' if os.name == 'nt' else 'auto-copy-safe',
            'hwdec-codecs': 'all',
            'gpu-hwdec-interop': 'auto',
            'd3d11va-zero-copy': False,
            'vd-lavc-threads': 0,
            'video-sync': 'audio',
            'framedrop': 'vo',
            'interpolation': False,
            'deband': False,
            'blend-subtitles': False,
            'scale': 'bilinear',
            'cscale': 'bilinear',
            'dscale': 'bilinear',
            'correct-downscaling': False,
            'linear-downscaling': False,
            'sigmoid-upscaling': False,
            'hr-seek-framedrop': True,
            'ao': 'wasapi',
            'audio-exclusive': False,
            'audio-client-name': 'Antigravity Player',
        }
        options.update(self._source_buffering_options())
        for name, value in options.items():
            self._set_mpv_option(name, value)
        self._last_perf_profile = 'base'

    def _apply_adaptive_performance_profile(self):
        if self._mpv is None:
            return
        video_params = self._get_mpv_property('video-params', {}) or {}
        try:
            width = int(video_params.get('w') or self._get_mpv_property('width', 0) or 0)
        except Exception:
            width = 0
        try:
            height = int(video_params.get('h') or self._get_mpv_property('height', 0) or 0)
        except Exception:
            height = 0
        try:
            fps = float(self._get_mpv_property('container-fps', 0) or self._get_mpv_property('estimated-vf-fps', 0) or 0)
        except Exception:
            fps = 0.0
        try:
            bitrate = float(self._get_mpv_property('video-bitrate', 0) or 0)
        except Exception:
            bitrate = 0.0
        heavy_4k = (
            width >= 3840
            or height >= 2160
            or (height >= 1440 and fps >= 50.0)
            or bitrate >= 25000000
        )
        prefer_shader_mirror = bool(heavy_4k and fps >= 45.0)
        target_profile = '4k-fast' if heavy_4k else 'base'
        mirror_strategy_changed = prefer_shader_mirror != getattr(self, '_prefer_shader_mirror', False)
        self._prefer_shader_mirror = prefer_shader_mirror
        if target_profile == self._last_perf_profile:
            if mirror_strategy_changed and self._pending_video_state:
                self._apply_pending_video_state()
            return
        if heavy_4k:
            native_d3d11 = getattr(self, '_render_driver', '') == 'native-d3d11'
            # AV1 and VP9 have very limited hardware zero-copy support (needs RTX 30xx+
            # or RX 6000+). Forcing d3d11va zero-copy on those codecs causes mpv to
            # silently fall back to hwdec=no (full software) instead of trying the
            # copy path first. d3d11va-copy is safer: it tries GPU decode and copies
            # the frame to RAM, gracefully degrading to software if the GPU can't
            # handle it — which is far better than a full software decode surprise.
            current_codec = (self._get_mpv_property('video-codec', '') or '').lower()
            non_zerocopy_codec = any(c in current_codec for c in ('av1', 'vp9', 'vp8'))
            if non_zerocopy_codec:
                hwdec_4k = 'd3d11va-copy' if os.name == 'nt' else 'auto-copy-safe'
                zero_copy_4k = False
            else:
                hwdec_4k = ('d3d11va' if native_d3d11 else 'd3d11va-copy') if os.name == 'nt' else 'auto-safe'
                zero_copy_4k = native_d3d11 and os.name == 'nt'
            profile_options = {
                'hwdec': hwdec_4k,
                'd3d11va-zero-copy': zero_copy_4k,
                'gpu-hwdec-interop': 'auto',
                'video-sync': 'audio',
                'framedrop': 'vo',
                'interpolation': False,
                'deband': False,
                'scale': 'bilinear',
                'cscale': 'bilinear',
                'dscale': 'bilinear',
                'correct-downscaling': False,
                'linear-downscaling': False,
                'sigmoid-upscaling': False,
                'demuxer-max-bytes': '768MiB',
                'demuxer-max-back-bytes': '192MiB',
                'cache-secs': 90,
            }
            # A high-resolution FTP stream still needs to start promptly; do
            # not let the 4K profile replace its small, range-friendly cache.
            profile_options.update(self._source_buffering_options())
            for name, value in profile_options.items():
                self._set_mpv_option(name, value)
        else:
            self._apply_base_performance_options()
        self._last_perf_profile = target_profile
        hwdec_current = self._get_mpv_property('hwdec-current', '') or self._get_mpv_property('hwdec', '')
        hwdec_config = self._get_mpv_property('hwdec', '') or ''
        codec = self._get_mpv_property('video-codec', '') or ''
        print(
            f"[mpv][perf] profile={target_profile} "
            f"{width}x{height} fps={fps:.2f} bitrate={bitrate / 1000:.0f}kbps "
            f"hwdec={hwdec_current or 'unknown'} config={hwdec_config or 'unknown'} codec={codec or 'unknown'} "
            f"renderer={getattr(self, '_render_driver', '') or 'unknown'} "
            f"mirror={'shader' if prefer_shader_mirror else 'presentation'}"
        )
        if mirror_strategy_changed and self._pending_video_state:
            self._apply_pending_video_state()

    def _right_angle_rotation(self, rotation):
        try:
            normalized = float(rotation or 0.0) % 360.0
        except Exception:
            normalized = 0.0
        for angle in (0, 90, 180, 270):
            if abs(normalized - angle) <= 0.25 or abs(normalized - angle - 360) <= 0.25:
                return angle
        return None

    def _nudge_after_transform_change(self):
        if self._mpv is None:
            return
        try:
            self._mpv.speed = float(self._playback_rate)
        except Exception:
            pass
        widget = getattr(self, '_render_widget', None)
        try:
            if widget is not None:
                QTimer.singleShot(0, widget.update)
        except Exception:
            pass

    def _transform_shader_path(self, mirror=False, vertical_mirror=False, dim_factor=None):
        try:
            dim_factor = float(self._shader_dim_factor if dim_factor is None else dim_factor)
        except Exception:
            dim_factor = 1.0
        dim_factor = max(0.02, min(1.0, dim_factor))
        key_bits = []
        if mirror:
            key_bits.append('x')
        if vertical_mirror:
            key_bits.append('y')
        if dim_factor < 0.999:
            key_bits.append(f"d{int(dim_factor * 1000):03d}")
        key = ''.join(key_bits)
        if not key:
            return '', ''
        cached_path = self._transform_shader_paths.get(key)
        if cached_path and os.path.exists(cached_path):
            return key, cached_path
        shader_dir = os.path.join(tempfile.gettempdir(), 'antigravity_player_mpv_shaders')
        os.makedirs(shader_dir, exist_ok=True)
        path = os.path.join(shader_dir, f'transform_{key}.glsl')
        x_line = 'pos.x = 1.0 - pos.x;' if mirror else ''
        y_line = 'pos.y = 1.0 - pos.y;' if vertical_mirror else ''
        dim_line = f'    color.rgb *= {dim_factor:.6f};\n' if dim_factor < 0.999 else ''
        shader_text = (
            '//!HOOK MAIN\n'
            '//!BIND HOOKED\n\n'
            'vec4 hook() {\n'
            '    vec2 pos = HOOKED_pos;\n'
            f'    {x_line}\n'
            f'    {y_line}\n'
            '    vec4 color = HOOKED_tex(pos);\n'
            f'{dim_line}'
            '    return color;\n'
            '}\n'
        )
        try:
            with open(path, 'w', encoding='utf-8') as shader_file:
                shader_file.write(shader_text)
            self._transform_shader_paths[key] = path
            return key, path
        except Exception as exc:
            print(f"[mpv] transform shader write failed: {exc}")
            return '', ''

    def _apply_transform_shader(self, mirror=False, vertical_mirror=False):
        if self._mpv is None:
            return False
        key, path = self._transform_shader_path(mirror, vertical_mirror)
        if key == self._last_transform_shader_key:
            return False
        try:
            self._mpv['glsl-shaders'] = [path] if path else []
            self._last_transform_shader_key = key
            return True
        except Exception as exc:
            print(f"[mpv] transform shader update failed: {exc}")
            return False

    def set_nocturnal_dim(self, enabled=False, intensity=0.0):
        try:
            intensity = max(0.0, min(0.98, float(intensity or 0.0)))
        except Exception:
            intensity = 0.0
        target_factor = max(0.02, 1.0 - intensity) if enabled else 1.0
        if abs(target_factor - getattr(self, '_shader_dim_factor', 1.0)) < 0.0005:
            return False
        self._shader_dim_factor = target_factor
        if self._pending_video_state:
            self._apply_pending_video_state()
        else:
            self._apply_transform_shader(False, False)
        self.refreshVideoSurface()
        return True

    def _set_presentation_mirror(self, mirror=False, vertical_mirror=False):
        mirror = bool(mirror)
        vertical_mirror = bool(vertical_mirror)
        changed = (
            mirror != getattr(self, '_presentation_mirror', False)
            or vertical_mirror != getattr(self, '_presentation_vertical_mirror', False)
        )
        self._presentation_mirror = mirror
        self._presentation_vertical_mirror = vertical_mirror
        if changed:
            widget = getattr(self, '_render_widget', None)
            try:
                if widget is not None:
                    widget.update()
            except Exception:
                pass
        return changed

    def setRenderWidget(self, widget, native_widget=None):
        if widget is not getattr(self, '_render_widget', None):
            self._presentation_fbo = None
            self._presentation_fbo_size = (0, 0)
            self._presentation_blit_failed_logged = False
        self._render_widget = widget
        self._native_render_widget = native_widget
        if hasattr(widget, 'bind_backend'):
            widget.bind_backend(self)
        if native_widget is not None and hasattr(native_widget, 'bind_backend'):
            native_widget.bind_backend(self)
        self._initialize_mpv()

    def setVideoOutput(self, target):
        # Kept for compatibility with the rest of the app. Rendering is handled
        # through the dedicated OpenGL widget instead of Qt Multimedia sinks.
        return target

    def setAudioOutput(self, audio_output):
        if isinstance(audio_output, MpvAudioOutputProxy):
            self._audio_output = audio_output
            self._audio_output.attach_mpv(self._mpv)

    def audioOutput(self):
        return self._audio_output

    def setNetworkRequestHeaders(self, headers=None):
        headers = dict(headers or {})
        self._force_direct_playback = bool(
            headers.pop('_force_direct_playback', False)
            or headers.pop('X-Antigravity-Direct-Playback', False)
        )
        self._network_headers = headers

    def _apply_tls_verify_option(self):
        if self._mpv is None:
            return
        enabled = bool(getattr(self, '_tls_verify', True))
        try:
            self._mpv['tls-verify'] = enabled
        except Exception:
            try:
                self._mpv['tls-verify'] = 'yes' if enabled else 'no'
            except Exception:
                pass

    def setTlsVerify(self, enabled=True):
        self._tls_verify = bool(True if enabled is None else enabled)
        self._apply_tls_verify_option()
        self._apply_network_request_headers()

    def position(self):
        return int(self._position_ms)

    def duration(self):
        return int(self._duration_ms)

    def playbackState(self):
        return self._playback_state

    def _set_media_status(self, status):
        if status != self._status:
            self._status = status
            self.mediaStatusChanged.emit(status)

    def _set_playback_state(self, state):
        self._playback_state = state

    def _register_observers(self):
        self._mpv.observe_property('time-pos', self._on_time_pos)
        self._mpv.observe_property('duration', self._on_duration)
        self._mpv.observe_property('eof-reached', self._on_eof_reached)
        self._mpv.observe_property('pause', self._on_pause)
        self._mpv.observe_property('volume', self._on_volume)
        self._mpv.observe_property('mute', self._on_mute)
        self._mpv.observe_property('audio-device-list', self._on_audio_device_list)

        @self._mpv.event_callback('file-loaded')
        def _file_loaded(_event):
            try:
                print(f"[PLAYBACK][FILE_LOADED] {self._source.toString()}")
            except Exception:
                pass
            self._file_loaded = True
            self._stopped_explicitly = False
            self._end_of_media_reported = False
            self._set_media_status(QMediaPlayer.MediaStatus.LoadedMedia)
            if self._pending_seek_ms is not None:
                pending_seek = self._pending_seek_ms
                self._pending_seek_ms = None
                self.setPosition(pending_seek)
            self._apply_pending_video_state()
            self._apply_adaptive_performance_profile()
            QTimer.singleShot(250, self._apply_adaptive_performance_profile)

        @self._mpv.event_callback('end-file')
        def _end_file(_event):
            try:
                print(f"[PLAYBACK][END_FILE] {self._source.toString()} event={_event}")
            except Exception:
                pass
            event_data = getattr(_event, 'd', None)
            if not isinstance(event_data, dict):
                try:
                    event_data = _event.as_dict()
                except Exception:
                    event_data = {}
            raw_event_text = str(_event)

            def _event_text(key):
                value = event_data.get(key) if isinstance(event_data, dict) else ''
                if not value:
                    match = re.search(rf"{re.escape(key)}['\"]?\s*[:=]\s*b?['\"]([^'\"]+)", raw_event_text)
                    if match:
                        value = match.group(1)
                if isinstance(value, bytes):
                    return value.decode('utf-8', errors='replace')
                return str(value or '')

            reason = _event_text('reason').lower()
            file_error = _event_text('file_error')
            if reason == 'error' or file_error:
                self._file_loaded = False
                self._set_playback_state(QMediaPlayer.PlaybackState.StoppedState)
                self._set_media_status(QMediaPlayer.MediaStatus.InvalidMedia)
                self.loadFailed.emit(self._source.toString(), file_error or reason or 'loading failed')
                return
            if self._source.isEmpty() or self._stopped_explicitly:
                self._file_loaded = False
                self._set_playback_state(QMediaPlayer.PlaybackState.StoppedState)
                return
            self._emit_end_of_media_once()

        @self._mpv.event_callback('shutdown')
        def _shutdown(_event):
            self._file_loaded = False
            self._set_playback_state(QMediaPlayer.PlaybackState.StoppedState)

        self._event_handlers.extend((_file_loaded, _end_file, _shutdown))

    def _on_time_pos(self, _name, value):
        try:
            pos_ms = max(0, int(float(value or 0.0) * 1000.0))
        except Exception:
            pos_ms = 0
        if pos_ms != self._position_ms:
            self._position_ms = pos_ms
            self.positionChanged.emit(pos_ms)

    def _on_duration(self, _name, value):
        try:
            duration_ms = max(0, int(float(value or 0.0) * 1000.0))
        except Exception:
            duration_ms = 0
        if duration_ms != self._duration_ms:
            self._duration_ms = duration_ms
            self.durationChanged.emit(duration_ms)

    def _emit_end_of_media_once(self):
        if self._source.isEmpty() or self._stopped_explicitly:
            self._file_loaded = False
            self._set_playback_state(QMediaPlayer.PlaybackState.StoppedState)
            return False
        if self._status == QMediaPlayer.MediaStatus.LoadingMedia and not self._file_loaded:
            return False
        if self._end_of_media_reported:
            return False
        self._end_of_media_reported = True
        self._file_loaded = False
        self._set_playback_state(QMediaPlayer.PlaybackState.StoppedState)
        self._set_media_status(QMediaPlayer.MediaStatus.EndOfMedia)
        self.playbackFinished.emit()
        return True

    def _on_eof_reached(self, _name, value):
        if value:
            self._emit_end_of_media_once()

    def _on_pause(self, _name, value):
        if self._source.isEmpty():
            self._set_playback_state(QMediaPlayer.PlaybackState.StoppedState)
            return
        if self._stopped_explicitly:
            self._set_playback_state(QMediaPlayer.PlaybackState.StoppedState)
        elif value:
            self._set_playback_state(QMediaPlayer.PlaybackState.PausedState)
        else:
            self._set_playback_state(QMediaPlayer.PlaybackState.PlayingState)

    def _on_volume(self, _name, value):
        self._audio_output.update_from_mpv(volume=value)

    def _on_mute(self, _name, value):
        self._audio_output.update_from_mpv(muted=value)

    def _on_audio_device_list(self, _name, value):
        self._audio_device_list = value or []

    def _apply_network_request_headers(self):
        if self._mpv is None:
            return
        headers = {
            str(key): str(value)
            for key, value in dict(self._network_headers or {}).items()
            if key and value
        }
        user_agent = headers.pop('User-Agent', headers.pop('user-agent', ''))
        referrer = headers.pop('Referer', headers.pop('Referrer', headers.pop('referrer', '')))
        header_fields = [f"{key}: {value}".replace(',', '\\,') for key, value in headers.items()]
        # Always send a proper browser User-Agent — never send empty string
        default_ua = (
            'Mozilla/5.0 (Windows NT 10.0; Win64; x64) '
            'AppleWebKit/537.36 (KHTML, like Gecko) Chrome/135.0 Safari/537.36'
        )
        try:
            self._mpv['user-agent'] = user_agent or default_ua
        except Exception:
            pass
        try:
            self._mpv['referrer'] = referrer or ''
        except Exception:
            pass
        try:
            self._mpv['http-header-fields'] = header_fields
        except Exception:
            try:
                self._mpv['http-header-fields'] = ",".join(header_fields)
            except Exception:
                pass

    def source(self):
        return QUrl(self._source)

    def setSource(self, url):
        if self._mpv is None and not self._initialize_mpv():
            return

        source_url = QUrl(url)
        # Fresh load attempt: drop error lines from any previous file so the
        # load-failed TLS/retry heuristics only ever see THIS attempt's
        # errors.
        self._last_mpv_error_message = ''
        self._recent_mpv_errors = []
        if source_url.isEmpty() or not source_url.isValid():
            self._source = QUrl()
            self._file_loaded = False
            self._pending_seek_ms = None
            self._stopped_explicitly = True
            self._end_of_media_reported = False
            self._position_ms = 0
            self._duration_ms = 0
            self._last_filter_chain = None
            self._last_video_rotate = None
            self._last_video_zoom = None
            self._last_video_pan_x = None
            self._last_video_pan_y = None
            self._last_video_crop = None
            self._last_transform_shader_key = ''
            self._last_perf_profile = None
            try:
                self._mpv.command('stop')
                self._mpv.command('playlist-clear')
            except Exception as exc:
                print(f"[mpv] source clear failed: {exc}")
            self.positionChanged.emit(0)
            self.durationChanged.emit(0)
            self.sourceChanged.emit(self._source)
            self._set_playback_state(QMediaPlayer.PlaybackState.StoppedState)
            self._set_media_status(QMediaPlayer.MediaStatus.NoMedia)
            return

        self._source = source_url
        self._file_loaded = False
        self._pending_seek_ms = None
        self._stopped_explicitly = False
        self._end_of_media_reported = False
        self._position_ms = 0
        self._duration_ms = 0
        self._last_filter_chain = None
        self._last_video_rotate = None
        self._last_video_zoom = None
        self._last_video_pan_x = None
        self._last_video_pan_y = None
        self._last_video_crop = None
        self._last_transform_shader_key = ''
        self._last_perf_profile = None
        self.positionChanged.emit(0)
        self.durationChanged.emit(0)
        self.sourceChanged.emit(self._source)
        self._set_media_status(QMediaPlayer.MediaStatus.LoadingMedia)

        try:
            self._mpv.pause = True
            # Set the source-specific cache before loadfile.  Waiting until
            # file-loaded is too late for MP4 files whose index is at the end.
            self._apply_source_buffering_options()
            self._apply_network_request_headers()
            self._apply_tls_verify_option()

            target = source_url.toLocalFile() or source_url.toString()
            if str(target or '').lower().startswith('ftp://'):
                target = _ftp_url_for_native_client(target)
            if str(target or '').lower().startswith(('http://', 'https://', 'ftp://')):
                try:
                    print(f"[PLAYBACK][LOADFILE] {target}")
                except Exception:
                    pass
            target_lower = target.lower()
            try:
                _target_parsed = urlparse(target)
                # Use urlparse to extract the path before checking the extension —
                # xhamster CDN sub-stream URLs often carry query params like
                # ?token=…&expires=… so target_lower.endswith('.m3u8') is False
                # even though the path ends in .m3u8.  Without this, the URL falls
                # through to the 'xhamster' branch, ytdl is re-enabled with the
                # page-URL format selector, yt-dlp fails on the CDN manifest, and
                # mpv enters a dead state that survives until the next video load.
                _target_path = _target_parsed.path.lower().rstrip('/')
                _is_direct_stream = _target_path.endswith(('.m3u8', '.m3u', '.mpd'))
                _target_host = _target_parsed.netloc.lower()
                _is_fileditch_page = 'fileditch' in _target_host and 'freakingfileditch' not in _target_host
                _query_media_name = _query_media_name_hint(target)
                _query_points_to_stream = _query_media_name.endswith(('.m3u8', '.m3u', '.mpd'))
                _query_points_to_media = _query_media_name.endswith(VIDEO_EXTENSIONS + AUDIO_EXTENSIONS)
                # Bunkr CDN and GoFile CDN URLs are direct media links — yt-dlp
                # must NOT be invoked on them (it fails with 403 and blocks playback).
                _is_bunkr_cdn = any(x in _target_host for x in ('cdn.cr', 'bunkr', 'bkr'))
                _is_gofile_cdn = 'gofile' in _target_host or 'srv' in _target_host
                _is_direct_mp4 = _target_path.endswith(('.mp4', '.mkv', '.webm', '.mov', '.avi'))
                _is_streamtape_direct = (
                    '/get_video' in _target_path
                    and any(x in _target_host for x in ('streamtape', 'strtape', 'streamadblock', 'stape.'))
                )
                if _is_fileditch_page:
                    # fileditch watch pages often end in .mp4 or hide the real media
                    # path in ?f=...mp4, but the page itself is HTML and must be
                    # resolved to a fresh signed CDN URL first.
                    _is_direct_mp4 = False
                    _query_points_to_stream = False
                    _query_points_to_media = False
                # javdock/javhdporn CDN URLs — pre-signed direct video links,
                # no yt-dlp needed. tapecontent uses ?stream=1 (no file ext).
                _is_cloudatacdn = 'cloudatacdn.com' in _target_host
                _is_tapecontent = 'tapecontent.net' in _target_host
                if (getattr(self, '_force_direct_playback', False)
                        or _is_direct_stream or _query_points_to_stream
                        or _is_bunkr_cdn or _is_gofile_cdn
                        or _is_direct_mp4 or _is_streamtape_direct
                        or _query_points_to_media
                        or _is_cloudatacdn or _is_tapecontent):
                    # Raw HLS/DASH CDN URL or Bunkr CDN — play natively; disable yt-dlp entirely
                    # so mpv never tries to invoke it on a CDN manifest URL.
                    # Reset ytdl-format too so any stale site-specific selector
                    # (e.g. xhamster's 720p cap) doesn't persist across loads.
                    self._mpv['ytdl'] = False
                    self._mpv['ytdl-format'] = 'bestvideo+bestaudio/best'
                elif 'xhamster' in target_lower:
                    self._mpv['ytdl'] = True
                    self._mpv['ytdl-format'] = 'bestvideo[height<=720]+bestaudio/best[height<=720]/best'
                elif 'pornhub' in target_lower:
                    self._mpv['ytdl'] = True
                    self._mpv['ytdl-format'] = 'bestvideo+bestaudio/best'
                elif 'eporner' in target_lower or 'beeg' in target_lower:
                    # Avoid AV1 — these sites serve 4K AV1 which causes software
                    # decode fallback on GPUs without a hardware AV1 engine.
                    self._mpv['ytdl'] = True
                    self._mpv['ytdl-format'] = (
                        'bestvideo[vcodec!=av1][ext=mp4]+bestaudio/'
                        'bestvideo[vcodec!=av1]+bestaudio/'
                        'bestvideo+bestaudio/best'
                    )
                else:
                    # No height cap — let mpv pick the best quality available.
                    self._mpv['ytdl'] = True
                    self._mpv['ytdl-format'] = 'bestvideo[vcodec!=av1]+bestaudio/bestvideo+bestaudio/best'
                print(f"[MPV][YTDL_FLAGS] ytdl={self._mpv['ytdl']} is_direct_stream={_is_direct_stream} target={target[:140]}")
            except Exception as exc:
                print(f"[MPV][YTDL_FLAGS] exception computing ytdl flags for {target[:140]}: {exc!r} — ytdl left at previous value")
            self._mpv.loadfile(target, 'replace')
            self._mpv.speed = float(self._playback_rate)
            self._audio_output.attach_mpv(self._mpv)
            self._apply_pending_video_state()
        except Exception as exc:
            self._backend_error = exc
            print(f"[mpv] loadfile failed: {exc}")

    def play(self):
        if self._mpv is None or self._source.isEmpty():
            return
        try:
            self._stopped_explicitly = False
            self._mpv.pause = False
            self._set_playback_state(QMediaPlayer.PlaybackState.PlayingState)
        except Exception as exc:
            print(f"[mpv] play failed: {exc}")

    def pause(self):
        if self._mpv is None:
            return
        try:
            self._stopped_explicitly = False
            self._mpv.pause = True
            self._set_playback_state(QMediaPlayer.PlaybackState.PausedState)
        except Exception as exc:
            print(f"[mpv] pause failed: {exc}")

    def stop(self):
        if self._mpv is None:
            return
        self._stopped_explicitly = True
        try:
            self._mpv.pause = True
            if not self._source.isEmpty() and self._file_loaded:
                self._mpv.seek(0.0, 'absolute', 'exact')
        except Exception as exc:
            print(f"[mpv] stop failed: {exc}")
        self._position_ms = 0
        self.positionChanged.emit(0)
        self._set_playback_state(QMediaPlayer.PlaybackState.StoppedState)

    def setPosition(self, position_ms):
        position_ms = max(0, int(position_ms or 0))
        self._pending_seek_ms = position_ms
        if self._mpv is None:
            return
        if not self._file_loaded:
            return
        try:
            src = ''
            try:
                src = str(self._source.toString() or '')
            except Exception:
                src = ''
            src_l = src.lower()
            # HLS (esp. turtleviplay VOD-as-live): exact seeks often no-op
            # and the bar only advances ~1 min. Keyframe seek jumps.
            if ('.m3u8' in src_l) or ('/hls/' in src_l) or src_l.endswith('.m3u'):
                self._mpv.seek(position_ms / 1000.0, 'absolute')
            else:
                self._mpv.seek(position_ms / 1000.0, 'absolute', 'exact')
            self._pending_seek_ms = None
        except Exception as exc:
            print(f"[mpv] seek failed: {exc}")

    def stepForward(self):
        if not self._mpv:
            return False
        try:
            self._mpv.command('frame-step')
            self.refreshVideoSurface()
            return True
        except Exception as exc:
            print(f"[mpv] frame-step failed: {exc}")
            return False

    def stepBackward(self):
        if not self._mpv:
            return False
        try:
            self._mpv.command('frame-back-step')
            self.refreshVideoSurface()
            return True
        except Exception as exc:
            print(f"[mpv] frame-back-step failed: {exc}")
            return False

    def refreshVideoSurface(self):
        widget = getattr(self, '_render_widget', None)
        if widget is None:
            return
        try:
            widget.update()
            widget.repaint()
        except Exception:
            pass

    def setPlaybackRate(self, speed):
        try:
            self._playback_rate = max(0.1, float(speed))
        except Exception:
            self._playback_rate = 1.0
        if self._mpv is None:
            return
        try:
            self._mpv.speed = self._playback_rate
        except Exception as exc:
            print(f"[mpv] speed failed: {exc}")

    def apply_audio_device(self, qt_device):
        if self._mpv is None or qt_device.isNull():
            return
        target_desc = str(qt_device.description() or '').strip().lower()
        if not target_desc:
            return
        try:
            device_list = self._audio_device_list or self._mpv._get_property('audio-device-list')
        except Exception:
            device_list = self._audio_device_list

        def _is_exclusive_entry(entry):
            name = str(entry.get('name') or '').lower()
            description = str(entry.get('description') or entry.get('desc') or '').lower()
            return 'exclusive' in name or 'exclusive' in description

        shared_match = None
        exclusive_match = None
        for entry in device_list or []:
            if not isinstance(entry, dict):
                continue
            name = str(entry.get('name') or '')
            description = str(entry.get('description') or entry.get('desc') or '')
            haystack = f"{name} {description}".lower()
            if target_desc in haystack:
                if _is_exclusive_entry(entry):
                    exclusive_match = exclusive_match or name
                    continue
                shared_match = name
                break

        chosen_name = shared_match
        if chosen_name:
            try:
                self._mpv['audio-exclusive'] = False
                self._mpv['audio-device'] = chosen_name
            except Exception as exc:
                print(f"[mpv] audio-device switch failed: {exc}")
        elif exclusive_match:
            print(f"[mpv] skipped exclusive audio device for shared-mode playback: {target_desc}")

    def ensure_render_context(self, widget):
        if self._mpv is None or widget is None:
            return False
        if getattr(self, '_render_driver', '') == 'native-d3d11':
            return False
        if self._render_context is not None and self._render_widget is widget:
            return True

        current_context = QOpenGLContext.currentContext()
        if current_context is None:
            return False

        try:
            if self._render_context is not None:
                self._render_context.free()
        except Exception:
            pass
        self._render_context = None
        self._presentation_fbo = None
        self._presentation_fbo_size = (0, 0)
        self._presentation_program = None
        self._presentation_vao = None
        self._presentation_blit_failed_logged = False
        self._qt_gl_function_cache = {}
        self._gl_bind_framebuffer = None
        self._gl_blit_framebuffer = None
        self._gl_viewport = None
        self._gl_active_texture = None
        self._gl_bind_texture = None
        self._gl_draw_arrays = None
        self._gl_disable = None

        def _get_proc_address(_ctx, name):
            gl_context = QOpenGLContext.currentContext()
            if gl_context is None:
                return 0
            try:
                address = gl_context.getProcAddress(name)
            except Exception:
                return 0
            if address is None:
                return 0
            try:
                return int(address)
            except Exception:
                return 0

        try:
            self._gl_get_proc_wrapper = self._mpv_module.MpvGlGetProcAddressFn(_get_proc_address)
            self._render_context = self._mpv_module.MpvRenderContext(
                self._mpv,
                'opengl',
                opengl_init_params={'get_proc_address': self._gl_get_proc_wrapper},
            )
            widget_ref = weakref.ref(widget)

            def _request_mpv_frame():
                target = widget_ref()
                if target is None:
                    return
                try:
                    QMetaObject.invokeMethod(
                        target,
                        'request_mpv_frame',
                        Qt.ConnectionType.QueuedConnection,
                    )
                except RuntimeError:
                    return
                except Exception:
                    return

            self._render_context.update_cb = _request_mpv_frame
            self._render_widget = widget
            self._render_failure_logged = False
            self._apply_pending_video_state()
            return True
        except Exception as exc:
            self._backend_error = exc
            self._render_context = None
            if not self._render_failure_logged:
                print(f"[mpv] render context init failed: {exc}")
                self._render_failure_logged = True
            return False

    def render_frame(self, fbo, width, height):
        if getattr(self, '_render_driver', '') == 'native-d3d11':
            return False
        if self._render_context is None or self._render_widget is None:
            return False
        width = max(1, int(width or 0))
        height = max(1, int(height or 0))
        mirror = bool(getattr(self, '_presentation_mirror', False))
        vertical_mirror = bool(getattr(self, '_presentation_vertical_mirror', False))
        try:
            self._render_context.update()
            if mirror or vertical_mirror:
                presentation_fbo = self._ensure_presentation_fbo(width, height)
                if presentation_fbo is not None:
                    self._render_context.render(
                        opengl_fbo={'fbo': int(presentation_fbo.handle()), 'w': width, 'h': height},
                        flip_y=True,
                    )
                    if (
                        self._blit_presentation_fbo(presentation_fbo, int(fbo), width, height, mirror, vertical_mirror)
                        or self._draw_presentation_fbo(presentation_fbo, int(fbo), width, height, mirror, vertical_mirror)
                    ):
                        self._apply_transform_shader(False, False)
                        self._render_context.report_swap()
                        return True
                    # Last-resort fallback: keep mirror functional if the current
                    # OpenGL driver/context rejects the presentation shader path.
                    self._apply_transform_shader(mirror, vertical_mirror)

            self._render_context.render(
                opengl_fbo={'fbo': int(fbo), 'w': width, 'h': height},
                flip_y=True,
            )
            self._render_context.report_swap()
            return True
        except Exception as exc:
            if not self._render_failure_logged:
                print(f"[mpv] render failed: {exc}")
                self._render_failure_logged = True
            return False

    def _ensure_presentation_fbo(self, width, height):
        size = (int(width), int(height))
        fbo = getattr(self, '_presentation_fbo', None)
        if fbo is not None and getattr(self, '_presentation_fbo_size', None) == size:
            try:
                if fbo.isValid():
                    return fbo
            except Exception:
                return fbo
        try:
            self._presentation_fbo = QOpenGLFramebufferObject(size[0], size[1])
            self._presentation_fbo_size = size
            return self._presentation_fbo
        except Exception as exc:
            if not getattr(self, '_presentation_blit_failed_logged', False):
                print(f"[mpv] presentation mirror FBO failed: {exc}")
                self._presentation_blit_failed_logged = True
            self._presentation_fbo = None
            self._presentation_fbo_size = (0, 0)
            return None

    def _ensure_presentation_program(self):
        program = getattr(self, '_presentation_program', None)
        vao = getattr(self, '_presentation_vao', None)
        if program is not None and vao is not None:
            return program, vao
        vertex_source = """
            #version 130
            out vec2 v_uv;
            uniform int u_mirror;
            uniform int u_vmirror;
            void main() {
                vec2 positions[3] = vec2[](
                    vec2(-1.0, -1.0),
                    vec2( 3.0, -1.0),
                    vec2(-1.0,  3.0)
                );
                vec2 uvs[3] = vec2[](
                    vec2(0.0, 0.0),
                    vec2(2.0, 0.0),
                    vec2(0.0, 2.0)
                );
                vec2 uv = uvs[gl_VertexID];
                if (u_mirror != 0) {
                    uv.x = 1.0 - uv.x;
                }
                if (u_vmirror != 0) {
                    uv.y = 1.0 - uv.y;
                }
                v_uv = uv;
                gl_Position = vec4(positions[gl_VertexID], 0.0, 1.0);
            }
        """
        fragment_source = """
            #version 130
            uniform sampler2D u_texture;
            in vec2 v_uv;
            out vec4 frag_color;
            void main() {
                frag_color = texture(u_texture, v_uv);
            }
        """
        try:
            program = QOpenGLShaderProgram()
            if not program.addShaderFromSourceCode(QOpenGLShader.ShaderTypeBit.Vertex, vertex_source):
                raise RuntimeError(program.log())
            if not program.addShaderFromSourceCode(QOpenGLShader.ShaderTypeBit.Fragment, fragment_source):
                raise RuntimeError(program.log())
            if not program.link():
                raise RuntimeError(program.log())
            vao = QOpenGLVertexArrayObject()
            vao.create()
            self._presentation_program = program
            self._presentation_vao = vao
            return program, vao
        except Exception as exc:
            if not getattr(self, '_presentation_blit_failed_logged', False):
                print(f"[mpv] presentation mirror shader failed: {exc}")
                self._presentation_blit_failed_logged = True
            self._presentation_program = None
            self._presentation_vao = None
            return None, None

    def _get_gl_function(self, cache_name, gl_name, restype, argtypes):
        cached = getattr(self, cache_name, None)
        if cached is not None:
            return cached
        context = QOpenGLContext.currentContext()
        if context is None:
            return None
        aliases = {
            'glBindFramebuffer': ('glBindFramebuffer', 'glBindFramebufferEXT', 'glBindFramebufferARB'),
            'glBlitFramebuffer': ('glBlitFramebuffer', 'glBlitFramebufferEXT', 'glBlitFramebufferARB'),
            'glActiveTexture': ('glActiveTexture', 'glActiveTextureARB'),
        }.get(gl_name, (gl_name,))
        try:
            for candidate in aliases:
                address = context.getProcAddress(candidate)
                if address is None:
                    address = context.getProcAddress(candidate.encode('ascii'))
                if address is None:
                    continue
                try:
                    address = int(address)
                except Exception:
                    address = 0
                if address:
                    func = ctypes.CFUNCTYPE(restype, *argtypes)(address)
                    setattr(self, cache_name, func)
                    return func
        except Exception:
            pass
        if os.name == 'nt':
            try:
                opengl32 = ctypes.windll.opengl32
                for candidate in aliases:
                    func = getattr(opengl32, candidate, None)
                    if func is None:
                        continue
                    func.restype = restype
                    func.argtypes = list(argtypes)
                    setattr(self, cache_name, func)
                    return func
            except Exception:
                pass
        try:
            qt_function_cache = getattr(self, '_qt_gl_function_cache', None)
            if qt_function_cache is None:
                qt_function_cache = {}
                self._qt_gl_function_cache = qt_function_cache
            version_candidates = ((4, 1), (3, 3), (3, 0), (2, 1), (2, 0))
            for major, minor in version_candidates:
                cache_key = (major, minor)
                funcs = qt_function_cache.get(cache_key)
                if funcs is None:
                    profile = QOpenGLVersionProfile()
                    profile.setVersion(major, minor)
                    funcs = QOpenGLVersionFunctionsFactory.get(profile, context)
                    if funcs is None:
                        qt_function_cache[cache_key] = False
                        continue
                    try:
                        init = getattr(funcs, 'initializeOpenGLFunctions', None)
                        if callable(init):
                            init()
                    except Exception:
                        pass
                    qt_function_cache[cache_key] = funcs
                if funcs is False:
                    continue
                for candidate in aliases:
                    func = getattr(funcs, candidate, None)
                    if callable(func):
                        setattr(self, cache_name, func)
                        return func
        except Exception:
            pass
        return None

    def _blit_presentation_fbo(self, source_fbo, target_fbo, width, height, mirror=False, vertical_mirror=False):
        if mirror or vertical_mirror:
            return False  # glBlitFramebuffer coordinate swapping fails on some drivers
        bind_framebuffer = self._get_gl_function(
            '_gl_bind_framebuffer',
            'glBindFramebuffer',
            None,
            (ctypes.c_uint, ctypes.c_uint),
        )
        blit_framebuffer = self._get_gl_function(
            '_gl_blit_framebuffer',
            'glBlitFramebuffer',
            None,
            (
                ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int,
                ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int,
                ctypes.c_uint, ctypes.c_uint,
            ),
        )
        if bind_framebuffer is None or blit_framebuffer is None:
            if not getattr(self, '_presentation_blit_failed_logged', False):
                print("[mpv] presentation mirror unavailable: OpenGL blit functions missing")
                self._presentation_blit_failed_logged = True
            return False
        GL_READ_FRAMEBUFFER = 0x8CA8
        GL_DRAW_FRAMEBUFFER = 0x8CA9
        GL_COLOR_BUFFER_BIT = 0x00004000
        GL_NEAREST = 0x2600
        try:
            src_x0 = width if mirror else 0
            src_x1 = 0 if mirror else width
            src_y0 = height if vertical_mirror else 0
            src_y1 = 0 if vertical_mirror else height
            bind_framebuffer(GL_READ_FRAMEBUFFER, int(source_fbo.handle()))
            bind_framebuffer(GL_DRAW_FRAMEBUFFER, int(target_fbo))
            blit_framebuffer(
                int(src_x0), int(src_y0), int(src_x1), int(src_y1),
                0, 0, int(width), int(height),
                GL_COLOR_BUFFER_BIT,
                GL_NEAREST,
            )
            return True
        except Exception as exc:
            if not getattr(self, '_presentation_blit_failed_logged', False):
                print(f"[mpv] presentation mirror blit failed: {exc}")
                self._presentation_blit_failed_logged = True
            return False

    def _draw_presentation_fbo(self, source_fbo, target_fbo, width, height, mirror=False, vertical_mirror=False):
        program, vao = self._ensure_presentation_program()
        if program is None or vao is None:
            return False
        bind_framebuffer = self._get_gl_function(
            '_gl_bind_framebuffer',
            'glBindFramebuffer',
            None,
            (ctypes.c_uint, ctypes.c_uint),
        )
        viewport = self._get_gl_function(
            '_gl_viewport',
            'glViewport',
            None,
            (ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int),
        )
        active_texture = self._get_gl_function(
            '_gl_active_texture',
            'glActiveTexture',
            None,
            (ctypes.c_uint,),
        )
        bind_texture = self._get_gl_function(
            '_gl_bind_texture',
            'glBindTexture',
            None,
            (ctypes.c_uint, ctypes.c_uint),
        )
        draw_arrays = self._get_gl_function(
            '_gl_draw_arrays',
            'glDrawArrays',
            None,
            (ctypes.c_uint, ctypes.c_int, ctypes.c_int),
        )
        disable = self._get_gl_function(
            '_gl_disable',
            'glDisable',
            None,
            (ctypes.c_uint,),
        )
        if None in (bind_framebuffer, viewport, active_texture, bind_texture, draw_arrays, disable):
            return self._blit_presentation_fbo(source_fbo, target_fbo, width, height, mirror, vertical_mirror)
        GL_FRAMEBUFFER = 0x8D40
        GL_TEXTURE0 = 0x84C0
        GL_TEXTURE_2D = 0x0DE1
        GL_TRIANGLES = 0x0004
        GL_BLEND = 0x0BE2
        GL_DEPTH_TEST = 0x0B71
        GL_STENCIL_TEST = 0x0B90
        try:
            bind_framebuffer(GL_FRAMEBUFFER, int(target_fbo))
            viewport(0, 0, int(width), int(height))
            disable(GL_BLEND)
            disable(GL_DEPTH_TEST)
            disable(GL_STENCIL_TEST)
            if not program.bind():
                return False
            try:
                program.setUniformValue('u_texture', 0)
                program.setUniformValue('u_mirror', 1 if mirror else 0)
                program.setUniformValue('u_vmirror', 1 if vertical_mirror else 0)
                active_texture(GL_TEXTURE0)
                bind_texture(GL_TEXTURE_2D, int(source_fbo.texture()))
                vao.bind()
                try:
                    draw_arrays(GL_TRIANGLES, 0, 3)
                finally:
                    vao.release()
                    bind_texture(GL_TEXTURE_2D, 0)
            finally:
                program.release()
            return True
        except Exception as exc:
            if not getattr(self, '_presentation_blit_failed_logged', False):
                print(f"[mpv] presentation mirror draw failed: {exc}")
                self._presentation_blit_failed_logged = True
            return False

    def apply_video_state(self, *, mirror=False, vertical_mirror=False, rotation=0.0, zoom=1.0, pan_x=0.0, pan_y=0.0, vr_half=False):
        self._pending_video_state = {
            'mirror': bool(mirror),
            'vertical_mirror': bool(vertical_mirror),
            'rotation': float(rotation or 0.0),
            'zoom': max(0.1, min(3.0, float(zoom or 1.0))),
            'pan_x': max(-1.0, min(1.0, float(pan_x or 0.0))),
            'pan_y': max(-1.0, min(1.0, float(pan_y or 0.0))),
            'vr_half': bool(vr_half),
        }
        self._apply_pending_video_state()

    def _apply_pending_video_state(self):
        if self._mpv is None or not self._pending_video_state:
            return
        state = self._pending_video_state
        rotation = float(state.get('rotation', 0.0) or 0.0)
        mirror = bool(state['mirror'])
        vertical_mirror = bool(state['vertical_mirror'])
        if mirror and vertical_mirror:
            rotation = (rotation + 180.0) % 360.0
            mirror = False
            vertical_mirror = False
        right_angle = self._right_angle_rotation(rotation)
        display_rotation = right_angle
        vr_half = bool(state.get('vr_half', False))

        # ── VR Half: use MPV video-crop (VO-level, hwdec-safe) ───────────────────
        # lavfi crop= needs CPU frames and silently fails with native d3d11va
        # (zero-copy HW decode — frames never leave GPU).  video-crop is applied
        # by the VO after all decode stages; works with d3d11va and URL streams.
        # Format: "WxH+X+Y" pixels — read actual dimensions from MPV so the crop
        # is pixel-perfect regardless of aspect ratio.
        if vr_half:
            try:
                vp = self._mpv._get_property('video-params') or {}
                vw = int(vp.get('w') or 0)
                vh = int(vp.get('h') or 0)
            except Exception:
                vw, vh = 0, 0
            crop_str = f"{vw // 2}x{vh}+0+0" if (vw > 0 and vh > 0) else ""
            # If dims not ready yet, leave crop_str="" (not cached) so the
            # file-loaded callback retries with real dimensions.
        else:
            crop_str = ""

        if crop_str != (self._last_video_crop or ""):
            try:
                self._mpv["video-crop"] = crop_str
                self._last_video_crop = crop_str
            except Exception as exc:
                print(f"[mpv] video-crop update failed: {exc}")

        # ── Rotation filter ───────────────────────────────────────────────────────
        # Right-angle rotations use video-rotate (VO-level, hwdec-safe).
        # Non-right-angle rotations need lavfi which requires CPU frames —
        # switch hwdec to d3d11va-copy first so frames are copied to RAM.
        need_lavfi_rotate = (display_rotation is None and abs(rotation) >= 0.05)
        filters = []
        if need_lavfi_rotate:
            radians = math.radians(rotation)
            filters.append(f"@ag_rotate:lavfi=[rotate={radians:.6f}:c=black:ow='rotw({radians:.6f})':oh='roth({radians:.6f})']")
        filter_chain = ','.join(filters)

        if need_lavfi_rotate:
            copy_mode = 'd3d11va-copy' if os.name == 'nt' else 'auto-copy-safe'
            try:
                if 'copy' not in str(self._mpv.hwdec or '').lower():
                    self._mpv['hwdec'] = copy_mode
            except Exception:
                pass
        else:
            try:
                if 'copy' in str(self._mpv.hwdec or '').lower():
                    self._mpv['hwdec'] = 'd3d11va' if os.name == 'nt' else 'auto-safe'
            except Exception:
                pass

        # ── Zoom / pan ────────────────────────────────────────────────────────────
        # When VR half is active the video-crop already selects the left half and
        # MPV scales that cropped region to fill the viewport at 1× zoom.
        # User zoom/pan still works on top of the crop — the cropped region is
        # treated as the full video by the VO, so zoom/pan behave identically to
        # normal playback.  Just pass the user values straight through; no override.
        zoom_value = math.log2(state['zoom'])
        pan_x = max(-1.0, min(1.0, float(state.get('pan_x', 0.0))))
        pan_y = max(-1.0, min(1.0, float(state.get('pan_y', 0.0))))

        transform_pipeline_changed = False

        target_video_rotate = int(display_rotation if display_rotation is not None else 0)
        if target_video_rotate != self._last_video_rotate:
            try:
                self._mpv['video-rotate'] = target_video_rotate
                self._last_video_rotate = target_video_rotate
                transform_pipeline_changed = True
            except Exception as exc:
                print(f"[mpv] video-rotate update failed: {exc}")

        if filter_chain != self._last_filter_chain:
            try:
                self._mpv.command('vf', 'set', filter_chain if filter_chain else '')
                self._last_filter_chain = filter_chain
                transform_pipeline_changed = True
            except Exception as exc:
                print(f"[mpv] filter update failed: {exc}")

        use_shader_mirror = bool(mirror or vertical_mirror)
        shader_mirror = mirror if use_shader_mirror else False
        shader_vertical = vertical_mirror if use_shader_mirror else False
        presentation_mirror = False if use_shader_mirror else mirror
        presentation_vertical = False if use_shader_mirror else vertical_mirror
        if self._apply_transform_shader(shader_mirror, shader_vertical):
            transform_pipeline_changed = True
        if self._set_presentation_mirror(presentation_mirror, presentation_vertical):
            transform_pipeline_changed = True

        if self._last_video_zoom is None or abs(zoom_value - self._last_video_zoom) >= 0.0001:
            try:
                self._mpv.video_zoom = zoom_value
                self._last_video_zoom = zoom_value
            except Exception as exc:
                print(f"[mpv] zoom update failed: {exc}")

        if self._last_video_pan_x is None or abs(pan_x - self._last_video_pan_x) >= 0.0001:
            try:
                self._mpv.video_pan_x = pan_x
                self._last_video_pan_x = pan_x
            except Exception as exc:
                print(f"[mpv] pan-x update failed: {exc}")

        if self._last_video_pan_y is None or abs(pan_y - self._last_video_pan_y) >= 0.0001:
            try:
                self._mpv.video_pan_y = pan_y
                self._last_video_pan_y = pan_y
            except Exception as exc:
                print(f"[mpv] pan-y update failed: {exc}")

        if transform_pipeline_changed:
            QTimer.singleShot(0, self._nudge_after_transform_change)

    def show_text(self, text, duration_ms=1500):
        if self._mpv is None:
            return
        try:
            self._mpv.command('show-text', str(text), int(duration_ms))
        except Exception:
            pass

    def get_property(self, name, default=None):
        return self._get_mpv_property(name, default)

    def set_property(self, name, value):
        if self._mpv is None:
            return False
        try:
            self._mpv._set_property(str(name), value)
            return True
        except Exception:
            try:
                self._mpv[str(name)] = value
                return True
            except Exception as exc:
                print(f"[mpv] set property failed: {name}={value!r}: {exc}")
                return False

    def terminate(self):
        try:
            if self._render_context is not None:
                self._render_context.free()
        except Exception:
            pass
        self._render_context = None

        try:
            if self._mpv is not None:
                self._mpv.terminate()
        except Exception:
            pass
        self._mpv = None


class PdfEdgeSwitchTrigger(QWidget):
    activated = pyqtSignal()

    def __init__(self, side='left'):
        flags = (
            Qt.WindowType.ToolTip
            | Qt.WindowType.FramelessWindowHint
            | Qt.WindowType.WindowStaysOnTopHint
        )
        no_focus_flag = getattr(Qt.WindowType, 'WindowDoesNotAcceptFocus', None)
        if no_focus_flag is not None:
            flags |= no_focus_flag
        super().__init__(None, flags)
        self.side = side if side in ('left', 'right') else 'left'
        self._screen_geometry = QRect()
        self._collapsed_width = 0
        self._expanded_width = 52
        self._button_height = 26
        self._expanded = False
        self.setAttribute(Qt.WidgetAttribute.WA_ShowWithoutActivating, True)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setMouseTracking(True)
        self.setCursor(Qt.CursorShape.PointingHandCursor)

        self.button = QPushButton("PDF", self)
        self.button.setToolTip("Bring the PDF player to the front")
        self.button.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        self.button.setStyleSheet("""
            QPushButton {
                background-color: rgba(18, 18, 18, 235);
                color: white;
                border: 1px solid rgba(255, 255, 255, 78);
                border-radius: 10px;
                padding: 1px 6px;
                font-weight: 600;
                font-size: 10px;
            }
            QPushButton:hover {
                background-color: rgba(34, 34, 34, 242);
                border-color: rgba(120, 190, 255, 210);
            }
            QPushButton:pressed {
                background-color: rgba(58, 142, 230, 235);
            }
        """)
        self.button.clicked.connect(lambda checked=False: self.activated.emit())
        self.button.hide()
        self.hide()

    def _pin_topmost(self):
        if os.name != 'nt':
            return
        try:
            hwnd = int(self.winId())
            ctypes.windll.user32.ShowWindow(hwnd, SW_SHOWNOACTIVATE)
            ctypes.windll.user32.SetWindowPos(
                hwnd,
                HWND_TOPMOST,
                0,
                0,
                0,
                0,
                SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE | SWP_SHOWWINDOW | SWP_NOOWNERZORDER,
            )
        except Exception:
            pass

    def set_screen_geometry(self, rect):
        self._screen_geometry = QRect(rect)
        if self._screen_geometry.isNull():
            self.hide()
            return
        self.collapse()

    def show_trigger(self):
        if self._screen_geometry.isNull():
            return
        self._set_expanded(True)

    def collapse(self):
        self._expanded = False
        self.button.hide()
        self.hide()

    def _target_y(self):
        rect = self._screen_geometry
        if rect.isNull():
            return 0
        return rect.top()

    def _apply_geometry(self, width):
        rect = self._screen_geometry
        if rect.isNull():
            return
        y = self._target_y()
        height = max(1, rect.height())
        if self.side == 'left':
            x = rect.left()
        else:
            x = rect.right() - width + 1
        self.setGeometry(x, y, width, height)
        button_y = max(20, (height - self._button_height) // 2)
        self.button.setGeometry(0, button_y, width, self._button_height)

    def _set_expanded(self, expanded):
        expanded = bool(expanded)
        self._expanded = expanded
        width = self._expanded_width if expanded else max(1, self._collapsed_width)
        self._apply_geometry(width)
        self.button.setVisible(expanded)
        if self._screen_geometry.isNull() or not expanded:
            self.hide()
            return
        self.show()
        self.raise_()
        self._pin_topmost()
        self.update()

    def contains_global_pos(self, global_pos):
        if global_pos is None or not self.isVisible():
            return False
        try:
            return self.geometry().contains(global_pos)
        except Exception:
            return False

    def enterEvent(self, event):
        self._set_expanded(True)
        super().enterEvent(event)

    def leaveEvent(self, event):
        QTimer.singleShot(0, self._collapse_if_outside)
        super().leaveEvent(event)

    def _collapse_if_outside(self):
        try:
            if not self.rect().contains(self.mapFromGlobal(QCursor.pos())):
                self._set_expanded(False)
        except Exception:
            self._set_expanded(False)

    def paintEvent(self, event):
        if self._expanded:
            super().paintEvent(event)

    def mouseReleaseEvent(self, event):
        try:
            if event.button() == Qt.MouseButton.LeftButton:
                self.activated.emit()
                event.accept()
                return
        except Exception:
            pass
        super().mouseReleaseEvent(event)
    def terminate(self):
        try:
            if self._render_context is not None:
                self._render_context.free()
        except Exception:
            pass
        self._render_context = None

        try:
            if self._mpv is not None:
                self._mpv.terminate()
        except Exception:
            pass
        self._mpv = None


class PdfTocPopup(QFrame):
    pageSelected = pyqtSignal(int)
    popupHidden = pyqtSignal()

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setObjectName("pdfTocPopup")
        self.setStyleSheet("""
            QFrame#pdfTocPopup {
                background-color: rgba(14, 14, 14, 242);
                border: 1px solid rgba(255, 255, 255, 78);
                border-radius: 10px;
            }
            QLabel {
                color: white;
                font-weight: 600;
                background: transparent;
            }
            QTreeWidget {
                background: transparent;
                color: white;
                border: none;
                outline: none;
                selection-background-color: rgba(58, 142, 230, 210);
                selection-color: white;
            }
            QTreeWidget::item {
                padding: 4px 6px;
            }
            QScrollBar:vertical {
                background: rgba(255, 255, 255, 18);
                width: 10px;
                border-radius: 5px;
                margin: 2px;
            }
            QScrollBar::handle:vertical {
                background: rgba(255, 255, 255, 95);
                min-height: 24px;
                border-radius: 5px;
            }
            QScrollBar::add-line:vertical,
            QScrollBar::sub-line:vertical,
            QScrollBar::add-page:vertical,
            QScrollBar::sub-page:vertical {
                background: transparent;
                height: 0px;
            }
        """)

        layout = QVBoxLayout(self)
        layout.setContentsMargins(8, 8, 8, 8)
        layout.setSpacing(6)

        self.title_label = QLabel("Table of Contents", self)
        layout.addWidget(self.title_label)

        self.tree = QTreeWidget(self)
        self.tree.setHeaderHidden(True)
        self.tree.setRootIsDecorated(True)
        self.tree.setIndentation(18)
        self.tree.setUniformRowHeights(True)
        self.tree.setSelectionMode(QAbstractItemView.SelectionMode.SingleSelection)
        self.tree.setVerticalScrollMode(QAbstractItemView.ScrollMode.ScrollPerPixel)
        self.tree.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.tree.itemClicked.connect(self._activate_item)
        self.tree.itemActivated.connect(self._activate_item)
        layout.addWidget(self.tree)

    def populate(self, entries, current_page=0):
        self.tree.clear()
        root = self.tree.invisibleRootItem()
        parent_stack = {0: root}
        best_item = None
        best_distance = None

        for entry in list(entries or []):
            if not isinstance(entry, (list, tuple)) or len(entry) < 3:
                continue
            try:
                level = max(1, int(entry[0] or 1))
            except Exception:
                level = 1
            title = str(entry[1] or "").strip()
            if not title:
                continue
            try:
                page_index = max(0, int(entry[2] or 1) - 1)
            except Exception:
                page_index = 0

            while level - 1 not in parent_stack and level > 1:
                level -= 1
            parent_item = parent_stack.get(level - 1, root)
            item = QTreeWidgetItem(parent_item, [f"{title}  [p{page_index + 1}]"])
            item.setData(0, Qt.ItemDataRole.UserRole, page_index)
            parent_stack[level] = item
            for stack_level in list(parent_stack.keys()):
                if stack_level > level:
                    del parent_stack[stack_level]

            distance = abs(page_index - max(0, int(current_page or 0)))
            if best_distance is None or distance < best_distance:
                best_distance = distance
                best_item = item

        self.tree.expandAll()
        if best_item is not None:
            self.tree.setCurrentItem(best_item)
            self.tree.scrollToItem(best_item, QAbstractItemView.ScrollHint.PositionAtCenter)

    def show_at(self, global_pos, screen_rect=None):
        screen_rect = QRect(screen_rect) if screen_rect is not None else QRect()
        target_width = 360
        row_height = max(22, self.tree.sizeHintForRow(0))
        item_count = max(1, self.tree.topLevelItemCount())
        visible_rows = min(max(item_count + 2, 8), 18)
        target_height = 42 + (visible_rows * row_height) + 16
        if not screen_rect.isNull():
            target_height = min(target_height, max(220, int(screen_rect.height() * 0.72)))
            target_width = min(target_width, max(240, int(screen_rect.width() * 0.42)))
        self.resize(target_width, target_height)

        x = int(global_pos.x())
        y = int(global_pos.y())
        if not screen_rect.isNull():
            x = max(screen_rect.left() + 8, min(x, screen_rect.right() - self.width() - 8))
            y = max(screen_rect.top() + 8, min(y, screen_rect.bottom() - self.height() - 8))
        parent = self.parentWidget()
        if parent is not None:
            local_pos = parent.mapFromGlobal(QPoint(x, y))
            x = max(8, min(local_pos.x(), parent.width() - self.width() - 8))
            y = max(8, min(local_pos.y(), parent.height() - self.height() - 8))
        self.move(x, y)
        self.show()
        self.raise_()
        self.tree.setFocus(Qt.FocusReason.PopupFocusReason)

    def _activate_item(self, item, column=0):
        if item is None:
            return
        try:
            page_index = int(item.data(0, Qt.ItemDataRole.UserRole))
        except Exception:
            return
        self.hide()
        self.pageSelected.emit(page_index)

    def hideEvent(self, event):
        self.popupHidden.emit()
        super().hideEvent(event)

    def keyPressEvent(self, event):
        try:
            if event.key() == Qt.Key.Key_Escape:
                self.hide()
                event.accept()
                return
        except Exception:
            pass
        super().keyPressEvent(event)


# --- Phone Sync Feature ---

class PhoneSyncHandler(http.server.BaseHTTPRequestHandler):
    """Handles file uploads, streaming, and directory sync from the phone"""
    
    def log_message(self, format, *args):
        pass # Suppress log noise

    def do_GET(self):
        """Serve portal or keep SSE connection open"""
        if self.path == '/control_stream':
            # Server-Sent Events for PC -> Phone commands
            self.send_response(200)
            self.send_header('Content-Type', 'text/event-stream')
            self.send_header('Cache-Control', 'no-cache')
            self.send_header('Connection', 'keep-alive')
            self.send_header('Access-Control-Allow-Origin', '*')
            self.end_headers()
            
            # Register this connection
            q = threading.Event()
            conn_id = id(self)
            self.server.active_connections[conn_id] = self
            print(f"Phone connected to control stream ({conn_id})")
            
            try:
                while not self.server._stop_event.is_set():
                    # Send Heartbeat
                    try:
                        self.wfile.write(b": heartbeat\n\n")
                        self.wfile.flush()
                    except (ConnectionResetError, ConnectionAbortedError):
                        print("Heartbeat failed, connection closed.")
                        break
                    
                    # Flush all pending requests immediately
                    if hasattr(self.server, 'request_queue'):
                        while self.server.request_queue:
                            request = self.server.request_queue.pop(0)
                            if request:
                                # Send command to phone
                                msg = f"event: REQUEST_FILE\ndata: {json.dumps(request)}\n\n"
                                self.wfile.write(msg.encode('utf-8'))
                                self.wfile.flush()
                                print(f"DEBUG: Sent request for {os.path.basename(request.get('path',''))}")
                    
                    # More frequent polling for better responsiveness
                    threading.Event().wait(0.1) 
            except Exception as e:
                print(f"SSE Connection {conn_id} closed: {e}")
            finally:
                if conn_id in self.server.active_connections:
                    del self.server.active_connections[conn_id]
            return

        # Default: Serve Portal
        try:
            html = self.get_portal_html()
            self.send_response(200)
            self.send_header('Content-Type', 'text/html; charset=utf-8')
            self.send_header('Content-Length', len(html))
            self.end_headers()
            self.wfile.write(html.encode('utf-8'))
        except Exception as e:
            self.send_error(500, str(e))

    def do_POST(self):
        """Handle uploads, structure updates, and streaming"""
        if self.path.startswith('/log_event'):
            # Diagnostic endpoint for phone-side errors
            try:
                params = parse_qs(self.path.split('?')[-1])
                msg = params.get('msg', [''])[0]
                print(f"PHONE LOG: {msg}")
                self.send_response(200)
                self.end_headers()
            except:
                self.send_error(500)
            return

        if self.path == '/update_structure':
            try:
                content_length = int(self.headers.get('Content-Length', 0))
                body = self.rfile.read(content_length)
                data = json.loads(body.decode('utf-8'))
                self.server.signals.structure_updated.emit(data)
                self.send_response(200)
                self.end_headers()
            except Exception as e:
                self.send_error(500, str(e))
            return

        if self.path == '/stream_upload':
            # Phone is "pushing" a requested file chunk
            try:
                content_type = self.headers.get('Content-Type', '')
                content_length = int(self.headers.get('Content-Length', 0))
                filename = self.headers.get('X-File-Path', 'unknown')
                
                body = self.rfile.read(content_length)
                
                # Check for multipart if used, but let's prefer raw binary for streaming
                if 'multipart/form-data' in content_type:
                    from email.parser import BytesParser
                    headers_raw = f"Content-Type: {content_type}\r\n\r\n".encode('ascii')
                    msg = BytesParser().parsebytes(headers_raw + body)
                    for part in msg.get_payload():
                        if part.get_filename():
                            body = part.get_payload(decode=True)
                            break

                # Write to temp and notify
                # Ensure filename is unquoted to match what the PC expects
                from urllib.parse import unquote
                filename = unquote(filename)
                
                temp_path = os.path.join(self.server.upload_dir, ".streaming_" + os.path.basename(filename))
                with open(temp_path, 'wb') as f:
                    f.write(body)
                
                print(f"DEBUG: Chunk received for {os.path.basename(filename)} ({len(body)} bytes)")
                self.server.signals.file_streamed.emit(filename, temp_path)
                
                self.send_response(200)
                self.end_headers()
            except Exception as e:
                print(f"Stream error for {filename}: {e}")
                self.send_error(500, str(e))
            return

        # Original do_POST for manual uploads (legacy compatibility)
        try:
            content_type = self.headers.get('Content-Type')
            content_length = int(self.headers.get('Content-Length', 0))
            if content_length == 0:
                self.send_error(400, "Empty request")
                return
            body = self.rfile.read(content_length)
            from email.parser import BytesParser
            headers_raw = f"Content-Type: {content_type}\r\n\r\n".encode('ascii')
            msg = BytesParser().parsebytes(headers_raw + body)
            received_files = []
            if msg.is_multipart():
                for part in msg.get_payload():
                    filename = part.get_filename()
                    if filename:
                        filename = os.path.basename(filename)
                        save_path = os.path.join(self.server.upload_dir, filename)
                        payload = part.get_payload(decode=True)
                        if payload:
                            with open(save_path, 'wb') as f: f.write(payload)
                            received_files.append(filename)
                            self.server.signals.file_received.emit(save_path)
            if received_files:
                self.send_response(200)
                self.end_headers()
                self.wfile.write(b"Success")
            else: self.send_error(400, "No files")
        except Exception as e:
            self.send_error(500, str(e))

