    def _update_selection_info_bar(self):
        """Show/update the centered menu-bar info bar when 2+ playlist items are selected."""
        if not hasattr(self, 'selection_info_bar'):
            return
        pw = getattr(self, 'playlist_widget', None)
        if pw is None:
            self.selection_info_bar.setVisible(False)
            return

        selected_rows = sorted(set(idx.row() for idx in pw.selectedIndexes()))
        count = len(selected_rows)

        if count < 2:
            self.selection_info_bar.setVisible(False)
            self._reposition_hb_overlay()
            return

        playlist = getattr(self, 'playlist', [])
        total_ms = 0
        total_bytes = 0
        for row in selected_rows:
            if row < len(playlist):
                fp = playlist[row]
                dur = int(getattr(self, 'video_durations', {}).get(fp, 0) or 0)
                total_ms += dur
                total_bytes += self._playlist_size_bytes(fp)
                if dur == 0 and self._is_ftp_url(fp) and hasattr(self, 'analyze_ftp_video_async'):
                    self.analyze_ftp_video_async(fp)

        # Format total duration
        secs = total_ms // 1000
        h, rem = divmod(secs, 3600)
        m, s = divmod(rem, 60)
        if h > 0:
            dur_str = f"{h}h {m:02}m {s:02}s"
        elif m > 0:
            dur_str = f"{m}m {s:02}s"
        else:
            dur_str = f"{s}s" if total_ms > 0 else ""

        size_str = self._format_size_bytes(total_bytes) if total_bytes > 0 else ""

        quality_str = ""
        if total_bytes > 0 and total_ms > 0:
            mb_sec = (total_bytes / 1048576) / (total_ms / 1000.0)
            quality_str = f"{mb_sec:.2f} MB/s"

        parts = [f"{count} items"]
        if dur_str:
            parts.append(dur_str)
        if size_str:
            parts.append(size_str)
        if quality_str:
            parts.append(quality_str)

        self.selection_info_bar.setText("  •  ".join(parts))
        self.selection_info_bar.adjustSize()
        self.selection_info_bar.setVisible(True)
        self.selection_info_bar.raise_()
        self._reposition_hb_overlay()

    def _sync_playlist_header_alignment(self):
        """Keep playlist headers centered even when sorting indicators appear."""
        if not hasattr(self, 'playlist_widget'):
            return
        hdr = self.playlist_widget.horizontalHeader()
        hdr.setDefaultAlignment(Qt.AlignmentFlag.AlignCenter)
        hdr.setTextElideMode(Qt.TextElideMode.ElideNone)
        for col in range(self.playlist_widget.columnCount()):
            item = self.playlist_widget.horizontalHeaderItem(col)
            if item:
                item.setTextAlignment(int(Qt.AlignmentFlag.AlignCenter))
        self._ensure_playlist_header_spacing()

    def _ensure_playlist_header_spacing(self):
        """Reserve enough width so sort arrows do not clip header text."""
        if not hasattr(self, 'playlist_widget'):
            return
        hdr = self.playlist_widget.horizontalHeader()
        metrics = hdr.fontMetrics()
        indicator_room = 22
        for col in range(self.playlist_widget.columnCount()):
            item = self.playlist_widget.horizontalHeaderItem(col)
            if not item:
                continue
            label = item.text() or ""
            if not label:
                continue
            required = metrics.horizontalAdvance(label) + indicator_room + 26
            if hdr.sectionResizeMode(col) != QHeaderView.ResizeMode.Stretch and hdr.sectionSize(col) < required:
                hdr.resizeSection(col, required)

    def _base_playlist_header_label(self, table_col):
        if table_col == 0:
            return "Name"
        if table_col == 1:
            return "Duration"
        if table_col == 2:
            return "Size"
        if table_col == 3:
            return "MB/sec"
        for col_id, mapped_col in getattr(self, '_extra_cols', {}).items():
            if mapped_col == table_col:
                return self._EXTRA_COL_LABELS.get(col_id, "?")
        return ""

    def _refresh_playlist_header_labels(self):
        """Draw sort direction in header text so the native arrow does not clip labels."""
        if not hasattr(self, 'playlist_widget'):
            return
        hdr = self.playlist_widget.horizontalHeader()
        hdr.setSortIndicatorShown(False)

        sorted_table_col = None
        if self._sort_last_col is not None:
            if self._sort_last_col <= 3:
                sorted_table_col = self._sort_last_col
            else:
                sorted_table_col = self._extra_cols.get(self._sort_last_col)

        arrow = " ↑" if getattr(self, '_sort_ascending', True) else " ↓"
        for table_col in range(self.playlist_widget.columnCount()):
            base_label = self._base_playlist_header_label(table_col)
            if not base_label:
                continue
            label = base_label + (arrow if table_col == sorted_table_col else "")
            item = self.playlist_widget.horizontalHeaderItem(table_col)
            if item is None:
                self.playlist_widget.setHorizontalHeaderItem(table_col, QTableWidgetItem(label))
                item = self.playlist_widget.horizontalHeaderItem(table_col)
            else:
                item.setText(label)
            if item:
                item.setTextAlignment(int(Qt.AlignmentFlag.AlignCenter))
        self._ensure_playlist_header_spacing()

    def _get_current_screen_transform_label(self):
        presets = getattr(self, '_SCREEN_TRANSFORM_PRESETS', ())
        if not presets:
            return "Normal"
        idx = getattr(self, 'screen_transform_cycle_index', 0) % len(presets)
        return presets[idx][0]

    def _get_now_playing_source_label(self):
        current = getattr(self, 'current_file', '') or ''
        lower = current.lower()
        if current.startswith("phone://"):
            return "Phone FTP"
        if getattr(self, 'is_cbz_active', False):
            if lower.endswith('.pdf'):
                return "PDF"
            if lower.endswith('.cbz'):
                return "Local CBZ"
            return "Local Chapter"
        if lower.endswith('.pdf'):
            return "PDF"
        if lower.endswith(AUDIO_EXTENSIONS):
            return "Audio"
        if lower.endswith(IMAGE_EXTENSIONS):
            return "Image"
        if lower.endswith(ARCHIVE_EXTENSIONS):
            return "Archive"
        if lower.endswith(VIDEO_EXTENSIONS):
            return "Video"
        return "Local"

    def _get_now_playing_progress_label(self):
        if getattr(self, 'is_cbz_active', False) and getattr(self, 'cbz_images', None):
            current_page = max(1, getattr(self, 'cbz_index', 0) + 1)
            total_pages = len(self.cbz_images)
            return f"Page {current_page}/{total_pages}"

        current = getattr(self, 'current_file', '') or ''
        if current and current.lower().endswith('.pdf') and getattr(self, 'cbz_images', None):
            current_page = max(1, getattr(self, 'cbz_index', 0) + 1)
            total_pages = len(self.cbz_images)
            return f"Page {current_page}/{total_pages}"

        duration = 0
        position = 0
        try:
            duration = int(self.media_player.duration())
            position = int(self.media_player.position())
        except Exception:
            duration = 0
            position = 0

        if duration > 0:
            percent = int((position / duration) * 100)
            return f"{self._format_playback_time_text(position, duration)} ({percent}%)"

        if hasattr(self, 'image_item') and self.image_item.isVisible() and getattr(self, 'playlist', None):
            try:
                if self.current_file in self.playlist:
                    idx = self.playlist.index(self.current_file) + 1
                    return f"Media {idx}/{len(self.playlist)}"
            except Exception:
                pass
        return "Ready"

    def _get_now_playing_modes_label(self):
        modes = []
        if self._is_app_fullscreen():
            modes.append("Full")
        if getattr(self, 'vr_mode', False):
            modes.append("VR")
        if getattr(self, 'vr_half_mode', False):
            modes.append("½ SBS")
        if getattr(self, 'mirror_mode', False):
            modes.append("Mirror")
        if getattr(self, 'vertical_mirror_mode', False):
            modes.append("VFlip")
        if abs(getattr(self, 'video_rotation_degrees', 0.0)) >= 0.05:
            angle_value = float(getattr(self, 'video_rotation_degrees', 0.0) or 0.0)
            if angle_value > 180.0:
                angle_value -= 360.0
            angle = f"{angle_value:.0f}"
            modes.append(f"Rot {angle}")
        transform_label = self._get_current_screen_transform_label()
        if transform_label != "Normal":
            modes.append(f"$ {transform_label}")
        if getattr(self, 'rotation_mode_enabled', False):
            modes.append("R-Mode")
        if getattr(self, 'is_cbz_active', False):
            modes.append("Continuous" if getattr(self, 'cbz_continuous_mode', False) else "Page")
            if getattr(self, 'cbz_rtl_mode', False):
                modes.append("RTL")
        return ", ".join(modes) if modes else "None"

    def _build_now_playing_status_text(self):
        """Compose the full now-playing / now-reading summary line."""
        has_media = bool(getattr(self, 'current_file', None) or getattr(self, 'is_cbz_active', False))
        if not has_media:
            return ""

        current = getattr(self, 'current_file', '') or ''
        lower = current.lower()
        if getattr(self, 'is_cbz_active', False):
            kind = "Now Reading"
        elif lower.endswith(AUDIO_EXTENSIONS):
            kind = "Now Listening"
        elif lower.endswith(IMAGE_EXTENSIONS):
            kind = "Now Viewing"
        else:
            kind = "Now Playing"

        display_title = getattr(self, 'current_media_title', None) or (os.path.basename(current.rstrip('/\\')) if current else "")
        file_label = os.path.basename(current.rstrip('/\\')) if current else display_title
        chapter_label = display_title if display_title and display_title != file_label else ""
        series_label = getattr(self, 'current_media_series', None) or ""
        source_label = self._get_now_playing_source_label()
        progress_label = self._get_now_playing_progress_label()
        modes_label = self._get_now_playing_modes_label()

        primary_title = chapter_label or display_title or file_label
        if series_label and primary_title and series_label.strip() and series_label.strip() != primary_title.strip():
            primary_title = f"[{series_label}] {primary_title}"

        parts = []
        if primary_title:
            parts.append(primary_title)
        else:
            parts.append(kind)
        if chapter_label and chapter_label != primary_title:
            parts.append(f"Chapter: {chapter_label}")
        parts.append(f"Source: {source_label}")
        parts.append(f"Progress: {progress_label}")
        parts.append(f"Modes: {modes_label}")
        return " | ".join(parts)

    def update_now_playing_strip(self):
        """Mirror the media summary into the window title bar."""
        if not hasattr(self, 'now_playing_strip'):
            return

        status_text = self._build_now_playing_status_text()
        if not status_text:
            if self._last_now_playing_window_title != self.base_window_title:
                self.setWindowTitle(self.base_window_title)
                self._last_now_playing_window_title = self.base_window_title
            self.now_playing_strip.hide()
            return

        window_title = f"{status_text} - {self.base_window_title}"
        if self._last_now_playing_window_title != window_title:
            self.setWindowTitle(window_title)
            self._last_now_playing_window_title = window_title
        self.now_playing_strip.hide()

    def _move_preview_widget(self, global_pos):
        if not hasattr(self, 'hover_preview'):
            return
        local_pos = self.mapFromGlobal(global_pos)
        x = local_pos.x() + 18
        y = local_pos.y() + 18
        if x + self.hover_preview.width() > self.width() - 8:
            x = max(8, local_pos.x() - self.hover_preview.width() - 18)
        if y + self.hover_preview.height() > self.height() - 8:
            y = max(8, local_pos.y() - self.hover_preview.height() - 18)
        self.hover_preview.move(x, y)

    def _get_preview_trigger_mode(self):
        settings = getattr(self, 'settings', {}) or {}
        mode = str(settings.get('preview_trigger_mode', 'click')).strip().lower()
        return 'hover' if mode == 'hover' else 'click'

    def _get_show_hours_for_long_media(self):
        return self._get_time_display_mode() == 'long'

    def _get_time_display_mode(self):
        settings = getattr(self, 'settings', {}) or {}
        mode = str(settings.get('time_display_mode', '') or '').strip().lower()
        if mode in {'compact', 'long', 'remaining'}:
            return mode
        return 'long' if bool(settings.get('show_hours_for_long_media', False)) else 'compact'

    def _set_show_hours_for_long_media(self, enabled, show_feedback=True):
        self._set_time_display_mode('long' if enabled else 'compact', show_feedback=show_feedback)

    def _set_time_display_mode(self, mode, show_feedback=True):
        mode = str(mode or '').strip().lower()
        if mode not in {'compact', 'long', 'remaining'}:
            mode = 'compact'
        if not hasattr(self, 'settings') or not isinstance(self.settings, dict):
            self.settings = {}
        self.settings['time_display_mode'] = mode
        self.settings['show_hours_for_long_media'] = (mode == 'long')
        self.save_settings()
        if not self.is_cbz_active:
            self.update_time_label(self.media_player.position(), self.media_player.duration())
        else:
            self.update_now_playing_strip()
        if show_feedback:
            labels = {
                'compact': "Compact MM:SS",
                'long': "HH:MM:SS for long media",
                'remaining': "Remaining time",
            }
            label = labels.get(mode, "Compact MM:SS")
            self.show_osd(f"Time display: {label}", duration=1700)

    def toggle_time_label_format(self):
        modes = ['compact', 'long', 'remaining']
        current = self._get_time_display_mode()
        try:
            next_mode = modes[(modes.index(current) + 1) % len(modes)]
        except ValueError:
            next_mode = 'compact'
        self._set_time_display_mode(next_mode, show_feedback=True)

    def _set_preview_trigger_mode(self, mode):
        mode = 'hover' if str(mode).strip().lower() == 'hover' else 'click'
        current = self._get_preview_trigger_mode()
        if not hasattr(self, 'settings') or not isinstance(self.settings, dict):
            self.settings = {}
        self.settings['preview_trigger_mode'] = mode
        self.save_settings()
        self._hide_hover_preview()
        if current != mode:
            self.show_osd(f"Preview trigger: {mode.title()}", duration=1600)

    def _preview_paths_match(self, a, b):
        if not a or not b:
            return False
        a = str(a)
        b = str(b)
        if a.startswith("phone://") or b.startswith("phone://"):
            return a == b
        return self._normalize_playlist_path(a) == self._normalize_playlist_path(b)

    def _make_global_rect(self, widget, rect):
        if widget is None or rect is None or rect.isNull():
            return QRect()
        top_left = widget.mapToGlobal(rect.topLeft())
        bottom_right = widget.mapToGlobal(rect.bottomRight())
        return QRect(top_left, bottom_right).normalized()

    def _is_cursor_inside_hover_target(self, global_pos=None):
        rect = getattr(self, '_hover_preview_target_global_rect', QRect())
        if rect.isNull():
            return False
        point = global_pos or QCursor.pos()
        return rect.contains(point)

    def _hover_preview_target_at_global_pos(self, global_pos):
        if not global_pos:
            return None

        if hasattr(self, 'playlist_widget'):
            viewport = self.playlist_widget.viewport()
            local_pos = viewport.mapFromGlobal(global_pos)
            if viewport.rect().contains(local_pos):
                index = self.playlist_widget.indexAt(local_pos)
                if index.isValid():
                    item = self.playlist_widget.item(index.row(), 0)
                    if item:
                        return item.data(Qt.ItemDataRole.UserRole)

        if hasattr(self, 'read_mode_tree'):
            viewport = self.read_mode_tree.viewport()
            local_pos = viewport.mapFromGlobal(global_pos)
            if viewport.rect().contains(local_pos):
                item = self.read_mode_tree.itemAt(local_pos)
                if item:
                    item_kind = item.data(0, Qt.ItemDataRole(Qt.ItemDataRole.UserRole.value + 1))
                    path = item.data(0, Qt.ItemDataRole.UserRole)
                    if item_kind in ('chapter', 'self_chapter') and path:
                        return path

        return None

    def _reposition_hover_preview(self):
        if getattr(self, '_hover_preview_anchor_global_pos', None) is None:
            return
        self._move_preview_widget(self._hover_preview_anchor_global_pos)

    def _hide_hover_preview(self):
        if hasattr(self, '_hover_preview_timer'):
            self._hover_preview_timer.stop()
        if hasattr(self, '_hover_preview_anim_timer'):
            self._hover_preview_anim_timer.stop()
        self._hover_preview_pending = None
        self._hover_preview_path = None
        self._hover_preview_frames = []
        self._hover_preview_frame_index = 0
        self._hover_preview_anchor_global_pos = None
        self._hover_preview_target_global_rect = QRect()
        self._hover_preview_display_text = ""
        if hasattr(self, 'hover_preview'):
            self.hover_preview.hide()

    def _hide_pdf_edge_switch_buttons(self):
        for btn in (
            getattr(self, 'pdf_edge_switch_left_btn', None),
            getattr(self, 'pdf_edge_switch_right_btn', None),
        ):
            if btn is not None:
                btn.hide()

    def _layout_pdf_toc_button(self):
        btn = getattr(self, 'pdf_toc_button', None)
        if btn is None:
            return
        if self._is_app_fullscreen():
            media_top = 0
        elif hasattr(self, 'media_stack') and self.media_stack.isVisible():
            media_top = self.media_stack.mapTo(self, self.media_stack.rect().topLeft()).y()
        elif hasattr(self, 'video_view') and self.video_view.isVisible():
            media_top = self.video_view.mapTo(self, self.video_view.rect().topLeft()).y()
        else:
            media_top = 0
        btn.move(12, media_top + 12)
        btn.raise_()

    def _pdf_toc_hotspot_rect(self):
        btn = getattr(self, 'pdf_toc_button', None)
        if btn is None:
            return QRect()
        self._layout_pdf_toc_button()
        rect = QRect(btn.pos(), btn.size())
        rect.adjust(-16, -12, 28, 16)
        return rect

    def _update_pdf_toc_button(self, global_pos=None):
        btn = getattr(self, 'pdf_toc_button', None)
        if btn is None:
            return
        if (
            not self._is_pdf_document_open()
            or getattr(self, 'privacy_mode_active', False)
            or getattr(self, '_post_hibernate_media_gate_active', False)
        ):
            btn.hide()
            popup = getattr(self, 'pdf_toc_popup', None)
            if popup is not None and popup.isVisible():
                popup.hide()
            return
        self._layout_pdf_toc_button()
        if global_pos is None:
            global_pos = QCursor.pos()
        popup = getattr(self, 'pdf_toc_popup', None)
        popup_visible = bool(popup is not None and popup.isVisible())
        hotspot = self._pdf_toc_hotspot_rect()
        show_button = popup_visible
        try:
            local_pos = self.mapFromGlobal(global_pos)
        except Exception:
            local_pos = QPoint(-100000, -100000)
        top_left_band = QRect(0, max(0, btn.y() - 10), 120, 70)
        show_button = show_button or top_left_band.contains(local_pos)
        if not hotspot.isNull():
            show_button = show_button or hotspot.contains(local_pos)
        if show_button:
            btn.show()
            btn.raise_()
        else:
            btn.hide()

    def _build_pdf_toc_actions(self):
        actions = []
        pdf_path = getattr(self, '_current_pdf_path', None)
        for entry in list(getattr(self, '_current_pdf_toc_entries', []) or []):
            if not isinstance(entry, (list, tuple)) or len(entry) < 3:
                continue
            try:
                level = max(1, int(entry[0] or 1))
            except Exception:
                level = 1
            title = str(entry[1] or "").strip()
            if not title:
                continue
            try:
                page_index = max(0, int(entry[2] or 1) - 1)
            except Exception:
                page_index = 0
            prefix = "    " * max(0, min(level - 1, 6))
            actions.append({
                'label': f"{prefix}{title}  [p{page_index + 1}]",
                'callback': lambda path=pdf_path, page=page_index: self._jump_to_pdf_page(path, page),
            })
        return actions

    def show_current_pdf_toc_menu(self):
        if not self._is_pdf_document_open():
            return False
        toc_entries = list(getattr(self, '_current_pdf_toc_entries', []) or [])
        if not toc_entries:
            self.show_osd("No table of contents in this PDF", duration=1800)
            return False

        btn = getattr(self, 'pdf_toc_button', None)
        if btn is not None:
            global_pos = btn.mapToGlobal(QPoint(0, btn.height() + 4))
        else:
            global_pos = QCursor.pos()

        popup = getattr(self, 'pdf_toc_popup', None)
        if popup is None:
            return False
        if popup.isVisible():
            popup.hide()
            return True
        popup.populate(
            toc_entries,
            current_page=getattr(self, 'cbz_index', 0),
        )
        screen = QApplication.screenAt(global_pos) or QApplication.primaryScreen()
        popup.show_at(global_pos, screen.geometry() if screen is not None else QRect())
        self._update_pdf_toc_button(global_pos)
        return True

    def _is_altgr_key_event(self, event):
        try:
            key = event.key()
            modifiers = event.modifiers()
        except Exception:
            return False
        altgr_key = getattr(Qt.Key, 'Key_AltGr', None)
        if altgr_key is not None and key == altgr_key:
            return True
        alt_key = getattr(Qt.Key, 'Key_Alt', None)
        return (
            key == alt_key
            and bool(modifiers & Qt.KeyboardModifier.ControlModifier)
            and bool(modifiers & Qt.KeyboardModifier.AltModifier)
        )

    def _layout_pdf_edge_switch_buttons(self):
        left_btn = getattr(self, 'pdf_edge_switch_left_btn', None)
        right_btn = getattr(self, 'pdf_edge_switch_right_btn', None)
        if left_btn is None or right_btn is None:
            return

        if self._is_app_fullscreen():
            media_top = 0
            media_bottom = getattr(getattr(self, 'controls_widget', None), 'y', lambda: self.height())()
        elif hasattr(self, 'media_stack') and self.media_stack.isVisible():
            media_top = self.media_stack.mapTo(self, self.media_stack.rect().topLeft()).y()
            media_bottom = media_top + self.media_stack.height()
        elif hasattr(self, 'video_view') and self.video_view.isVisible():
            media_top = self.video_view.mapTo(self, self.video_view.rect().topLeft()).y()
            media_bottom = media_top + self.video_view.height()
        else:
            media_top = 0
            media_bottom = self.height()

        media_bottom = max(media_top + left_btn.height(), media_bottom)
        y = media_top + max(8, ((media_bottom - media_top) - left_btn.height()) // 2)
        margin = 8 if self._is_app_fullscreen() else 6
        left_btn.move(margin, y)
        right_btn.move(max(margin, self.width() - right_btn.width() - margin), y)
        left_btn.raise_()
        right_btn.raise_()

    def _update_pdf_edge_switch_buttons(self, global_pos=None):
        self._hide_pdf_edge_switch_buttons()

    def switch_back_to_previous_app_from_pdf(self):
        self._hide_pdf_edge_switch_buttons()
        self._pdf_edge_peek_mode = False
        if not self._is_pdf_document_open():
            return False
        if os.name == 'nt':
            try:
                user32 = ctypes.windll.user32
                target_hwnd = getattr(self, '_pdf_edge_return_hwnd', None)
                self._pdf_edge_return_hwnd = None
                if target_hwnd and user32.IsWindow(int(target_hwnd)):
                    try:
                        if user32.IsIconic(int(target_hwnd)):
                            user32.ShowWindow(int(target_hwnd), 9)
                    except Exception:
                        pass
                    try:
                        user32.SetForegroundWindow(int(target_hwnd))
                        return True
                    except Exception:
                        pass
                user32.keybd_event(0x12, 0, 0, 0)   # Alt down
                user32.keybd_event(0x09, 0, 0, 0)   # Tab down
                user32.keybd_event(0x09, 0, 2, 0)   # Tab up
                user32.keybd_event(0x12, 0, 2, 0)   # Alt up
                return True
            except Exception:
                pass
        self._pdf_edge_return_hwnd = None
        try:
            self.showMinimized()
            return True
        except Exception:
            return False

    def _hide_external_pdf_edge_triggers(self):
        for trigger in (
            getattr(self, 'pdf_external_trigger_left', None),
            getattr(self, 'pdf_external_trigger_right', None),
        ):
            if trigger is not None:
                try:
                    trigger.hide()
                    trigger.collapse()
                except Exception:
                    pass

    def _pdf_edge_trigger_screen_geometry(self):
        screen = None
        try:
            screen = QApplication.screenAt(QCursor.pos())
        except Exception:
            screen = None
        if screen is None:
            try:
                screen = QApplication.screenAt(self.frameGeometry().center())
            except Exception:
                screen = None
        if screen is None:
            screen = QApplication.primaryScreen()
        return screen.geometry() if screen is not None else QRect()

    def _should_show_external_pdf_edge_triggers(self):
        foreground_is_self = False
        if os.name == 'nt':
            try:
                foreground_is_self = int(ctypes.windll.user32.GetForegroundWindow()) == int(self.winId())
            except Exception:
                foreground_is_self = False
        return bool(
            os.name == 'nt'
            and self._is_pdf_document_open()
            and self.isVisible()
            and not self.isMinimized()
            and not self.isActiveWindow()
            and not foreground_is_self
            and not getattr(self, 'privacy_mode_active', False)
            and not getattr(self, '_post_hibernate_media_gate_active', False)
            and self.settings.get('enable_pdf_edge_triggers', True)
        )

    def _is_windows_left_mouse_down(self):
        if os.name != 'nt':
            return False
        try:
            return bool(ctypes.windll.user32.GetAsyncKeyState(0x01) & 0x8000)
        except Exception:
            return False

    def _update_external_pdf_edge_triggers(self):
        if not self._should_show_external_pdf_edge_triggers():
            self._hide_external_pdf_edge_triggers()
            self._external_pdf_edge_left_mouse_down = False
            self._external_pdf_edge_altgr_down = False
            return

        if os.name == 'nt':
            try:
                # 0xA5 is VK_RMENU (Right Alt / AltGr)
                altgr_down = bool(ctypes.windll.user32.GetAsyncKeyState(0xA5) & 0x8000)
                if altgr_down and not getattr(self, '_external_pdf_edge_altgr_down', False):
                    self._external_pdf_edge_altgr_down = True
                    self.switch_to_pdf_from_edge_trigger()
                    return
                self._external_pdf_edge_altgr_down = altgr_down
            except Exception:
                pass

        rect = self._pdf_edge_trigger_screen_geometry()
        if rect.isNull():
            self._hide_external_pdf_edge_triggers()
            self._external_pdf_edge_left_mouse_down = False
            return
        cursor_pos = QCursor.pos()
        left_trigger = getattr(self, 'pdf_external_trigger_left', None)
        right_trigger = getattr(self, 'pdf_external_trigger_right', None)
        edge_width = 16

        left_edge_rect = QRect(rect.left(), rect.top(), edge_width, rect.height())
        right_edge_rect = QRect(rect.right() - edge_width + 1, rect.top(), edge_width, rect.height())

        for trigger in (left_trigger, right_trigger):
            if trigger is not None:
                trigger.set_screen_geometry(rect)

        left_active = bool(
            left_trigger is not None and (
                left_edge_rect.contains(cursor_pos)
                or left_trigger.contains_global_pos(cursor_pos)
            )
        )
        right_active = bool(
            right_trigger is not None and (
                right_edge_rect.contains(cursor_pos)
                or right_trigger.contains_global_pos(cursor_pos)
            )
        )

        if left_trigger is not None:
            if left_active:
                left_trigger.show_trigger()
            else:
                left_trigger.collapse()
        if right_trigger is not None:
            if right_active:
                right_trigger.show_trigger()
            else:
                right_trigger.collapse()

        left_mouse_down = self._is_windows_left_mouse_down()
        if left_mouse_down and not getattr(self, '_external_pdf_edge_left_mouse_down', False):
            if left_active or right_active:
                self._external_pdf_edge_left_mouse_down = True
                self.switch_to_pdf_from_edge_trigger()
                return
        self._external_pdf_edge_left_mouse_down = left_mouse_down

    def switch_to_pdf_from_edge_trigger(self):
        self._hide_external_pdf_edge_triggers()
        if not self._is_pdf_document_open():
            return False
        self._pdf_edge_peek_mode = True
        if os.name == 'nt':
            try:
                foreground_hwnd = int(ctypes.windll.user32.GetForegroundWindow())
                self_hwnd = int(self.winId())
                if foreground_hwnd and foreground_hwnd != self_hwnd:
                    self._pdf_edge_return_hwnd = foreground_hwnd
            except Exception:
                self._pdf_edge_return_hwnd = None
        try:
            if self.isMinimized():
                self.showNormal()
            else:
                self.show()
        except Exception:
            pass
        if self._is_app_fullscreen():
            self._restore_fullscreen_input_stack(activate=True)
        else:
            try:
                self.raise_()
            except Exception:
                pass
            try:
                self.activateWindow()
            except Exception:
                pass
            try:
                self.setFocus(Qt.FocusReason.ActiveWindowFocusReason)
            except Exception:
                pass
        QTimer.singleShot(80, self._update_external_pdf_edge_triggers)
        return True

    def _pixmap_from_bytes(self, data):
        pixmap = QPixmap()
        if pixmap.loadFromData(data):
            return pixmap
        try:
            qimg = BatchImageLoader([])._decode_data(data)
            if not qimg.isNull():
                return QPixmap.fromImage(qimg)
        except Exception:
            pass
        return QPixmap()

    def _scale_preview_pixmap(self, pixmap):
        if pixmap.isNull():
            return pixmap
        return pixmap.scaled(220, 160, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation)

    def _extract_video_preview_frame(self, path, timestamp_seconds):
        pixmap = QPixmap()
        try:
            startupinfo = None
            if os.name == 'nt':
                startupinfo = subprocess.STARTUPINFO()
                startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
            result = subprocess.run(
                ['ffmpeg', '-hide_banner', '-loglevel', 'error',
                 '-ss', f"{max(0.0, float(timestamp_seconds)):.3f}",
                 '-i', path,
                 '-frames:v', '1',
                 '-vf', 'scale=240:-1:force_original_aspect_ratio=decrease',
                 '-f', 'image2pipe', '-vcodec', 'png', '-'],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                timeout=8,
                startupinfo=startupinfo
            )
            if result.stdout:
                pixmap.loadFromData(result.stdout)
        except Exception:
            pixmap = QPixmap()
        return self._scale_preview_pixmap(pixmap)

    def _extract_video_preview_frame_bytes(self, path, timestamp_seconds):
        try:
            startupinfo = None
            if os.name == 'nt':
                startupinfo = subprocess.STARTUPINFO()
                startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
            result = subprocess.run(
                ['ffmpeg', '-hide_banner', '-loglevel', 'error',
                 '-ss', f"{max(0.0, float(timestamp_seconds)):.3f}",
                 '-i', path,
                 '-frames:v', '1',
                 '-vf', 'scale=240:-1:force_original_aspect_ratio=decrease',
                 '-f', 'image2pipe', '-vcodec', 'png', '-'],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                timeout=8,
                startupinfo=startupinfo
            )
            return result.stdout or b""
        except Exception:
            return b""

    def _get_video_preview_timestamps(self, path):
        duration_seconds = self._probe_media_duration_seconds(path, timeout=4)
        if duration_seconds <= 0:
            return [2.0, 10.0, 25.0]

        max_ts = max(0.0, duration_seconds - 0.25)
        timestamps = []
        for ratio in (0.08, 0.32, 0.58, 0.84):
            ts = min(max(0.35, duration_seconds * ratio), max_ts)
            if not timestamps or abs(ts - timestamps[-1]) >= 0.35:
                timestamps.append(ts)
        return timestamps or [min(2.0, max_ts)]

    def _load_video_preview_frame_payloads(self, path):
        payloads = []
        seen_hashes = set()
        timestamps = self._get_video_preview_timestamps(path)
        
        import concurrent.futures
        # Limit max_workers to 2 to avoid overwhelming phone FTP servers with concurrent connections
        with concurrent.futures.ThreadPoolExecutor(max_workers=min(2, len(timestamps) or 1)) as executor:
            # Keep the original order of timestamps
            futures = [executor.submit(self._extract_video_preview_frame_bytes, path, ts) for ts in timestamps]
            results = [f.result() for f in futures]
            
        for payload in results:
            if not payload:
                continue
            payload_hash = hash(payload)
            if payload_hash in seen_hashes:
                continue
            seen_hashes.add(payload_hash)
            payloads.append(payload)
        return payloads

    def _start_async_video_hover_preview(self, path):
        if not path:
            return
        norm_path = self._normalize_playlist_path(path)
        if norm_path in self._hover_preview_loading_paths:
            return
        self._hover_preview_loading_paths.add(norm_path)

        # For FTP/phone files, get the HTTP proxy URL that ffmpeg can read
        is_ftp_or_phone = self._is_ftp_url(path) or str(path).startswith('phone://')
        ffmpeg_path = path
        if is_ftp_or_phone:
            proxy_url = self._ftp_preview_http_url(path)
            if proxy_url:
                ffmpeg_path = proxy_url

        def _worker():
            payloads = self._load_video_preview_frame_payloads(ffmpeg_path)
            self.hover_preview_video_frames_ready.emit(path, payloads)

        self.thread_pool.submit(_worker)


    @pyqtSlot(str, object)
    def _on_hover_preview_video_frames_ready(self, path, payloads):
        norm_path = self._normalize_playlist_path(path)
        self._hover_preview_loading_paths.discard(norm_path)
        frames = []
        for payload in payloads or []:
            pixmap = self._pixmap_from_bytes(payload)
            if not pixmap.isNull():
                frames.append(self._scale_preview_pixmap(pixmap))
        self._hover_preview_cache[norm_path] = frames

        if getattr(self, '_hover_preview_path', None) != path or not self.hover_preview.isVisible():
            return

        self._hover_preview_frames = frames
        self._hover_preview_frame_index = 0
        self._update_hover_preview_frame()
        if len(frames) > 1:
            self._hover_preview_anim_timer.start()
        else:
            self._hover_preview_anim_timer.stop()
        self._refresh_hover_preview_layout()
        self._reposition_hover_preview()

    def _ftp_preview_http_url(self, path):
        """Return an HTTP proxy URL for an ftp:// or phone:// path, so ffmpeg can thumbnail it."""
        try:
            ftp_url = path
            if str(path).startswith('phone://'):
                # Convert phone://... to ftp://user:pass@ip:port/...
                ip, port, user, pw = self._ftp_creds_from_url_or_server(None)
                if not ip:
                    return None
                remote = path[8:]  # strip phone://
                from urllib.parse import quote
                ftp_url = f"ftp://{user}:{pw}@{ip}:{port}/{remote.lstrip('/')}"
            if not self._is_ftp_url(ftp_url):
                return None
            return self._ftp_playback_proxy_url(ftp_url)
        except Exception:
            return None

    def _load_preview_frames_for_path(self, path):
        if not path:
            return []

        norm_path = self._normalize_playlist_path(path)
        cached = self._hover_preview_cache.get(norm_path, None)
        if cached is not None:
            return cached

        frames = []
        lower = path.lower()
        try:
            if os.path.isfile(path) and lower.endswith(IMAGE_EXTENSIONS):
                pixmap = QPixmap(path)
                if pixmap.isNull():
                    decoded = BatchImageLoader._decode_path(path)
                    if decoded:
                        w, h, stride, fmt, raw = decoded
                        img_fmt = QImage.Format.Format_ARGB32 if fmt == 'ARGB32' else QImage.Format.Format_RGB32
                        pixmap = QPixmap.fromImage(QImage(raw, w, h, stride, img_fmt).copy())
                if not pixmap.isNull():
                    frames = [self._scale_preview_pixmap(pixmap)]
            elif os.path.isfile(path) and lower.endswith('.cbz'):
                with zipfile.ZipFile(path, 'r') as zf:
                    names = [n for n in zf.namelist() if n.lower().endswith(IMAGE_EXTENSIONS)]
                    names.sort(key=natural_sort_key)
                    if names:
                        pixmap = self._pixmap_from_bytes(zf.read(names[0]))
                        if not pixmap.isNull():
                            frames = [self._scale_preview_pixmap(pixmap)]
            elif os.path.isdir(path):
                images = [os.path.join(path, f) for f in os.listdir(path) if f.lower().endswith(IMAGE_EXTENSIONS)]
                images.sort(key=natural_sort_key)
                if images:
                    frames = self._load_preview_frames_for_path(images[0])
        except Exception:
            frames = []

        self._hover_preview_cache[norm_path] = frames
        return frames

    def _update_hover_preview_frame(self):
        if not getattr(self, '_hover_preview_frames', None):
            self.hover_preview_image.clear()
            self.hover_preview_image.setVisible(False)
            return
        pixmap = self._hover_preview_frames[self._hover_preview_frame_index % len(self._hover_preview_frames)]
        self.hover_preview_image.setVisible(not pixmap.isNull())
        if not pixmap.isNull():
            self.hover_preview_image.setPixmap(pixmap)
        else:
            self.hover_preview_image.clear()

    def _wrap_hover_preview_text(self, text, max_width):
        text = str(text or "").strip()
        if not text or max_width <= 0:
            return text

        import textwrap

        metrics = self.hover_preview_text.fontMetrics()
        avg_char_width = max(6, metrics.averageCharWidth())
        wrap_chars = max(12, int(max_width / avg_char_width))

        wrapped_lines = []
        for paragraph in text.splitlines() or [""]:
            paragraph = paragraph.strip()
            if not paragraph:
                wrapped_lines.append("")
                continue
            lines = textwrap.wrap(
                paragraph,
                width=wrap_chars,
                break_long_words=True,
                break_on_hyphens=True,
                replace_whitespace=False,
                drop_whitespace=False,
            )
            if not lines:
                wrapped_lines.append(paragraph)
                continue
            wrapped_lines.extend(line.rstrip() for line in lines)
        return "\n".join(wrapped_lines)

    def _refresh_hover_preview_layout(self):
        if not hasattr(self, 'hover_preview'):
            return

        margins = self.hover_preview_layout.contentsMargins()
        max_content_width = max(140, min(220, self.width() - 80))
        pixmap = self.hover_preview_image.pixmap()
        image_width = 0
        if pixmap is not None and not pixmap.isNull():
            image_width = pixmap.width()
        content_width = max(140, min(max_content_width, image_width or max_content_width))

        self.hover_preview_image.setMinimumWidth(content_width)
        self.hover_preview_image.setMaximumWidth(content_width)
        self.hover_preview_text.setMinimumWidth(content_width)
        self.hover_preview_text.setMaximumWidth(content_width)
        wrapped_text = self._wrap_hover_preview_text(
            getattr(self, '_hover_preview_display_text', ""),
            content_width,
        )
        self.hover_preview_text.setText(wrapped_text)

        frame_width = content_width + margins.left() + margins.right()
        self.hover_preview.setMinimumWidth(frame_width)
        self.hover_preview.setMaximumWidth(frame_width)
        self.hover_preview.adjustSize()

    def _advance_hover_preview_frame(self):
        if not self.hover_preview.isVisible() or len(getattr(self, '_hover_preview_frames', [])) <= 1:
            self._hover_preview_anim_timer.stop()
            return
        self._hover_preview_frame_index = (self._hover_preview_frame_index + 1) % len(self._hover_preview_frames)
        self._update_hover_preview_frame()
        self._refresh_hover_preview_layout()
        self._reposition_hover_preview()

    def _show_hover_preview(self, path, text, global_pos, target_global_rect=None):
        if not hasattr(self, 'hover_preview'):
            return
        display_text = text or os.path.basename(str(path).rstrip('/\\'))
        _path_lower = path.lower()
        is_ftp_or_phone = self._is_ftp_url(path) or str(path).startswith('phone://')
        is_video = (is_ftp_or_phone and _path_lower.endswith(VIDEO_EXTENSIONS)) or (
            os.path.isfile(path) and _path_lower.endswith(VIDEO_EXTENSIONS))
        norm_path = self._normalize_playlist_path(path)
        frames = self._hover_preview_cache.get(norm_path)
        if frames is None or not is_video:
            frames = self._load_preview_frames_for_path(path)
        self._hover_preview_display_text = display_text
        self._hover_preview_frames = frames
        self._hover_preview_frame_index = 0
        self._update_hover_preview_frame()
        if len(frames) > 1:
            self._hover_preview_anim_timer.start()
        else:
            self._hover_preview_anim_timer.stop()
        if is_video and not frames:
            self._hover_preview_display_text = f"{display_text}\nLoading preview..."
            self._start_async_video_hover_preview(path)
        self._refresh_hover_preview_layout()
        self._hover_preview_anchor_global_pos = global_pos
        self._hover_preview_target_global_rect = target_global_rect or QRect()
        self._move_preview_widget(global_pos)
        self.hover_preview.show()
        self.hover_preview.raise_()
        self._hover_preview_path = path

    def _show_pending_hover_preview(self):
        if not self._hover_preview_pending:
            return
        path, text, global_pos, target_global_rect = self._hover_preview_pending
        if target_global_rect is not None and not target_global_rect.isNull() and not target_global_rect.contains(QCursor.pos()):
            self._hide_hover_preview()
            return
        current_target = self._hover_preview_target_at_global_pos(QCursor.pos())
        if not self._preview_paths_match(current_target, path):
            self._hide_hover_preview()
            return
        self._show_hover_preview(path, text, global_pos, target_global_rect=target_global_rect)

    def _schedule_hover_preview(self, path, text, global_pos, target_global_rect=None):
        if not path:
            self._hide_hover_preview()
            return
        if self.hover_preview.isVisible() and not self._preview_paths_match(self._hover_preview_path, path):
            self._hover_preview_anim_timer.stop()
            self.hover_preview.hide()
            self._hover_preview_path = None
            self._hover_preview_frames = []
            self._hover_preview_frame_index = 0
        self._hover_preview_pending = (path, text, global_pos, target_global_rect or QRect())
        self._hover_preview_anchor_global_pos = global_pos
        self._hover_preview_target_global_rect = target_global_rect or QRect()
        if self.hover_preview.isVisible() and self._hover_preview_path == path:
            self._move_preview_widget(global_pos)
            return
        self._hover_preview_timer.start(1000)

    def update_hibernate_ui(self):
        """Update the hibernate+zoom overlay label in the top-right corner."""
        if not hasattr(self, 'hb_overlay'):
            return
        if not self.hb_overlay.isVisible() and not getattr(self, '_hb_show_zoom', False):
            return

        import time as _time
        elapsed = self.last_activity_time.elapsed() if hasattr(self, 'last_activity_time') else 0

        # ── Determine which mode is active and compute timer text ──────────────────
        late_night_enabled = getattr(self, 'late_night_hibernate_enabled', True)
        is_late_window = late_night_enabled and self._is_late_night_hibernate_window()

        if is_late_window:
            # Late-night mode is active — show its own countdown
            late_night_idle_ms = self._effective_late_night_idle_timeout_ms()
            started_at = getattr(self, '_late_night_window_started_at_ms', None)
            if started_at:
                late_elapsed = max(0, int(_time.monotonic() * 1000) - int(started_at))
            else:
                late_elapsed = elapsed
            remaining_ms = max(0, late_night_idle_ms - late_elapsed)
            remaining_sec = remaining_ms // 1000
            mins = remaining_sec // 60
            secs = remaining_sec % 60
            # Use red circle when pending hibernate, green otherwise
            if getattr(self, '_late_night_scheduled', False) or remaining_ms == 0:
                timer_text = f"🌙🔴 {mins:02d}:{secs:02d}"
            else:
                timer_text = f"🌙🟢 {mins:02d}:{secs:02d}"
        elif not getattr(self, 'auto_hibernate_enabled', True):
            timer_text = "🔴 Off"
        else:
            remaining_ms = max(0, self.inactivity_timeout - elapsed)
            if elapsed > self.inactivity_timeout + (10 * 60 * 1000):
                remaining_ms = self.inactivity_timeout
            remaining_sec = remaining_ms // 1000
            mins = remaining_sec // 60
            secs = remaining_sec % 60
            timer_text = f"🟢 {mins:02d}:{secs:02d}"

        # Build full overlay text
        if getattr(self, '_hb_show_zoom', False):
            zoom_text = self._get_current_zoom_text()
            text = f"{zoom_text}  |  {timer_text}"
        else:
            text = timer_text

        if text == getattr(self, '_last_hibernate_overlay_text', None):
            return
        self._last_hibernate_overlay_text = text

        self.hb_overlay.setText(text)
        self.hb_overlay.adjustSize()
        self._reposition_hb_overlay()

    def _tick_remote_loading_indicator(self):
        frames = getattr(self, '_remote_loading_frames', ("o", "O"))
        if not frames or not hasattr(self, 'remote_loading_label'):
            return
        self._remote_loading_frame = (int(getattr(self, '_remote_loading_frame', 0) or 0) + 1) % len(frames)
        self.remote_loading_label.setText(frames[self._remote_loading_frame])
        self.remote_loading_label.adjustSize()
        self._reposition_hb_overlay()

    def _update_remote_loading_indicator(self):
        label = getattr(self, 'remote_loading_label', None)
        timer = getattr(self, 'remote_loading_timer', None)
        if label is None or timer is None:
            return
        active = int(getattr(self, '_remote_analysis_count', 0) or 0) > 0
        unseen = int(getattr(self, '_link_flow_unseen', 0) or 0)
        has_rows = bool(getattr(self, '_link_flow_rows', None))
        # The indicator sits on the menu bar, which is hidden in fullscreen —
        # keep it hidden there (exiting fullscreen refreshes it).
        in_fullscreen = self._is_app_fullscreen()
        if active:
            frames = getattr(self, '_remote_loading_frames', ("o", "O"))
            label.setText(frames[int(getattr(self, '_remote_loading_frame', 0) or 0) % len(frames)])
            label.setToolTip(f"Analyzing links ({int(getattr(self, '_remote_analysis_count', 0) or 0)} active) — click to show captured links")
            if in_fullscreen:
                label.hide()
            else:
                label.show()
            if not timer.isActive():
                timer.start()
        elif has_rows:
            # Idle but links were captured: stay clickable as the popup
            # toggle, with a badge of unseen links (R43).
            timer.stop()
            label.setText(f'≡{unseen}' if unseen else '≡')
            label.adjustSize()
            label.setToolTip(
                f'{unseen} new captured link(s) — click to show the list'
                if unseen else 'Captured links — click to show the list')
            if in_fullscreen:
                label.hide()
            else:
                label.show()
        else:
            timer.stop()
            label.hide()
        self._reposition_hb_overlay()

    @pyqtSlot(int)
    def _apply_remote_analysis_delta(self, delta):
        self._remote_analysis_count = max(
            0,
            int(getattr(self, '_remote_analysis_count', 0) or 0) + int(delta or 0),
        )
        self._update_remote_loading_indicator()

    def _remote_analysis_begin(self, count=1):
        delta = max(1, int(count or 1))
        app = QApplication.instance()
        if app is not None and QThread.currentThread() != app.thread():
            self.remote_analysis_delta_requested.emit(delta)
            return
        self._apply_remote_analysis_delta(delta)

    def _remote_analysis_end(self, count=1):
        delta = -max(1, int(count or 1))
        app = QApplication.instance()
        if app is not None and QThread.currentThread() != app.thread():
            self.remote_analysis_delta_requested.emit(delta)
            return
        self._apply_remote_analysis_delta(delta)


    def load_recent_files(self):
        if os.path.exists(self.recent_files_file):
            try:
                with open(self.recent_files_file, 'r') as f:
                    return json.load(f)
            except:
                return []
        return []
    
    def save_recent_files(self):
        with open(self.recent_files_file, 'w') as f:
            json.dump(self.recent_files, f)

    def _recent_file_name_key(self, file_path):
        value = str(file_path or '').strip()
        try:
            if self._is_remote_url(value):
                value = self._canonicalize_remote_source_url(value)
        except Exception:
            pass
        return _meta_norm_path(value)

    # Title strings that must never be stored or displayed — they are page-level
    # anti-bot challenge titles, not real media names.
    _BANNED_STREAM_TITLES = frozenset({
        'adblocker detected',
        'attention required',
        'just a moment',
        'access denied',
        'ddos protection',
        'please wait',
        'one moment, please',
        'checking your browser',
        'security check',
        'bot check',
        'human verification',
    })

    @classmethod
    def _is_banned_stream_title(cls, title):
        """Return True if *title* is a known anti-bot / challenge page title."""
        t = str(title or '').strip().lower()
        if not t:
            return False
        return t in cls._BANNED_STREAM_TITLES or any(b in t for b in cls._BANNED_STREAM_TITLES)

    def load_recent_file_names(self):
        try:
            if os.path.exists(self.recent_file_names_file):
                with open(self.recent_file_names_file, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                if isinstance(data, dict):
                    return {
                        str(k): str(v)
                        for k, v in data.items()
                        if str(k or '').strip() and str(v or '').strip()
                        and not self._is_banned_stream_title(v)
                    }
        except Exception:
            pass
        return {}

    def save_recent_file_names(self):
        try:
            with open(self.recent_file_names_file, 'w', encoding='utf-8') as f:
                json.dump(getattr(self, 'recent_file_names', {}), f, ensure_ascii=False, indent=2)
        except Exception as e:
            print(f"Error saving recent file names: {e}")

    # ── Series / sequel linking ─────────────────────────────────────────────
    # Groups are keyed by an opaque id so auto-detected and manually-linked
    # groups share one storage format. _series_groups maps group_id -> an
    # ordered list of _meta_norm_path keys (list order == series order).
    # _series_link_map is the reverse index (norm key -> group_id), used for
    # fast per-row lookups during sort and row rendering. Matching always
    # runs on _playlist_display_name() — the same name the playlist already
    # shows, whether it came from the filename, a URL-derived title, an F2
    # rename, or a metadata override — never the raw path.

    def load_series_links(self):
        """Load persisted series/sequel groups. Returns (link_map, groups)."""
        try:
            if os.path.exists(self.series_links_file):
                with open(self.series_links_file, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                if isinstance(data, dict):
                    groups = {
                        str(gid): [str(k) for k in members if str(k or '').strip()]
                        for gid, members in (data.get('groups') or {}).items()
                        if isinstance(members, list) and len(members) >= 2
                    }
                    link_map = {}
                    for gid, members in groups.items():
                        for key in members:
                            link_map[key] = gid
                    return link_map, groups
        except Exception as e:
            print(f"Error loading series links: {e}")
        return {}, {}

    def save_series_links(self):
        try:
            with open(self.series_links_file, 'w', encoding='utf-8') as f:
                json.dump({'groups': getattr(self, '_series_groups', {})}, f, ensure_ascii=False, indent=2)
        except Exception as e:
            print(f"Error saving series links: {e}")

    _SERIES_MARKER_WORDS = r'(?:part|pt|vol(?:ume)?|episode|ep|chapter|ch|disc|disk|cd)'
    _SERIES_MARKER_TOKENS = {'part', 'pt', 'vol', 'volume', 'episode', 'ep', 'chapter', 'ch', 'disc', 'disk', 'cd'}
    _SERIES_GLUEABLE_MARKER_WORDS = r'(?:part|pt|vol(?:ume)?|episode|ep|chapter|disc|disk|cd)'
    _SERIES_PART_PLACEHOLDER = '__series_part__'

    def _series_signature_from_tokens(self, tokens, *, require_context=False):
        """Collapse token lists into a stable comparison key.
        For bare-number matches we require a bit more surrounding text so
        catalog codes like 'ABP 123' do not get mistaken for sequels."""
        cleaned = []
        for t in (tokens or []):
            if not t or t == self._SERIES_PART_PLACEHOLDER:
                continue
            # Ignore short mixed release tags like 'h1x' / 'v1x' when
            # building the series signature.
            if re.fullmatch(r'[a-z]\d[a-z0-9]{0,2}', t):
                continue
            cleaned.append(t)
        if not cleaned:
            return ""
        alphaish = [t for t in cleaned if re.search(r'[a-z]', t)]
        if not alphaish:
            return ""
        if require_context and len(alphaish) < 2:
            return ""
        return " ".join(cleaned).strip(" -_.")

    def _series_signature_and_part(self, display_name):
        """Return (series_signature, part_number) when a sequel marker is
        found anywhere in the effective playlist title.
        Handles:
        - raw browser duplicate suffixes like 'Title (2)'
        - explicit markers like 'Part 2' / 'Episode III'
        - bare numeric tokens surrounded by stable title tokens, such as
          'azeez-zezer-ez-1-720p-rert' vs '...-2-720p-rert'
        """
        raw_stem = os.path.splitext(str(display_name or ''))[0].strip()
        if not raw_stem:
            return "", None

        # Handle bracketed markers anywhere in the raw title, e.g.
        # 'Name - (PART 2) Subtitle'.
        bracket_marker = re.search(
            r'^(.*?)(?:\s*[\(\[]\s*(' + self._SERIES_MARKER_WORDS + r')\.?\s*(\d{1,3}|[ivxlcdm]+)\s*[\)\]])\s*(.*)$',
            raw_stem,
            flags=re.IGNORECASE,
        )
        if bracket_marker:
            marker_num = bracket_marker.group(3)
            if re.fullmatch(r'\d{1,3}', marker_num, flags=re.IGNORECASE):
                part = int(marker_num)
            else:
                part = self._roman_to_int(marker_num)
            if part is not None:
                signature_source = " ".join(x for x in [bracket_marker.group(1), bracket_marker.group(4)] if x).strip()
                signature = self._sanitize_subtitle_search_title(signature_source).lower().strip(" -_.")
                if signature:
                    return signature, part

        # The subtitle-search sanitizer removes bracketed content entirely,
        # so browser-style duplicate suffixes must be captured first.
        bracket_match = re.search(r'^(.*?)(?:\s*[\(\[]\s*(\d{1,3})\s*[\)\]])\s*$', raw_stem)
        if bracket_match:
            try:
                part = int(bracket_match.group(2))
            except (TypeError, ValueError):
                part = None
            if part is not None:
                signature = self._sanitize_subtitle_search_title(bracket_match.group(1)).lower().strip(" -_.")
                if signature:
                    return signature, part

        sanitized = self._sanitize_subtitle_search_title(display_name).lower().strip()
        if not sanitized:
            return "", None

        # Split glued marker tokens like "pt2" / "episode10" before tokenizing.
        sanitized = re.sub(
            r'\b(' + self._SERIES_GLUEABLE_MARKER_WORDS[3:-1] + r')(\d{1,3}|[ivxlcdm]+)\b',
            r'\1 \2',
            sanitized,
            flags=re.IGNORECASE,
        )
        tokens = [t for t in re.split(r'\s+', sanitized) if t]
        if len(tokens) < 2:
            return "", None

        # Strongest signal: explicit sequel marker + number / roman numeral.
        for i in range(len(tokens) - 1):
            marker = tokens[i].rstrip('.')
            if marker not in self._SERIES_MARKER_TOKENS:
                continue
            nxt = tokens[i + 1].rstrip('.')
            part = None
            if re.fullmatch(r'\d{1,3}', nxt):
                part = int(nxt)
            elif re.fullmatch(r'[ivxlcdm]+', nxt):
                part = self._roman_to_int(nxt)
            if part is None:
                continue
            signature = self._series_signature_from_tokens(tokens[:i] + tokens[i + 2:])
            if signature:
                return signature, part

        # Fallback: a bare number token anywhere in the cleaned title, as
        # long as enough stable text remains around it.
        number_tokens = [t.rstrip('.') for t in tokens if re.fullmatch(r'\d{1,3}', t.rstrip('.'))]
        for i, token in enumerate(tokens):
            candidate = token.rstrip('.')
            if not re.fullmatch(r'\d{1,3}', candidate):
                continue
            # Avoid misreading leftover day/month fragments or other multi-
            # number titles as sequel indices.
            if len(number_tokens) != 1:
                continue
            signature = self._series_signature_from_tokens(
                tokens[:i] + tokens[i + 1:],
                require_context=True,
            )
            if signature:
                return signature, int(candidate)

        return "", None

    def _series_part_number(self, display_name):
        """Extract the detected sequel/part number from a display name."""
        _, part = self._series_signature_and_part(display_name)
        return part

    def _roman_to_int(self, s):
        vals = {'i': 1, 'v': 5, 'x': 10, 'l': 50, 'c': 100, 'd': 500, 'm': 1000}
        s = s.lower()
        total, prev = 0, 0
        for ch in reversed(s):
            v = vals.get(ch, 0)
            total += -v if v < prev else v
            prev = max(prev, v)
        return total or None

    def _series_base_title(self, display_name):
        """Normalize a display name down to its series-comparison key."""
        signature, _ = self._series_signature_and_part(display_name)
        if signature:
            return signature
        t = self._sanitize_subtitle_search_title(display_name).lower()
        t = re.sub(r'\s+' + self._SERIES_MARKER_WORDS + r'\.?\s*\d{1,3}\s*$', '', t, flags=re.IGNORECASE)
        t = re.sub(r'\s+(?:part|pt)\.?\s*[ivxlcdm]+\s*$', '', t, flags=re.IGNORECASE)
        t = re.sub(r'\s+-\s*\d{1,3}\s*$', '', t)
        t = re.sub(r'\s+\d{1,3}\s*$', '', t)
        t = re.sub(r'\s+', ' ', t).strip(' -_.')
        return t

    def _series_group_id_for(self, file_path):
        key = _meta_norm_path(file_path)
        return getattr(self, '_series_link_map', {}).get(key)

    def _series_group_members_present(self, group_id, ordered_paths):
        """This group's members, in stored series order, limited to whichever
        of *ordered_paths* are currently present (respects the active seen/
        unmarked filter and silently drops entries that no longer exist)."""
        members = getattr(self, '_series_groups', {}).get(group_id, [])
        by_norm = {_meta_norm_path(p): p for p in ordered_paths}
        return [by_norm[k] for k in members if k in by_norm]

    def _apply_series_grouping(self, ordered_paths):
        """Given a list of paths already sorted by whichever column is
        active, pull linked series/sequel entries together so they sit
        contiguously — anchored at whichever member sorted earliest under
        the active column — and ordered internally by stored series
        position rather than by that column. Works the same for every
        column since it's a pass over the already-sorted result, not a
        per-column special case."""
        if not getattr(self, '_series_groups', None):
            return ordered_paths
        result = []
        placed = set()
        for fp in ordered_paths:
            gid = self._series_group_id_for(fp)
            if gid is None:
                result.append(fp)
                continue
            if gid in placed:
                continue
            placed.add(gid)
            result.extend(self._series_group_members_present(gid, ordered_paths))
        return result

    def _refresh_series_group_rows(self, file_paths):
        """Re-render whichever rows currently show any of *file_paths*
        (name text + grouping indicator) without a full table rebuild."""
        for fp in file_paths:
            for row in self._find_playlist_rows(fp):
                self.update_row_appearance(row)

    def _resort_or_regroup_playlist(self):
        """Re-apply the current sort — which re-runs series grouping as part
        of it — or just regroup in place if no column has been sorted yet
        this session."""
        if getattr(self, '_sort_last_col', None) is not None:
            col = self._sort_last_col
            want_asc = self._sort_ascending
            # sort_playlist() toggles direction when the clicked column is
            # unchanged; pre-flip so its toggle lands back on what we want.
            self._sort_ascending = not want_asc
            self.sort_playlist(col)
        else:
            visible_paths = []
            hidden_paths = []
            for row, fp in enumerate(self.playlist):
                if self._playlist_row_matches_filters(row):
                    visible_paths.append(fp)
                else:
                    hidden_paths.append(fp)
            self._apply_sorted_playlist(self._apply_series_grouping(visible_paths), hidden_paths)

    def link_selected_playlist_entries(self, rows):
        """Manually link the given playlist rows into one series, ordered by
        their current top-to-bottom position. Absorbs any group(s) they
        already belonged to, so linking a new part onto an existing series
        just extends it."""
        rows = sorted(set(rows or []))
        paths = [self.playlist[r] for r in rows if 0 <= r < len(self.playlist)]
        if len(paths) < 2:
            self.show_osd("Select 2+ items to link as a series", duration=2000)
            return False

        groups, link_map = self._series_groups, self._series_link_map
        old_gids = {link_map[_meta_norm_path(p)] for p in paths
                    if _meta_norm_path(p) in link_map and link_map[_meta_norm_path(p)] in groups}

        merged_keys, seen = [], set()
        for gid in old_gids:
            for key in groups.get(gid, []):
                if key not in seen:
                    seen.add(key)
                    merged_keys.append(key)
        for p in paths:
            key = _meta_norm_path(p)
            if key not in seen:
                seen.add(key)
                merged_keys.append(key)

        row_of = {_meta_norm_path(p): i for i, p in enumerate(self.playlist)}
        merged_keys.sort(key=lambda k: row_of.get(k, len(self.playlist)))

        for gid in old_gids:
            groups.pop(gid, None)
        new_gid = uuid.uuid4().hex[:12]
        groups[new_gid] = merged_keys
        for key in merged_keys:
            link_map[key] = new_gid

        self.save_series_links()
        self._refresh_series_group_rows(paths)
        self._resort_or_regroup_playlist()
        self.show_osd(f"Linked {len(merged_keys)} items as a series", duration=2000)
        return True

    def unlink_selected_playlist_entries(self, rows):
        """Remove the given rows from whatever series group they're in. A
        group left with fewer than 2 members is dissolved entirely."""
        rows = sorted(set(rows or []))
        paths = [self.playlist[r] for r in rows if 0 <= r < len(self.playlist)]
        groups, link_map = self._series_groups, self._series_link_map
        touched_gids, removed_any = set(), False

        for p in paths:
            key = _meta_norm_path(p)
            gid = link_map.pop(key, None)
            if gid:
                touched_gids.add(gid)
                removed_any = True
                if gid in groups and key in groups[gid]:
                    groups[gid].remove(key)

        for gid in touched_gids:
            members = groups.get(gid, [])
            if len(members) < 2:
                for key in members:
                    link_map.pop(key, None)
                groups.pop(gid, None)

        if not removed_any:
            self.show_osd("Nothing selected is linked", duration=1800)
            return False

        self.save_series_links()
        self._refresh_series_group_rows(paths)
        self._resort_or_regroup_playlist()
        self.show_osd("Removed from series", duration=1800)
        return True

    def auto_link_series_and_sequels(self):
        """Scan the whole playlist and auto-group entries whose current
        display name shares a series base plus a detected part/sequel
        number. Entries already in a group (manual or from an earlier scan)
        are left untouched, so this never clobbers manual work."""
        buckets = {}
        already_linked = set(getattr(self, '_series_link_map', {}).keys())
        for p in self.playlist:
            key = _meta_norm_path(p)
            if key in already_linked:
                continue
            name = self._playlist_display_name(p)
            base, part = self._series_signature_and_part(name)
            if part is None or not base:
                continue
            if len(base) <= 3:
                continue
            buckets.setdefault(base, []).append((part, key, p))

        new_groups, touched_paths = 0, []
        for members in buckets.values():
            if len(members) < 2:
                continue
            if len({part for part, _, _ in members}) < 2:
                continue
            playlist_pos = {_meta_norm_path(p): i for i, p in enumerate(self.playlist)}
            members.sort(key=lambda m: (m[0], playlist_pos.get(m[1], len(self.playlist))))
            gid = uuid.uuid4().hex[:12]
            self._series_groups[gid] = [k for _, k, _ in members]
            for _, k, _ in members:
                self._series_link_map[k] = gid
            touched_paths.extend(p for _, _, p in members)
            new_groups += 1

        if new_groups == 0:
            self.show_osd("No new series/sequels detected", duration=2000)
            return 0

        self.save_series_links()
        self._refresh_series_group_rows(touched_paths)
        self._resort_or_regroup_playlist()
        self.show_osd(f"Auto-linked {new_groups} series ({len(touched_paths)} items)", duration=2400)
        return new_groups
    # ─────────────────────────────────────────────────────────────────────

    def _seen_url_key(self, url):
        value = str(url or '').strip()
        if self._is_remote_folder_entry(value):
            value = self._remote_folder_url(value)
        if not value:
            return ''
        return self._url_date_key(value)

    def load_seen_urls(self):
        try:
            if os.path.exists(self.seen_urls_file):
                with open(self.seen_urls_file, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                if isinstance(data, dict):
                    raw_values = data.get('keys') or data.get('urls') or []
                else:
                    raw_values = data
                keys = set()
                if isinstance(raw_values, (list, tuple, set)):
                    for value in raw_values:
                        key = str(value or '').strip()
                        if not key:
                            continue
                        if self._is_remote_url(key) or self._is_remote_folder_entry(key):
                            key = self._seen_url_key(key)
                        keys.add(key)
                return keys
        except Exception as e:
            print(f"Error loading seen URLs: {e}")
        return set()

    def save_seen_urls(self):
        try:
            keys = sorted(str(key) for key in getattr(self, 'seen_url_keys', set()) if str(key or '').strip())
            with open(self.seen_urls_file, 'w', encoding='utf-8') as f:
                json.dump({'keys': keys}, f, ensure_ascii=False, indent=2)
        except Exception as e:
            print(f"Error saving seen URLs: {e}")

    _JAV_CODE_PREFIX_BLACKLIST = frozenset({
        'AAC', 'AVC', 'BD', 'BLURAY', 'CODEC', 'DL', 'DVD', 'EAC3', 'FHD',
        'FILE', 'GROUP', 'H264', 'H265', 'HD', 'HEVC', 'HTTP', 'HTTPS',
        'ID', 'ITEM', 'LIST', 'ML', 'MP3', 'MP4', 'NET', 'ORG', 'SD', 'TV',
        'UHD', 'URL', 'VIEWKEY', 'WATCH', 'WEB', 'WEBDL', 'WEBRIP', 'WWW',
        'X264', 'X265',
    })

    def _extract_jav_code(self, text):
        value = unquote(str(text or '')).strip().upper()
        if not value:
            return ""

        # Treat any punctuation/symbol as a separator so codes still match
        # inside wrappers like "(ABC|123)", "{ABC]123}", or similar.
        value = re.sub(r'[^A-Z0-9]+', ' ', value)
        value = re.sub(r'\s+', ' ', value).strip()
        if not value:
            return ""

        fc2_match = re.search(
            r'(?<![A-Z0-9])FC2(?:\s*[-_])?\s*PPV(?:\s*[-_])?\s*(\d{5,8})(?!\d)',
            value,
            re.IGNORECASE,
        )
        if fc2_match:
            return f"FC2-PPV-{fc2_match.group(1)}"

        heyzo_match = re.search(
            r'(?<![A-Z0-9])HEYZO(?:\s*[-_])?\s*(\d{3,5})(?!\d)',
            value,
            re.IGNORECASE,
        )
        if heyzo_match:
            return f"HEYZO-{heyzo_match.group(1)}"

        generic_match = re.search(
            r'(?<![A-Z0-9])([A-Z]{2,6})(?:\s*[-_])?\s*(\d{2,5})(?!\d)',
            value,
            re.IGNORECASE,
        )
        if not generic_match:
            return ""

        prefix = str(generic_match.group(1) or '').upper()
        number = str(generic_match.group(2) or '')
        if prefix in self._JAV_CODE_PREFIX_BLACKLIST:
            return ""
        return f"{prefix}-{number}"

    def _jav_code_candidates_for_path(self, file_path):
        candidates = []
        seen = set()

        def add_candidate(value):
            text = str(value or '').strip()
            if not text:
                return
            for candidate in (text, unquote(text)):
                candidate = str(candidate or '').strip()
                if not candidate or candidate in seen:
                    continue
                seen.add(candidate)
                candidates.append(candidate)
                base = os.path.basename(candidate.rstrip('/\\')).lstrip('-').strip()
                stem = os.path.splitext(base)[0].strip()
                for extra in (base, stem):
                    extra = str(extra or '').strip()
                    if extra and extra not in seen:
                        seen.add(extra)
                        candidates.append(extra)

        source_path = file_path
        if self._is_remote_folder_entry(file_path):
            source_path = self._remote_folder_url(file_path)
            folder_meta = self._remote_folder_meta(file_path) or {}
            add_candidate(self._clean_remote_title(folder_meta.get('title')))

        add_candidate(self._recent_file_saved_name(file_path))

        overrides = getattr(self, '_metadata_name_overrides', {}) or {}
        add_candidate(self._get_name_override(file_path))

        if self._is_remote_url(source_path):
            cached = dict(getattr(self, '_stream_resolution_cache', {}).get(source_path, {}) or {})
            add_candidate(self._clean_remote_title(cached.get('roshy_title')))
            add_candidate(self._clean_remote_title(cached.get('title')))
            try:
                parsed = urlparse(source_path)
                add_candidate(os.path.basename(unquote((parsed.path or '').rstrip('/'))))
            except Exception:
                pass
            add_candidate(self._remote_url_identity_label(source_path))
        else:
            add_candidate(source_path)

        return candidates

    def _jav_seen_key_for_path(self, file_path):
        # FTP URLs contain credentials/IPs like mou@192..., which can look like
        # fake JAV codes (for example MOU-192) and mark every phone FTP row.
        if self._is_ftp_url(file_path):
            return ""
        for candidate in self._jav_code_candidates_for_path(file_path):
            code = self._extract_jav_code(candidate)
            if code:
                return f"jav:{code}"
        return ""

    def _refresh_seen_rows_for_jav_key(self, jav_key):
        jav_key = str(jav_key or '').strip()
        if not jav_key:
            return
        for row, path in enumerate(getattr(self, 'playlist', [])):
            try:
                if self._jav_seen_key_for_path(path) == jav_key:
                    self.update_row_appearance(row)
            except Exception:
                continue

    def _ftp_display_basename(self, file_path):
        if not self._is_ftp_url(file_path):
            return ""
        try:
            return unquote(str(file_path).rstrip('/').split('/')[-1]).strip()
        except Exception:
            return unquote(os.path.basename(str(file_path or '').rstrip('/'))).strip()

    def _ftp_filename_has_seen_prefix(self, file_path):
        return self._ftp_display_basename(file_path).lstrip().startswith('-')

    def _ftp_seen_name_key_for_path(self, file_path):
        if not self._is_ftp_url(file_path):
            return ""
        name = self._ftp_display_basename(file_path)
        key = self._mirror_title_identity_key(name)
        return f"ftp-name:{key}" if key else ""

    def _url_seen_keys_for_single_path(self, file_path):
        keys = set()
        if self._is_ftp_url(file_path):
            key = self._ftp_seen_name_key_for_path(file_path)
            if key:
                keys.add(key)
            return keys
        key = self._seen_url_key(file_path)
        if key:
            keys.add(key)
        if self._is_remote_folder_entry(file_path):
            url = self._remote_folder_url(file_path)
            key = self._seen_url_key(url)
            if key:
                keys.add(key)
        return keys

    def _url_seen_name_key_for_path(self, file_path):
        if self._is_ftp_url(file_path):
            return self._ftp_seen_name_key_for_path(file_path)
        if not (self._is_remote_url(file_path) or self._is_remote_folder_entry(file_path)):
            return ""
        key = self._mirror_display_group_key(file_path)
        return f"name:{key}" if key else ""

    def _url_seen_keys_for_path(self, file_path, include_mirrors=True):
        paths = [file_path]
        if include_mirrors and self._is_remote_url(file_path):
            try:
                paths.extend(self._mirrors_for_visible_url(file_path))
            except Exception:
                pass
        keys = set()
        for path in self._unique_paths(paths):
            keys.update(self._url_seen_keys_for_single_path(path))
            name_key = self._url_seen_name_key_for_path(path)
            if name_key:
                keys.add(name_key)
        for path in self._unique_paths(paths):
            if not self._is_remote_url(path):
                continue
            try:
                parsed = urlparse(path)
                fragment = parse_qs(parsed.fragment or '')
                if fragment.get('file'):
                    parent_url = urlunparse((parsed.scheme, parsed.netloc, parsed.path, '', parsed.query, ''))
                    parent_key = self._seen_url_key(parent_url)
                    keys.discard(parent_key)
            except Exception:
                pass
        return keys

    def _url_seen_display_prefix(self, file_path, display_name):
        keys = self._url_seen_keys_for_path(file_path)
        jav_key = self._jav_seen_key_for_path(file_path)
        if jav_key:
            keys.add(jav_key)
        text = str(display_name or '')
        if not keys:
            return self._strip_seen_display_prefix(text) if text.lstrip().startswith('-') else display_name
        seen_keys = getattr(self, 'seen_url_keys', set()) or set()
        is_marked = bool(keys & seen_keys)
        if text.lstrip().startswith('-'):
            return text if is_marked else self._strip_seen_display_prefix(text)
        return f"- {text}" if is_marked else display_name

    def _refresh_seen_rows_for_url_group(self, file_path):
        paths = [file_path]
        if self._is_remote_url(file_path):
            try:
                paths.extend(self._mirrors_for_visible_url(file_path))
            except Exception:
                pass
        name_keys = {
            self._url_seen_name_key_for_path(path)
            for path in self._unique_paths(paths)
        }
        name_keys.discard("")
        path_keys = {
            self._mirror_path_key(path)
            for path in self._unique_paths(paths)
        }
        path_keys.discard("")
        for row, row_path in enumerate(getattr(self, 'playlist', [])):
            try:
                row_path_key = self._mirror_path_key(row_path)
                row_name_key = self._url_seen_name_key_for_path(row_path)
                if row_path_key in path_keys or (row_name_key and row_name_key in name_keys):
                    self.update_row_appearance(row)
            except Exception:
                continue

    # ------------------------------------------------------------------ #
    #  URL DATE TRACKING                                                   #
    #  Creation date = first time the URL is added to the playlist.       #
    #  Name-modified date = last time the user renamed the entry.         #
    # ------------------------------------------------------------------ #

    def _load_url_dates(self):
        """Load url_dates.json → { normalized_key: { 'added': ISO, 'name_modified': ISO } }"""
        try:
            if os.path.exists(self.url_dates_file):
                with open(self.url_dates_file, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                if isinstance(data, dict):
                    return data
        except Exception:
            pass
        return {}

    def _save_url_dates(self):
        try:
            with open(self.url_dates_file, 'w', encoding='utf-8') as f:
                json.dump(getattr(self, 'url_dates', {}), f, indent=2, ensure_ascii=False)
        except Exception as exc:
            print(f"Error saving url dates: {exc}")

    def _url_date_key(self, url):
        """Normalized dict key for url_dates — same normalisation as _recent_file_name_key."""
        return self._recent_file_name_key(url)

    def _get_url_dates(self, url):
        """Return {'added': ISO, 'name_modified': ISO} (may be partial or empty)."""
        key = self._url_date_key(url)
        if not key:
            return {}
        return dict(getattr(self, 'url_dates', {}).get(key) or {})

    def _set_url_date_added(self, url, dt=None):
        """Stamp the addition date for a remote URL — no-op if already set.

        Being a no-op when the date is already present means that loading a
        playlist (where _apply_loaded_playlist_metadata pre-populates the date)
        will never overwrite the original stamp.
        """
        key = self._url_date_key(url)
        if not key:
            return
        dates = getattr(self, 'url_dates', {})
        if not isinstance(dates, dict):
            self.url_dates = {}
            dates = self.url_dates
        if 'added' in dates.get(key, {}):
            return                              # already recorded — preserve original
        dates.setdefault(key, {})['added'] = (dt or datetime.now()).isoformat(timespec='seconds')
        self._save_url_dates()

    def _set_url_date_name_modified(self, url, dt=None):
        """Stamp the name-modification date for a remote URL entry."""
        key = self._url_date_key(url)
        if not key:
            return
        dates = getattr(self, 'url_dates', {})
        if not isinstance(dates, dict):
            self.url_dates = {}
            dates = self.url_dates
        dates.setdefault(key, {})['name_modified'] = (dt or datetime.now()).isoformat(timespec='seconds')
        self._save_url_dates()

    @staticmethod
    def _format_url_date(iso_str):
        """Convert an ISO timestamp string to a human-readable local-time string."""
        if not iso_str:
            return ''
        try:
            return datetime.fromisoformat(iso_str).strftime('%Y-%m-%d  %H:%M')
        except Exception:
            return iso_str

