    def _remember_recent_file_name(self, file_path, display_name=None, save=True):
        if not hasattr(self, 'recent_file_names') or not isinstance(self.recent_file_names, dict):
            self.recent_file_names = {}
        key = self._recent_file_name_key(file_path)
        if not key:
            return False
        name = str(display_name or '').strip()
        if not name:
            try:
                name = str(self._get_playlist_name_for_path(file_path) or '').strip()
            except Exception:
                name = ''
        if not name or name.lower().startswith(('http://', 'https://')):
            return False
        name = self._strip_seen_display_prefix(name)
        if not name:
            return False
        # Never persist a known anti-bot challenge title.
        if self._is_banned_stream_title(name):
            return False
        try:
            if self._is_remote_url(file_path):
                parsed = urlparse(self._canonicalize_remote_source_url(str(file_path or '')))
                host = (parsed.netloc or '').replace('www.', '').lower()
                base = unquote(os.path.basename((parsed.path or '').rstrip('/'))).strip().lower()
                without_host = re.sub(r"\s+\[[^\]]+\]\s*$", "", name).strip().lower()
                if ('gofile.io' in host or 'gofile.to' in host) and base and without_host == base:
                    return False
                if self._is_fileditch_host(host) and self._is_fileditch_generic_title(name):
                    return False
                if self._is_pornhub_host(host) and self._is_pornhub_generic_title(name):
                    return False
        except Exception:
            pass
        self.recent_file_names[key] = name
        if save:
            self.save_recent_file_names()
        return True

    def _recent_file_saved_name(self, file_path):
        names = getattr(self, 'recent_file_names', {})
        if not isinstance(names, dict):
            return ""
        name = str(names.get(self._recent_file_name_key(file_path)) or '').strip()
        try:
            if self._is_remote_url(file_path):
                parsed = urlparse(self._canonicalize_remote_source_url(str(file_path or '')))
                if self._is_fileditch_host((parsed.netloc or '').replace('www.', '')) and self._is_fileditch_generic_title(name):
                    return ""
                if self._is_pornhub_host((parsed.netloc or '').replace('www.', '')) and self._is_pornhub_generic_title(name):
                    return ""
        except Exception:
            pass
        return name

    def _prune_recent_file_names(self):
        names = getattr(self, 'recent_file_names', {})
        if not isinstance(names, dict):
            self.recent_file_names = {}
            return False
        keep = {self._recent_file_name_key(path) for path in getattr(self, 'recent_files', [])}
        keep.discard("")
        pruned = {key: value for key, value in names.items() if key in keep and value}
        changed = pruned != names
        if changed:
            self.recent_file_names = pruned
        return changed
    
