    def is_seen(self, file_path):
        """A file is SEEN if:
        - it lives inside C:\\GhostToolbox\\SEEN\\, OR
        - its filename starts with '-'
        The internal marked_videos set is also checked for files moved/tracked this session.
        """
        if not file_path:
            return False
        try:
            jav_key = self._jav_seen_key_for_path(file_path)
            if jav_key and jav_key in (getattr(self, 'seen_url_keys', set()) or set()):
                return True
        except Exception:
            pass
        try:
            if self._is_ftp_url(file_path) and self._ftp_filename_has_seen_prefix(file_path):
                return True
            if self._is_remote_url(file_path) or self._is_remote_folder_entry(file_path) or self._is_ftp_url(file_path):
                keys = self._url_seen_keys_for_path(file_path)
                if keys and (keys & (getattr(self, 'seen_url_keys', set()) or set())):
                    return True
        except Exception:
            pass
        basename = os.path.basename(file_path)
        if basename.startswith('-'):
            return True
        if self._is_seen_folder_path(file_path):
            return True
        return file_path in self.marked_videos

    def _is_seen_by_local_path_state(self, file_path):
        if not file_path:
            return False
        if self._is_remote_url(file_path) or self._is_remote_folder_entry(file_path):
            return False
        basename = os.path.basename(file_path)
        if basename.startswith('-'):
            return True
        if self._is_seen_folder_path(file_path):
            return True
        return file_path in getattr(self, 'marked_videos', set())

    def load_marked_videos(self):
        """Load marked videos and their origins from file"""
        try:
            if os.path.exists(self.marked_videos_file):
                with open(self.marked_videos_file, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                    if isinstance(data, dict):
                        self.marked_videos = set(data.get('paths', []))
                        self.marked_videos_origins = data.get('origins', {})
                    else:
                        # Legacy: plain list
                        self.marked_videos = set(data)
                        self.marked_videos_origins = {}
        except Exception as e:
            print(f"Error loading marked videos: {e}")
            self.marked_videos = set()
            self.marked_videos_origins = {}

    def save_marked_videos(self):
        """Save marked videos and their origins to file"""
        try:
            data = {
                'paths': list(self.marked_videos),
                'origins': getattr(self, 'marked_videos_origins', {})
            }
            with open(self.marked_videos_file, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=2)
        except Exception as e:
            print(f"Error saving marked videos: {e}")

    def load_rename_history(self):
        """Load rename history / undo stack from JSON file, keeping entries up to 30 days old."""
        import time, json
        self._rename_undo_stack = []
        try:
            if os.path.exists(self.rename_history_file):
                with open(self.rename_history_file, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                    if isinstance(data, list):
                        now = time.time()
                        cutoff = 30 * 86400  # 30 days retention
                        valid = []
                        for entry in data:
                            if isinstance(entry, dict) and 'old' in entry and 'new' in entry:
                                ts = entry.get('timestamp', now)
                                if (now - ts) <= cutoff or not entry.get('timestamp'):
                                    valid.append(entry)
                        self._rename_undo_stack = valid[-100:]
        except Exception as e:
            print(f"Error loading rename history: {e}")
            self._rename_undo_stack = []

    def save_rename_history(self):
        """Save rename history / undo stack to JSON file."""
        import json
        try:
            data = getattr(self, '_rename_undo_stack', [])[-100:]
            with open(self.rename_history_file, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=2)
        except Exception as e:
            print(f"Error saving rename history: {e}")

    def _is_seen_folder_path(self, file_path):
        try:
            norm = os.path.normcase(os.path.abspath(str(file_path or '')))
            seen_dir = os.path.normcase(os.path.abspath(r"C:\GhostToolbox\SEEN"))
            return norm == seen_dir or norm.startswith(seen_dir + os.sep)
        except Exception:
            return False

    def _is_ghost_toolbox_path(self, file_path):
        """Return True only for local paths inside C:\\GhostToolbox."""
        try:
            path = str(file_path or '').strip()
            if (
                not path
                or path.startswith("phone://")
                or self._is_remote_url(path)
                or self._is_remote_folder_entry(path)
            ):
                return False
            root = os.path.normcase(os.path.abspath(r"C:\GhostToolbox"))
            norm = os.path.normcase(os.path.abspath(path))
            return os.path.commonpath([root, norm]) == root
        except Exception:
            return False

    def _drive_root_for_path(self, file_path):
        try:
            path = str(file_path or '').strip()
            if not path or path.startswith("phone://"):
                return ''
            drive, _tail = os.path.splitdrive(os.path.abspath(path))
            if not drive:
                return ''
            return drive + os.sep
        except Exception:
            return ''

    def _should_mark_without_moving(self, file_path):
        """Return True for entries that should be remembered/marked in-place.

        Only videos physically under C:\\GhostToolbox are moved to
        C:\\GhostToolbox\\SEEN. Everything else keeps its current location.
        """
        path = str(file_path or '').strip()
        if not path:
            return False
        if path.startswith("phone://"):
            return True
        if self._is_remote_url(path) or self._is_remote_folder_entry(path):
            return True
        if not os.path.exists(path):
            return True
        return not self._is_ghost_toolbox_path(path)

    def _is_marked_without_moving(self, file_path):
        try:
            marked = getattr(self, 'marked_videos', set()) or set()
            if file_path not in marked:
                return False
            basename = os.path.basename(str(file_path or ''))
            return not basename.startswith('-') and not self._is_seen_folder_path(file_path)
        except Exception:
            return False

    def _strip_seen_display_prefix(self, display_name):
        text = str(display_name or '')
        stripped = text.lstrip()
        if stripped.startswith('-'):
            return stripped[1:].lstrip()
        return text

    def _local_seen_display_prefix(self, file_path, display_name):
        text = str(display_name or '')
        is_marked = bool(
            self._is_seen_by_local_path_state(file_path)
            or self._is_marked_without_moving(file_path)
        )
        jav_key = self._jav_seen_key_for_path(file_path)
        if jav_key and jav_key in (getattr(self, 'seen_url_keys', set()) or set()):
            is_marked = True
        if text.lstrip().startswith('-'):
            return text if is_marked else self._strip_seen_display_prefix(text)
        return f"- {text}" if is_marked else display_name

    def bulk_mark_videos(self, rows, mark=True):
        """Mark or unmark multiple rows.
        mark=True  → mark all as SEEN
        mark=False → unmark all
        mark=None  → smart toggle: mark unseen, unmark seen
        The currently playing file is processed last so position is preserved."""
        rows = sorted(set(rows), reverse=True)
        done = 0

        # Remember which files were selected so we can re-select them after
        # (filtering hides/shows rows which clears Qt selection)
        selected_paths = [self.playlist[r] for r in rows if r < len(self.playlist)]

        # Separate the currently playing row so we handle it last
        playing_row = None
        if hasattr(self, 'current_file') and self.current_file:
            for row in rows:
                if row < len(self.playlist) and os.path.normcase(self.playlist[row]) == os.path.normcase(self.current_file):
                    playing_row = row
                    break

        # Save position now before any row processing touches the player
        saved_position = self.media_player.position() if playing_row is not None else 0
        was_playing = (playing_row is not None and
                       self.media_player.playbackState() == QMediaPlayer.PlaybackState.PlayingState)

        for row in rows:
            if row < 0 or row >= len(self.playlist):
                continue
            if row == playing_row:
                continue  # handle after the loop
            file_path = self.playlist[row]
            currently_seen = self.is_seen(file_path)
            desired_mark = (not currently_seen) if mark is None else mark
            if desired_mark == currently_seen:
                continue
            if self.toggle_mark_video(row):
                done += 1

        # Now handle the playing file last
        if playing_row is not None:
            actual_row = None
            for i, p in enumerate(self.playlist):
                if os.path.normcase(p) == os.path.normcase(self.current_file):
                    actual_row = i
                    break
            if actual_row is not None:
                file_path = self.playlist[actual_row]
                currently_seen = self.is_seen(file_path)
                desired_mark = (not currently_seen) if mark is None else mark
                if desired_mark != currently_seen:
                    self.playback_history[file_path] = {'position': saved_position}
                    self._bulk_was_playing = was_playing
                    if self.toggle_mark_video(actual_row):
                        done += 1

        # Restore selection — match by file path since paths may have changed (- prefix added/removed)
        self.playlist_widget.clearSelection()
        sel_model = self.playlist_widget.selectionModel()
        for path in selected_paths:
            basename = os.path.basename(path).lstrip('-').lower()
            for i, p in enumerate(self.playlist):
                if os.path.basename(p).lstrip('-').lower() == basename:
                    sel_model.select(
                        self.playlist_widget.model().index(i, 0),
                        sel_model.SelectionFlag.Select | sel_model.SelectionFlag.Rows
                    )
                    break

        if mark is None:
            action = "Toggled"
        elif mark:
            action = "Marked"
        else:
            action = "Unmarked"
        self.show_osd(f"{action} {done} file{'s' if done != 1 else ''}", duration=2500)

    def _process_ui_wait(self, delay_ms=120):
        QApplication.processEvents()
        if delay_ms <= 0:
            return
        loop = QEventLoop()
        QTimer.singleShot(delay_ms, loop.quit)
        loop.exec()

    def _wait_for_playlist_analysis_release(self, file_path, timeout_ms=1800):
        import time

        deadline = time.monotonic() + (max(0, timeout_ms) / 1000.0)
        target = self._normalize_playlist_path(file_path)
        while time.monotonic() < deadline:
            pending = {
                self._normalize_playlist_path(path)
                for path in getattr(self, '_playlist_analysis_pending', set())
            }
            if target not in pending:
                return True
            self._process_ui_wait(80)
        return target not in {
            self._normalize_playlist_path(path)
            for path in getattr(self, '_playlist_analysis_pending', set())
        }

    def _shell_text_key(self, text):
        raw = str(text or "").replace("&", "").replace("…", "").strip().lower()
        normalized = unicodedata.normalize("NFKD", raw)
        return "".join(ch for ch in normalized if not unicodedata.combining(ch))

    def reveal_in_file_manager(self, path):
        """Reveal a file in the platform file manager, or open its folder."""
        if not path:
            return False
        target = os.path.abspath(path)
        try:
            if os.name == 'nt':
                if os.path.isdir(target):
                    subprocess.Popen(['explorer', os.path.normpath(target)])
                elif os.path.exists(target):
                    subprocess.Popen(f'explorer /select,"{os.path.normpath(target)}"')
                else:
                    parent = os.path.dirname(target)
                    if not parent or not os.path.isdir(parent):
                        raise FileNotFoundError(target)
                    subprocess.Popen(['explorer', os.path.normpath(parent)])
            else:
                folder = target if os.path.isdir(target) else os.path.dirname(target)
                if not folder or not os.path.isdir(folder):
                    raise FileNotFoundError(target)
                subprocess.Popen(['xdg-open', folder])
            return True
        except Exception as exc:
            self.show_osd(f"Explorer open failed: {exc}", duration=3000)
            print(f"Explorer open failed for {target}: {exc}")
            return False

