        msg.setIcon(QMessageBox.Icon.Warning)
        msg.setWindowTitle("Delete Currently Playing File?")
        msg.setText(f"'{base_name}' is currently playing.")
        if selection_count > 1:
            msg.setInformativeText(
                "Delete it to the Recycle Bin and stop playback?\n"
                "Choosing No keeps this file and deletes the other selected files."
            )
        else:
            msg.setInformativeText(
                "Delete it to the Recycle Bin and stop playback?"
            )
        msg.setStandardButtons(QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
        msg.setDefaultButton(QMessageBox.StandardButton.No)
        return msg.exec() == QMessageBox.StandardButton.Yes

