import javhd_integration   # noqa
import familypornhd_integration   # noqa
if __name__ == "__main__":
    import traceback
    import logging

    def _configure_crash_logging():
        """Set up crash logging without letting a bad log path block startup."""
        app_dir = os.path.dirname(os.path.abspath(__file__))
        candidates = [
            os.path.join(app_dir, "antigravity_player_crash.log"),
            os.path.join(os.path.expanduser("~"), "antigravity_player_crash.log"),
            os.path.join(tempfile.gettempdir(), "antigravity_player_crash.log"),
        ]
        for candidate in candidates:
            try:
                os.makedirs(os.path.dirname(candidate), exist_ok=True)
                logging.basicConfig(
                    filename=candidate,
                    level=logging.ERROR,
                    format='%(asctime)s - %(levelname)s - %(message)s',
                    force=True,
                )
                return candidate
            except Exception as exc:
                print(f"Crash log unavailable at {candidate}: {exc}")

        logging.basicConfig(
            level=logging.ERROR,
            format='%(asctime)s - %(levelname)s - %(message)s',
            force=True,
        )
        return None

    log_file = _configure_crash_logging()
    
    def exception_hook(exctype, value, tb):
        """Global exception handler to catch crashes"""
        error_msg = ''.join(traceback.format_exception(exctype, value, tb))
        print(f"\n{'='*60}\nCRASH DETECTED:\n{'='*60}\n{error_msg}")
        logging.error(f"Application crash:\n{error_msg}")
        
        # Try to show error dialog
        try:
            from PyQt6.QtWidgets import QMessageBox
            msg = QMessageBox()
            msg.setIcon(QMessageBox.Icon.Critical)
            msg.setWindowTitle("Application Error")
            msg.setText("The application encountered an error.")
            log_text = f"\n\nLog saved to:\n{log_file}" if log_file else ""
            msg.setInformativeText(f"Error: {str(value)}{log_text}")
            msg.setDetailedText(error_msg)
            msg.exec()
        except:
            pass
    
    # Install exception hook
    sys.excepthook = exception_hook
    
    try:
        if len(sys.argv) > 2 and sys.argv[1] == "--playwright":
            url = sys.argv[2]
            inject_js = None
            if len(sys.argv) > 4 and sys.argv[3] == "--inject-js":
                try:
                    with open(sys.argv[4], 'r', encoding='utf-8') as f:
                        inject_js = f.read()
                except Exception as e:
                    print(f"Error reading js: {e}")
            # Some hoster clones behave differently (or refuse to actually
            # start playback at all) when they detect a headless browser.
            # --headed launches a real, visible Chromium window instead, but
            # positioned far off-screen so nothing actually pops up in front
            # of the person using the app.
            headless_capture = '--headless-capture' in sys.argv
            hidden_headed = ('--headed-hidden' in sys.argv) and not headless_capture
            # --headed-hidden: a real headed engine (not headless — many bot
            # walls fingerprint headless Chromium), but positioned far
            # off-screen and started minimized, so nothing ever appears.
            # --headless-capture is an explicit no-window mode for ordinary
            # HTML5 pages whose player does not require a headed fingerprint.
            run_headed = (('--headed' in sys.argv) or hidden_headed) and not headless_capture
            # --dump-html: always print the final post-click DOM as
            # PAGE_HTML_B64::, even when a media URL was already captured.
            # Mixdrop-style players can rewrite MDCore.wurl into the page on
            # click while the actual media request slips past route()
            # interception (media-pipeline requests are a known route() blind
            # spot), so the caller wants both signals to pick from.
            dump_html = '--dump-html' in sys.argv
            # --click-download: also click visible download-style controls
            # (file-host pages that only reveal the direct link on click).
            click_download = '--click-download' in sys.argv
            # --early-m3u8 (R53): packed-JS HLS embeds (vidara /
            # emturbovid / streamwish). The real stream is the m3u8
            # hls.js fetches; <video> src is blob: so VERIFIED_MEDIA
            # never fires. Exit ~5s after the first m3u8 instead of
            # sitting out the whole watch window.
            early_m3u8 = '--early-m3u8' in sys.argv
            # --referer X (R52): send this Referer on the initial
            # navigation - domain-locked embeds (javclan) only serve
            # their player to the embedding jav site.
            nav_referer = ''
            for _arg_i, _arg_v in enumerate(sys.argv):
                if _arg_v == '--referer' and _arg_i + 1 < len(sys.argv):
                    nav_referer = sys.argv[_arg_i + 1]
                    break
            # --max-watch N: cap the capture loop at N seconds (default 75).
            # File hosts don't need the long pre-roll wait video pages do.
            max_watch = 75
            for _arg_i, _arg_v in enumerate(sys.argv):
                if _arg_v == '--max-watch' and _arg_i + 1 < len(sys.argv):
                    try:
                        max_watch = max(10, min(int(sys.argv[_arg_i + 1]), 120))
                    except Exception:
                        pass

            # ── Guaranteed browser shutdown (R43) ──────────────────────
            # Field bug: when the PARENT app timed a slow capture out and
            # killed this child, the kill only terminated the python
            # process — the off-screen Brave window it launched was left
            # orphaned (the 'finally: browser.close()' below never ran
            # under SIGKILL). Register a hard-close helper for atexit AND
            # for SIGTERM/SIGINT/SIGBREAK so a graceful kill still closes
            # the browser; the parent additionally kills the whole process
            # tree as a last resort.
            _PW_STATE = {'browser': None, 'browser_pid': None}

            def _pw_close_browser_hard():
                _b = _PW_STATE.get('browser')
                _pid = _PW_STATE.get('browser_pid')
                if _b is not None:
                    _PW_STATE['browser'] = None
                    try:
                        _b.close()
                    except Exception:
                        pass
                if _pid:
                    _PW_STATE['browser_pid'] = None
                    try:
                        if os.name == 'nt':
                            subprocess.run(
                                ['taskkill', '/PID', str(_pid), '/T', '/F'],
                                capture_output=True, timeout=10,
                                creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
                        else:
                            os.kill(_pid, 9)
                    except Exception:
                        pass

            def _pw_on_signal(signum, frame):
                _pw_close_browser_hard()
                os._exit(0)

            import atexit as _pw_atexit
            import signal as _pw_signal
            _pw_atexit.register(_pw_close_browser_hard)
            for _pw_sig_name in ('SIGTERM', 'SIGINT', 'SIGBREAK'):
                _pw_sig = getattr(_pw_signal, _pw_sig_name, None)
                if _pw_sig is None:
                    continue
                try:
                    _pw_signal.signal(_pw_sig, _pw_on_signal)
                except Exception:
                    pass

            try:
                from playwright.sync_api import sync_playwright
                import time

                def run_pw():
                    with sync_playwright() as p:
                        launch_args = [
                            "--autoplay-policy=no-user-gesture-required",
                            # The persistent profile is killed at the end of
                            # each capture, so Chromium treats the next launch
                            # as a crash and tries to RESTORE the previous
                            # session's tabs — that is why old capture tabs
                            # piled up in the window. Suppress the restore
                            # bubble; any restored tab is also closed right
                            # after launch below.
                            "--hide-crash-restore-bubble",
                            # Reduces (does not eliminate) the chance a site's
                            # anti-bot check flags navigator.webdriver / other
                            # automation fingerprints and refuses to serve the
                            # real player.
                            "--disable-blink-features=AutomationControlled",
                            "--no-first-run",
                            "--no-default-browser-check",
                            # The pre-roll ad plays audibly in the visible
                            # window below — keep the capture silent.
                            "--mute-audio",
                        ]
                        if run_headed and not hidden_headed:
                            # A REAL, VISIBLE window — deliberately not
                            # minimized/off-screen anymore. Chromium marks
                            # hidden pages via document.visibilityState, and
                            # these players never start (or never finish)
                            # the actual video while the page is hidden, so
                            # a hidden capture only ever saw the pre-roll
                            # ad. With a visible window the ad plays out,
                            # the player advances to the real video, and
                            # the duration check picks it. The window closes
                            # itself when the capture completes.
                            launch_args += [
                                "--window-position=60,60",
                                "--window-size=1280,800",
                            ]
                        elif hidden_headed:
                            # Off-screen, like the missav/eporner capture
                            # (capture.js): a real headed window positioned
                            # far away, so nothing appears on the desktop.
                            # Deliberately NOT minimized: a minimized page
                            # reports document.visibilityState='hidden', and
                            # Cloudflare refuses to pass hidden widgets.
                            # Off-screen pages stay 'visible', so the
                            # challenge completes and clicks still dispatch.
                            launch_args += [
                                "--window-position=-32000,-32000",
                                "--window-size=1280,800",
                            ]

                        chromium_exe = _find_installed_chromium_like_executable()

                        def _try_launch(label, kwargs):
                            try:
                                if kwargs.get('user_data_dir'):
                                    return p.chromium.launch_persistent_context(
                                        headless=not run_headed,
                                        args=launch_args,
                                        **kwargs,
                                    )
                                return p.chromium.launch(
                                    headless=not run_headed,
                                    args=launch_args,
                                    **kwargs,
                                )
                            except Exception as exc:
                                launch_errors.append(f"{label}: {exc}")
                                return None

                        browser = None
                        launch_errors = []
                        # A dedicated persistent profile keeps cookies and
                        # consent-wall acceptance between captures — sites
                        # re-show consent/bot walls on every fresh profile.
                        # If another capture holds the profile lock (parallel
                        # resolutions), fall back to a per-PID one-off profile
                        # and finally to an ephemeral launch.
                        _profile_dir = os.path.join(
                            tempfile.gettempdir(), 'antigravity_player_pw_profile'
                        )
                        _attempts = []
                        if chromium_exe:
                            _attempts.append(
                                (f"persistent:{chromium_exe}",
                                 dict(executable_path=chromium_exe, user_data_dir=_profile_dir))
                            )
                            _attempts.append(
                                (f"persistent-pid:{chromium_exe}",
                                 dict(executable_path=chromium_exe,
                                      user_data_dir=f"{_profile_dir}-{os.getpid()}"))
                            )
                            _attempts.append(
                                (f"ephemeral:{chromium_exe}",
                                 dict(executable_path=chromium_exe))
                            )
                        # No Brave/Chrome/Edge found on this machine (or they
                        # all failed) — fall back to Playwright's own bundled
                        # Chromium. This only works if `playwright install
                        # chromium` has been run at least once; if not, the
                        # error below explains why nothing opened.
                        _attempts.append(("bundled chromium", dict()))
                        for _label, _kwargs in _attempts:
                            browser = _try_launch(_label, _kwargs)
                            if browser is not None:
                                break
                        if browser is None:
                            print(
                                "Playwright error: could not launch any browser. "
                                "Install Brave, Chrome, or Edge, or run "
                                "'playwright install chromium'. Details: "
                                + " | ".join(launch_errors)
                            )
                            return
                        _PW_STATE['browser'] = browser
                        # Announce the browser's OS pid so the parent can
                        # kill a lingering window even if this child dies
                        # first (best effort - private API, any failure is
                        # fine, the parent still tree-kills by our pid).
                        try:
                            _pw_impl = getattr(browser, '_impl_obj', None)
                            _pw_proc = getattr(_pw_impl, '_browser_process', None)
                            if _pw_proc is None:
                                _pw_impl2 = getattr(_pw_impl, '_browser', None)
                                _pw_proc = getattr(_pw_impl2, '_browser_process', None)
                            _pw_pid = getattr(_pw_proc, 'pid', None)
                            if _pw_pid:
                                _PW_STATE['browser_pid'] = int(_pw_pid)
                                print('PW_BROWSER_PID::' + str(int(_pw_pid)))
                                sys.stdout.flush()
                        except Exception:
                            pass
                        page = browser.new_page()
                        # The persistent profile can still restore the last
                        # session's tabs despite the flags — the capture
                        # window must contain ONLY this capture's tab, so
                        # close everything else that came back.
                        try:
                            for _restored in list(browser.pages):
                                if _restored is not page:
                                    try:
                                        _restored.close()
                                    except Exception:
                                        pass
                        except Exception:
                            pass
                        found_url = None
                        # R44: when the FIRST capture fires, for file-host
                        # pages (--click-download) the loop can close early
                        # instead of sitting out the whole watch window.
                        _first_capture_at = None
                        # R53: first .m3u8 / VOE_M3U8 sighting, for
                        # --early-m3u8 embeds that never raise
                        # VERIFIED_MEDIA (hls.js blob: <video> src).
                        _m3u8_at = None
                        # Every distinct playable URL seen during the session,
                        # in capture order. The FIRST hit still wins for the
                        # legacy single-result callers (VOE paths), but the
                        # Mixdrop path parses every MEDIA_URL::/VOE_M3U8::
                        # line so it can probe each candidate and pick a real
                        # one — ad overlays on these players fire their own
                        # .mp4/.m3u8 requests, and first-capture-wins was
                        # locking onto those instead of the actual video.
                        media_urls = []
                        # Announcement tiers: a URL can be re-announced at a
                        # HIGHER tier (e.g. first seen on the network as
                        # MEDIA_URL::, later confirmed playing long-form
                        # content as VERIFIED_MEDIA::) so the parent can rank
                        # the confirmed sighting above everything else.
                        _prefix_tier = {'MEDIA_URL::': 0, 'VOE_M3U8::': 1, 'VERIFIED_MEDIA::': 2}
                        _announced_tier = {}

                        def _announce_media_url(raw_url, prefix='MEDIA_URL::'):
                            nonlocal found_url, _first_capture_at, _m3u8_at
                            u = str(raw_url or '').strip()
                            if not u:
                                return
                            # The page's own URL is NOT a capture. Fileditch
                            # links are .mp4-looking PAGE urls, so the route
                            # hook below announced the Cloudflare challenge
                            # page itself as a "candidate" the instant it
                            # loaded - producing the garbage best-ranked
                            # capture. Never announce the navigated URL.
                            try:
                                _pu, _uu = urlparse(url), urlparse(u)
                                if (_uu.scheme == _pu.scheme
                                        and _uu.netloc == _pu.netloc
                                        and _uu.path == _pu.path):
                                    return
                            except Exception:
                                if u == url:
                                    return
                            tier = _prefix_tier.get(prefix, 0)
                            if _announced_tier.get(u, -1) >= tier:
                                return
                            _announced_tier[u] = tier
                            if u not in media_urls:
                                media_urls.append(u)
                            print(prefix + u)
                            sys.stdout.flush()
                            if found_url is None:
                                found_url = u
                                if _first_capture_at is None:
                                    _first_capture_at = time.time()
                            if (prefix == 'VOE_M3U8::' or '.m3u8' in u.lower()) and _m3u8_at is None:
                                _m3u8_at = time.time()

                        def handle_console(msg):
                            nonlocal found_url, _first_capture_at, _m3u8_at
                            if msg.text.startswith('VOE_M3U8::'):
                                found_url = msg.text
                                if _first_capture_at is None:
                                    _first_capture_at = time.time()
                                if _m3u8_at is None:
                                    _m3u8_at = time.time()
                                print(msg.text)
                                sys.stdout.flush()

                        # FamilyPornHD (and a few file hosts) put a slash
                        # between the file extension and the signed query:
                        # ``...movie.mp4/?v-acctoken=...``.  Match that form,
                        # but not screenshot names such as ``preview.mp4.jpg``.
                        _media_ext_re = re.compile(r'\.(?:mp4|mkv|webm|mov|m4v)(?:/?(?:[?#]|$))', re.IGNORECASE)

                        def handle_request(route, request):
                            req_url = request.url
                            if '.m3u8' in req_url:
                                _announce_media_url(req_url, prefix='VOE_M3U8::')
                            elif _media_ext_re.search(urlparse(req_url).path or ''):
                                _announce_media_url(req_url)
                            route.continue_()

                        # Video.js players on file hosters (Mixdrop especially)
                        # commonly wire the big play button to a popunder ad:
                        # the click both starts playback and window.open()s an
                        # ad. In --headed mode those popups would pile up on
                        # the user's desktop, and some sites then move focus
                        # enough to interrupt playback init. Close them all.
                        def _close_popup(popup):
                            try:
                                popup.close()
                            except Exception:
                                pass

                        page.on("popup", _close_popup)
                        page.on("console", handle_console)
                        page.route("**/*", handle_request)

                        try:
                            _goto_kwargs = {"wait_until": "domcontentloaded",
                                            "timeout": 20000}
                            if nav_referer:
                                _goto_kwargs["referer"] = nav_referer
                            page.goto(url, **_goto_kwargs)
                            if inject_js:
                                page.evaluate(inject_js)
                            try:
                                _pt = page.title() or ''
                                if _pt:
                                    print('PAGE_TITLE::' + _pt[:300])
                                    sys.stdout.flush()
                            except Exception:
                                pass

                            # Make sure THIS tab is the active, visible one —
                            # a background tab is 'hidden' exactly like a
                            # minimized window, and hidden pages never
                            # advance to the real video. (Skipped in
                            # --headed-hidden mode: the window must stay
                            # off-screen.)
                            if not hidden_headed:
                                try:
                                    page.bring_to_front()
                                except Exception:
                                    pass

                            # Report this browser's actual User-Agent: some
                            # file-host CDNs (fileditch's freakingfileditch)
                            # lock the direct link to the UA that requested
                            # it, so the parent must replay the same one.
                            try:
                                print('BROWSER_UA::' + page.evaluate('() => navigator.userAgent'))
                                sys.stdout.flush()
                            except Exception:
                                pass

                            # Also report the page's (non-httpOnly) cookies:
                            # bot-challenge clears (the fileditch 403 wall)
                            # land here, and the parent must send them along
                            # with playback or the CDN 403s again.
                            def _report_cookies():
                                try:
                                    _ck = page.evaluate('() => document.cookie') or ''
                                    if _ck:
                                        print('BROWSER_COOKIES::' + _ck[:3000])
                                        sys.stdout.flush()
                                except Exception:
                                    pass

                            _report_cookies()

                            # Consent/cookie walls (OneTrust, FundingChoice,
                            # generic "Accept") block the player entirely on
                            # some sites until accepted — click them away
                            # before trying to start playback.
                            _consent_selectors = (
                                '#onetrust-accept-btn-handler',
                                'button.fc-cta-consent',
                                'button:has-text("Accept all")',
                                'button:has-text("Accept All")',
                                'button:has-text("ACCEPT")',
                                'button:has-text("I agree")',
                                'button:has-text("Agree")',
                                'button:has-text("Got it")',
                            )

                            def _dismiss_consent():
                                for _sel in _consent_selectors:
                                    try:
                                        _el = page.query_selector(_sel)
                                        if _el and _el.is_visible():
                                            _el.click(timeout=1500)
                                            return True
                                    except Exception:
                                        continue
                                return False

                            _dismiss_consent()

                            _cf_hint_shown = False

                            def _try_click_cloudflare():
                                # Cloudflare's "Verify you are human"
                                # (Turnstile) lives in cross-origin
                                # challenges.cloudflare.com iframes — often
                                # NESTED (widget frame containing the
                                # checkbox frame), so every challenge frame
                                # is tried, not just the first. Three
                                # strategies per call: a real element click
                                # inside whichever frame has one, a
                                # coordinate click on the checkbox zone
                                # inside each challenge frame, and finally a
                                # coordinate click on the host iframe in the
                                # page. Every action prints (the parent
                                # relays child output live), so the console
                                # shows exactly what was attempted. Best
                                # effort: Cloudflare scores interactions, so
                                # a manual click still works as backup — the
                                # capture window is off-screen in the
                                # background; restore it from the taskbar if
                                # the hint below asks.
                                nonlocal _cf_hint_shown
                                try:
                                    frames = list(page.frames)
                                except Exception:
                                    return False
                                cf_frames = [
                                    fr for fr in frames
                                    if 'challenges.cloudflare.com' in str(fr.url or '')
                                ]
                                if not cf_frames:
                                    return False
                                if not _cf_hint_shown:
                                    _cf_hint_shown = True
                                    print('[BROWSER_CLICK] Cloudflare challenge detected - auto-clicking the verify box; if it does not clear in ~10s, open the background browser from the taskbar and click it yourself - the capture keeps waiting')
                                    sys.stdout.flush()
                                # 1) a real, clickable checkbox element in
                                #    any challenge frame
                                for fr in cf_frames:
                                    for sel in ('input[type="checkbox"]',
                                                '[role="checkbox"]',
                                                '.ctp-checkbox-label',
                                                '#challenge-stage label',
                                                'label'):
                                        try:
                                            el = fr.query_selector(sel)
                                            if el and el.is_visible():
                                                el.click(timeout=1500)
                                                print(f'[BROWSER_CLICK] cloudflare: clicked {sel} in {str(fr.url)[:90]}')
                                                sys.stdout.flush()
                                                return True
                                        except Exception:
                                            continue
                                # 2) coordinate click on the checkbox zone
                                #    (left edge, vertical center) inside each
                                #    challenge frame
                                for fr in cf_frames:
                                    try:
                                        fr.click('body', position={'x': 28, 'y': 34}, timeout=1500)
                                        print(f'[BROWSER_CLICK] cloudflare: coordinate-clicked the checkbox zone in {str(fr.url)[:90]}')
                                        sys.stdout.flush()
                                        return True
                                    except Exception:
                                        continue
                                # 3) coordinate click on the host iframe
                                try:
                                    host = page.query_selector(
                                        'iframe[src*="challenges.cloudflare.com"]'
                                    )
                                    if host:
                                        box = host.bounding_box()
                                        if box and box.get('width') and box.get('height'):
                                            page.mouse.click(
                                                box['x'] + 25,
                                                box['y'] + box['height'] / 2,
                                            )
                                            print('[BROWSER_CLICK] cloudflare: coordinate-clicked the widget iframe zone')
                                            sys.stdout.flush()
                                            return True
                                except Exception:
                                    pass
                                return False

                            def _skip_ad():
                                # Pre-roll ads on these players often become
                                # skippable a few seconds in — click any
                                # visible control whose text/class says "skip".
                                try:
                                    return bool(page.evaluate(
                                        """() => {
                                            const els = document.querySelectorAll('button, a, div[role="button"], span[role="button"]');
                                            for (const el of els) {
                                                try {
                                                    const txt = (el.textContent || '').trim().slice(0, 60).toLowerCase();
                                                    let cls = '';
                                                    try { cls = String(el.className && el.className.baseVal !== undefined ? el.className.baseVal : el.className || '').toLowerCase(); } catch (e) {}
                                                    cls += ' ' + (el.id || '').toLowerCase();
                                                    if (txt.indexOf('skip') === -1 && cls.indexOf('skip') === -1)
                                                        continue;
                                                    const r = el.getBoundingClientRect();
                                                    if (r.width < 4 || r.height < 4)
                                                        continue;
                                                    const st = getComputedStyle(el);
                                                    if (st.display === 'none' || st.visibility === 'hidden')
                                                        continue;
                                                    el.click();
                                                    return true;
                                                } catch (e) {}
                                            }
                                            return false;
                                        }"""
                                    ))
                                except Exception:
                                    return False

                            # "Is the big player actively playing right now?"
                            # Only counts LARGE videos — banner/video-box ads
                            # elsewhere on these ad-heavy pages autoplay in
                            # tiny <video> elements and must not make us think
                            # the main player is running.
                            _is_playing_js = """
                                () => {
                                    try {
                                        for (const v of document.querySelectorAll('video')) {
                                            if (v.paused || v.ended || v.readyState < 2)
                                                continue;
                                            const r = v.getBoundingClientRect();
                                            if (r.width >= 320 && r.height >= 180)
                                                return true;
                                        }
                                    } catch (e) {}
                                    return false;
                                }
                            """

                            _play_selectors = [
                                # Order matters: click the REAL player controls
                                # first. Mixdrop-style video.js pages sit an ad
                                # click-catcher (.play-overlay / .player-overlay
                                # anchors) on top of the player; clicking that
                                # first navigated the page to an ad so the
                                # actual .vjs-big-play-button was never pressed
                                # and nothing was ever captured. Those ad-layer
                                # selectors stay last as a fallback only.
                                ".vjs-big-play-button",
                                "video",
                                "button.play",
                                ".jw-display-icon-container",
                                ".play-overlay",
                                ".player-overlay",
                            ]

                            def _click_play():
                                # The element-picker route often lands inside
                                # the player iframe, so try the top page and
                                # every child frame before giving up.
                                try:
                                    _play_contexts = [page] + [
                                        _frame for _frame in page.frames if _frame is not page
                                    ]
                                except Exception:
                                    _play_contexts = [page]
                                for _ctx in _play_contexts:
                                    for _sel in _play_selectors:
                                        try:
                                            _el = _ctx.query_selector(_sel)
                                            if _el:
                                                _el.click(timeout=3000)
                                                return True
                                        except Exception:
                                            continue
                                return False

                            def _click_download():
                                """For --click-download (file hosts): click the
                                page's real download affordances. Anchors whose
                                href is a media file / download path are the
                                trustworthy ones; class/id-styled buttons are a
                                second pass (ad banners also say "Download", so
                                no text matching). Clicking the real anchor
                                navigates to the file, which route() captures
                                as MEDIA_URL::."""
                                if not click_download:
                                    return False
                                try:
                                    clicked = page.evaluate(
                                        """() => {
                                            const mediaRe = /\\.(mp4|mkv|webm|mov|m4v|mpg|mpeg|avi|flv|ts|mp3|m4a|aac|flac|wav|ogg|opus)(?:\\/?(?:[?#]|$))/i;
                                            const anchors = Array.from(document.querySelectorAll('a[href]'));
                                            for (const a of anchors) {
                                                try {
                                                    const href = a.href || '';
                                                    if (!href || href.startsWith('javascript:'))
                                                        continue;
                                                    if (mediaRe.test(href) || /(?:\\/|\\?)(?:download|get-file|dl\\b|file\\/)/i.test(href)) {
                                                        const r = a.getBoundingClientRect();
                                                        if (r.width < 4 || r.height < 4)
                                                            continue;
                                                        a.click();
                                                        return true;
                                                    }
                                                } catch (e) {}
                                            }
                                            for (const el of document.querySelectorAll('button, a.button, a.btn, input[type="button"]')) {
                                                try {
                                                    const idcls = ((el.id || '') + ' ' + (el.className || '')).toLowerCase();
                                                    if (idcls.indexOf('download') === -1)
                                                        continue;
                                                    const r = el.getBoundingClientRect();
                                                    if (r.width < 4 || r.height < 4)
                                                        continue;
                                                    el.click();
                                                    return true;
                                                } catch (e) {}
                                            }
                                            return false;
                                        }"""
                                    )
                                    return bool(clicked)
                                except Exception:
                                    return False

                            # The video.js player is often built by a script
                            # that runs after domcontentloaded, so the button
                            # may not exist for a moment. Give the real play
                            # controls a few seconds to appear before the
                            # first click instead of clicking into a page that
                            # hasn't finished initializing its player.
                            try:
                                page.wait_for_selector(
                                    ".vjs-big-play-button, video, button.play, .jw-display-icon-container",
                                    timeout=8000,
                                )
                            except Exception:
                                pass

                            # Actively click the play button on VOE/javclan/Mixdrop
                            # pages so the video actually starts fetching its
                            # stream — many of these players (video.js-based
                            # ones especially, e.g. Mixdrop's .vjs-big-play-button)
                            # never issue that request until a real click happens.
                            _click_play()
                            # File-host mode: also poke the download controls
                            # right away — many hosts reveal the direct link
                            # only on that click.
                            _click_download()

                            # Reads every place a player stashes the real media
                            # URL once playback starts: MDCore.wurl (Mixdrop
                            # only writes it into the page AFTER the click),
                            # each <video>'s currentSrc/src (blob: = hls.js
                            # MediaSource, useless outside the page), and the
                            # hls.js / Video.js engine objects that keep the
                            # underlying manifest URL even when video.src is a
                            # blob:. Each entry carries the <video>'s OWN
                            # duration/dimensions when known — that's how the
                            # real video gets told apart from the pre-roll ad
                            # (an ad is a few seconds / low-res; the actual
                            # clip reports tens of minutes or HD dimensions).
                            _dom_media_js = """
                                () => {
                                    const found = [];
                                    const push = (u, dur, w, h) => {
                                        if (!u || typeof u !== 'string') return;
                                        u = u.trim();
                                        if (!u || u.startsWith('blob:') || u.startsWith('data:')) return;
                                        // The DevTools element picker also
                                        // walks poster/thumbnail attributes;
                                        // never turn those images into media
                                        // candidates, including names such as
                                        // preview_1080p.mp4.jpg.
                                        if (/\\.(?:jpg|jpeg|png|gif|webp|svg|ico|bmp|avif)(?:[/?#]|$)/i.test(u)) return;
                                        const rec = found.find(f => f.u === u);
                                        if (rec) {
                                            rec.dur = Math.max(rec.dur || 0, dur || 0);
                                            rec.w = Math.max(rec.w || 0, w || 0);
                                            rec.h = Math.max(rec.h || 0, h || 0);
                                            return;
                                        }
                                        found.push({u: u, dur: dur || 0, w: w || 0, h: h || 0});
                                    };
                                    try { push(window.MDCore && window.MDCore.wurl, 0, 0, 0); } catch (e) {}
                                    const mediaAttrs = [
                                        'src', 'data-src', 'data-file', 'data-video', 'data-url',
                                        'data-media', 'data-source', 'data-stream', 'data-hls', 'data-m3u8'
                                    ];
                                    const scanMediaNode = (node) => {
                                        try {
                                            if (!node || !node.querySelectorAll) return;
                                            for (const el of node.querySelectorAll('*')) {
                                                for (const attr of mediaAttrs) {
                                                    try {
                                                        const value = el.getAttribute(attr);
                                                        if (value) push(value, 0, 0, 0);
                                                    } catch (e) {}
                                                }
                                                // The player can be a web
                                                // component; DevTools shows
                                                // its <video> inside an open
                                                // shadow root, which a plain
                                                // document.querySelectorAll()
                                                // does not visit.
                                                try {
                                                    if (el.shadowRoot) scanMediaNode(el.shadowRoot);
                                                } catch (e) {}
                                            }
                                        } catch (e) {}
                                    };
                                    try {
                                        for (const v of document.querySelectorAll('video')) {
                                            let d = 0;
                                            try { if (isFinite(v.duration)) d = v.duration; } catch (e) {}
                                            push(v.currentSrc, d, v.videoWidth, v.videoHeight);
                                            push(v.src, d, v.videoWidth, v.videoHeight);
                                            try { if (v.hls && v.hls.url) push(v.hls.url, d, v.videoWidth, v.videoHeight); } catch (e) {}
                                            try { if (v.player && v.player.hls && v.player.hls.url) push(v.player.hls.url, d, v.videoWidth, v.videoHeight); } catch (e) {}
                                            try {
                                                for (const source of v.querySelectorAll('source')) {
                                                    push(source.src || source.getAttribute('src'), d, v.videoWidth, v.videoHeight);
                                                }
                                            } catch (e) {}
                                        }
                                        for (const source of document.querySelectorAll('source')) {
                                            push(source.src || source.getAttribute('src'), 0, 0, 0);
                                        }
                                        // Also inspect the containing divs and
                                        // player data attributes, matching the
                                        // DevTools element-picker path.
                                        scanMediaNode(document);
                                    } catch (e) {}
                                    try {
                                        if (window.videojs && window.videojs.players) {
                                            for (const p of Object.values(window.videojs.players)) {
                                                try { if (p && p.cache_ && p.cache_.src) push(p.cache_.src, 0, 0, 0); } catch (e) {}
                                                try { if (p && p.currentSource) { const cs = p.currentSource(); if (cs && cs.src) push(cs.src, 0, 0, 0); } } catch (e) {}
                                            }
                                        }
                                    } catch (e) {}
                                    try {
                                        if (window.jwplayer) {
                                            for (const el of document.querySelectorAll('.jwplayer')) {
                                                try {
                                                    const api = window.jwplayer(el.id);
                                                    if (api && api.getPlaylistItem) {
                                                        const item = api.getPlaylistItem();
                                                        if (item && item.file) push(item.file, 0, 0, 0);
                                                    }
                                                } catch (e) {}
                                            }
                                        }
                                    } catch (e) {}
                                    try {
                                        for (const a of document.querySelectorAll('a[href]')) {
                                            const href = a.href || '';
                                            if (!href)
                                                continue;
                                            if (/\\.(?:mp4|mkv|webm|mov|m4v|mpg|mpeg|avi|flv|ts|mp3|m4a|aac|flac|wav|ogg|opus)(?:\\/?(?:[?#]|$))/i.test(href)
                                                    || href.indexOf('freakingfileditch') !== -1
                                                    || /(?:\\/|\\?)(?:download|get-file|dl\\b|file\\/)/i.test(href)) {
                                                push(href, 0, 0, 0);
                                            }
                                        }
                                    } catch (e) {}
                                    return found.length ? found : null;
                                }
                            """

                            # Pre-roll ads on these players load AND play
                            # first — the real video's URL only appears once
                            # the ad finishes (6-30s in). The old "stop 3s
                            # after the first capture" logic grabbed the ad
                            # and closed the browser before the actual video
                            # ever started. Now the loop keeps watching for
                            # the whole window and exits early when a
                            # <video> is genuinely playing long-form content
                            # (real duration / HD dimensions) — that capture
                            # is announced as VERIFIED_MEDIA:: and wins in
                            # the parent's ranking. --early-m3u8 (R53) is
                            # the other early-exit: packed-JS HLS embeds
                            # never raise VERIFIED_MEDIA (blob: src).
                            _verified_media_url = None
                            # url -> (duration_s, width, height) as measured from
                            # the page's own <video> elements — announced to the
                            # parent as MEDIA_DUR:: lines so it can tell a 6s
                            # pre-roll ad from the real video even without a
                            # duration-VERIFIED sighting.
                            _measured = {}
                            for _i in range(max_watch):
                                # <video> element requests are a known blind spot
                                # for route()-based interception (Chromium's media
                                # pipeline can fetch them outside the normal
                                # Fetch/XHR path route() hooks), so also just read
                                # the resolved src straight off the DOM — this is
                                # what actually shows up for sites like Mixdrop
                                # that set player.src()/video.src on click.
                                # DevTools can land on a video inside an
                                # iframe.  Evaluate the same DOM probe in
                                # every accessible frame, not only the top
                                # document; cross-origin frames are still
                                # readable through Playwright's frame API.
                                dom_recs = []
                                try:
                                    _dom_frames = list(page.frames)
                                except Exception:
                                    _dom_frames = [page]
                                for _dom_frame in _dom_frames:
                                    try:
                                        dom_recs.extend(_dom_frame.evaluate(_dom_media_js) or [])
                                    except Exception:
                                        continue
                                for _rec in dom_recs:
                                    _u = str((_rec or {}).get('u') or '').strip()
                                    if not _u:
                                        continue
                                    try:
                                        _dur = float(_rec.get('dur') or 0)
                                    except Exception:
                                        _dur = 0.0
                                    try:
                                        _w = int(_rec.get('w') or 0)
                                        _h = int(_rec.get('h') or 0)
                                    except Exception:
                                        _w = _h = 0
                                    try:
                                        if _dur > 0 and (_u not in _measured or _measured[_u][0] < _dur):
                                            _measured[_u] = (_dur, _w, _h)
                                            print('MEDIA_DUR::' + _u + '|' + str(int(_dur)) + '|' + str(_w) + '|' + str(_h))
                                            sys.stdout.flush()
                                    except Exception:
                                        pass
                                    _is_long_content = (
                                        _dur >= 45.0
                                        or (_h >= 480 and _dur >= 20.0)
                                        or (_w >= 960 and _dur >= 20.0)
                                    )
                                    if _is_long_content and _verified_media_url is None:
                                        _verified_media_url = _u
                                        _announce_media_url(_u, prefix='VERIFIED_MEDIA::')
                                    else:
                                        _announce_media_url(_u)
                                if (click_download and found_url is not None
                                        and _first_capture_at is not None
                                        and (time.time() - _first_capture_at) >= 8.0):
                                    # R44 file-host captures (fileditch): the
                                    # file URL fired, but a download page has
                                    # no <video> that could ever raise
                                    # VERIFIED_MEDIA — the loop used to sit
                                    # out the whole watch window with the
                                    # browser tab open in the taskbar. Close
                                    # early instead.
                                    print('[BROWSER_CLICK] file-host capture complete - closing the browser early')
                                    sys.stdout.flush()
                                    break
                                if (early_m3u8 and _m3u8_at is not None
                                        and (time.time() - _m3u8_at) >= 5.0):
                                    # R53 embed-HLS (vidara / emturbovid):
                                    # hls.js fetches the real m3u8 then
                                    # plays it via a blob: <video> src, so
                                    # VERIFIED_MEDIA never fires. Close a
                                    # few seconds after the m3u8 so sibling
                                    # variants can still be announced.
                                    print('[BROWSER_CLICK] embed-HLS m3u8 captured - closing the browser early')
                                    sys.stdout.flush()
                                    break
                                if _verified_media_url:
                                    break
                                # Keep the page genuinely visible/active — some
                                # players pause again if the tab loses focus
                                # mid-ad — and re-dismiss any consent wall that
                                # appeared after an ad navigation.
                                if _i in (2, 20, 45):
                                    if not hidden_headed:
                                        try:
                                            page.bring_to_front()
                                        except Exception:
                                            pass
                                    _dismiss_consent()
                                    _report_cookies()
                                # Try the ad's Skip button periodically — many
                                # pre-rolls become skippable a few seconds in,
                                # and skipping jumps straight to the real video.
                                if _i % 3 == 1:
                                    _skip_ad()
                                # Cloudflare "verify you are human": try the
                                # auto-click a few times, spaced out — a
                                # repeated machine-gun click would only hurt
                                # the trust score. The human can always click
                                # it in between; the loop keeps waiting.
                                if _i in (1, 3, 6, 10, 16, 24, 35, 50, 70, 95):
                                    _try_click_cloudflare()
                                if click_download and _i % 4 == 2:
                                    _click_download()
                                # Click play ONLY when the big player is not
                                # actively playing, and space the clicks out.
                                # Re-clicking every ~5s while an ad plays
                                # RE-ARMS a fresh pre-roll on these ad-heavy
                                # players — the earlier click storm cycled ads
                                # forever and the real video never started.
                                if _i in (4, 15, 30, 50, 65):
                                    try:
                                        _playing = page.evaluate(_is_playing_js)
                                    except Exception:
                                        _playing = False
                                    if not _playing:
                                        _click_play()
                                time.sleep(1)

                            # Nothing showed up on the network or in the DOM —
                            # some Mixdrop mirrors rewrite MDCore.wurl into a
                            # <script> block on click instead. Dump the post-click
                            # page so the caller can run its normal HTML
                            # extraction against it. (--dump-html asks for this
                            # even when an unverified URL WAS captured, for the
                            # same static-scan fallback. A duration-verified
                            # result is complete and skips this extra snapshot.)
                            if not found_url or (dump_html and not _verified_media_url):
                                try:
                                    html_content = page.content()
                                    b64 = base64.b64encode(
                                        html_content.encode('utf-8', errors='ignore')
                                    ).decode('ascii')
                                    print('PAGE_HTML_B64::' + b64)
                                    sys.stdout.flush()
                                except Exception as e:
                                    print(f"Error capturing page content: {e}")
                        except Exception as e:
                            print(f"Error navigating: {e}")
                        finally:
                            # close() plus a belt-and-braces pid tree-kill
                            # (see _pw_close_browser_hard): close() can hang
                            # or leave the window alive on a modal/blocked
                            # page, and that window inherits our stdout —
                            # the parent would then block on the pipe
                            # forever (browser stuck open, flow stuck).
                            _pw_close_browser_hard()

                run_pw()
            except Exception as e:
                print(f"Playwright error: {e}")

            sys.exit(0)

        app = QApplication(sys.argv)
        
        player = VideoPlayer()
        player.show()

        # Register .agpl file association on Windows (once per run, cheap)
        VideoPlayer.register_file_association()

        # Open playlist or media file passed on the command line (double-click)
        if len(sys.argv) > 1:
            arg = sys.argv[1]
            if player._is_remote_url(arg):
                QTimer.singleShot(200, lambda: player.queue_add_urls_to_playlist_text(arg, request_source='argv'))
            else:
                ext = os.path.splitext(arg)[1].lower()
                if ext in ('.agpl', '.json', '.m3u', '.m3u8', '.xspf'):
                    QTimer.singleShot(200, lambda: player.load_playlist_file(arg))
                elif ext in IMAGE_EXTENSIONS + VIDEO_EXTENSIONS + AUDIO_EXTENSIONS + ARCHIVE_EXTENSIONS:
                    QTimer.singleShot(200, lambda: player.set_media(arg))

        sys.exit(app.exec())
    except Exception as e:
        logging.error(f"Failed to start application: {e}\n{traceback.format_exc()}")
        print(f"Fatal error: {e}")
        raise
